let S={settings:null,cards:[],chats:[],letters:[],moments:[],annivs:[],periods:[],audios:[],misc:{},assets:{},pickup:{on:false,prob:30,items:[]},aiModels:[],aiCurrent:"",aiLogs:[],worldbook:{},voiceLib:[],voiceCfgs:[],voiceCfgCurrent:"",divine:[]};
const SAVEKEYS=["settings","cards","chats","letters","moments","annivs","periods","audios","misc","assets","pickup","aiModels","aiCurrent","aiLogs","worldbook","voiceLib","voiceCfgs","voiceCfgCurrent","divine"];
let saveT={};
let SNAP={};      /* 寮€鏈烘椂鍚勫垪琛ㄧ殑鍘熸牱蹇収锛氬啓涔嬪墠鐢ㄥ畠鍒ゆ柇"鏄笉鏄鍙樻垚绌虹殑" */
/* ★ 数据安全：万一某个键「读」失败了（存储繁忙/被占用/出错），这时内存里是空的默认值，
   如果再写回去就会把原本好好的聊天记录清空 —— 这正是"更新后丢聊天记录"的根因。
   现在：读失败的键会记下来，本次会话不再写它；并且写之前如果发现某个列表要变成 0 条，
   会先把原来的内容存一份 __bak 备份（设置 → 存储 可以恢复）。 */
const KV_ERR={__kvErr:1};
let kvBad={},_kvBadShown=false;
function kvBadNote(k){
 if(_kvBadShown)return;_kvBadShown=true;
 try{toast("读取「"+k+"」失败，为避免覆盖已暂停保存；请把星笺完全关掉重开一次")}catch(e){}}
function save(k){
 if(kvBad[k]){kvBadNote(k);return}
 clearTimeout(saveT[k]);
 saveT[k]=setTimeout(function(){
  saveT[k]=null;
  try{
   const snap=(typeof SNAP!=="undefined")?SNAP[k]:null;
   const nw=S[k];
   if(snap&&Array.isArray(snap)&&snap.length>=20&&Array.isArray(nw)&&nw.length===0){
    try{kvSet(k+"__bak",snap)}catch(e){}
    try{toast("「"+k+"」要变成空的了，已先备份一份（设置 → 存储 可恢复）")}catch(e){}
   }
  }catch(e){}
  kvSet(k,S[k]);
 },250)}
/* 关闭/切到后台前，把所有还没落盘的改动立刻写入，避免"改完马上关页面"丢设置 */
function saveFlush(){for(const k in saveT){if(saveT[k]){clearTimeout(saveT[k]);saveT[k]=null;try{kvSet(k,S[k])}catch(e){}}}}
if(typeof window!=="undefined"){
 window.addEventListener("pagehide",saveFlush);
 window.addEventListener("beforeunload",saveFlush);
 document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden")saveFlush()});
}
function getPath(o,p){return p.split(".").reduce((a,b)=>a?a[b]:undefined,o)}
function setPath(o,p,v){const ks=p.split(".");let t=o;for(let i=0;i<ks.length-1;i++){t=t[ks[i]]||(t[ks[i]]={})}t[ks[ks.length-1]]=v}
function deepMerge(base,src){if(!src||typeof src!=="object"||Array.isArray(src))return src===undefined?base:src;if(Array.isArray(base))return src;const out={...base};for(const k in src){out[k]=(k in base)?deepMerge(base[k],src[k]):src[k]}return out}
const cardsOf=cat=>S.cards.filter(c=>c.cat===cat);
/* 屏蔽：单条字卡被屏蔽，或所属分组被屏蔽 */
function isBlocked(c){if(!c)return false;if(c.blocked)return true;const bg=(S.misc&&S.misc.blockGroups&&S.misc.blockGroups[c.cat])||[];return !!c.group&&bg.indexOf(c.group)>=0}
const cardTexts=cat=>cardsOf(cat).filter(c=>c.type==="text"&&!isBlocked(c)).map(c=>c.content);
/* ================= 灵感拾取 ================= */
/* 拾取内容归属于「当前人物」（本应用只有一个 TA），开启时同步进入其卡池（字卡库「灵感拾取」分类） */
const PICKUP_CAT="灵感拾取";
function pkState(){if(!S.pickup||typeof S.pickup!=="object")S.pickup={on:false,prob:30,items:[]};const p=S.pickup;
 if(typeof p.on!=="boolean")p.on=false;if(p.prob==null)p.prob=30;if(!Array.isArray(p.items))p.items=[];return p}
const pkCardId=id=>"pk_"+id;
/* 让人物卡池与拾取记录保持一致：开启则逐条入库，关闭则从卡池移除（记录保留） */
function pkSyncPool(){const p=pkState();S.cards=(S.cards||[]).filter(c=>c.cat!==PICKUP_CAT);
 if(p.on)p.items.forEach(it=>S.cards.push({id:pkCardId(it.id),cat:PICKUP_CAT,type:"text",content:it.text,group:"",pickup:true,pid:it.id}))}
/* 由「对方（TA）」随机拾取：仅在开启时、按概率、且内容为新的文本时入库 */
/* 由「对方（TA）」随机拾取灵感：从**我发的**聊天消息里随机挑（TA 自己的消息不拾取），
   仅在开启时、按概率、且内容和已有字卡不重复时入库，并同步进 TA 的字卡池「灵感拾取」分类。 */
function pkPickup(m){if(!m||m.type!=="text"||m.nopick||m.from!=="me")return;const p=pkState();if(!p.on||!chance(p.prob))return;
 const raw=String(m.text||"").trim();if(!raw||raw.length>200)return;
 if(!/[\u4e00-\u9fa5A-Za-z0-9]/.test(raw))return;
 const known=[];S.cards.forEach(c=>{if(c.type==="text"&&c.cat!==PICKUP_CAT)known.push(c.content)});p.items.forEach(it=>known.push(it.text));
 if(known.indexOf(raw)>=0)return;
 const it={id:uid(),ts:Date.now(),from:"me",text:raw,name:(S.settings&&S.settings.myName)||"我"};
 p.items.push(it);
 S.cards.push({id:pkCardId(it.id),cat:PICKUP_CAT,type:"text",content:raw,group:"",pickup:true,pid:it.id});
 save("pickup");save("cards")}
/* ================= WebAudio sounds ================= */
let AC=null;
const ac=()=>{if(!AC){const C=window.AudioContext||window.webkitAudioContext;if(C)AC=new C()}if(AC&&AC.state==="suspended")AC.resume();return AC};
function tone(f,t0,dur,type,vol,glide){const a=ac();if(!a)return;type=type||"sine";vol=Math.min(.95,(vol==null?.3:vol)*SFX_GAIN*SFX_BOOST);const o=a.createOscillator(),g=a.createGain(),t=a.currentTime+t0;o.type=type;o.frequency.setValueAtTime(f,t);if(glide)o.frequency.exponentialRampToValueAtTime(glide,t+dur);g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(vol,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(a.destination);o.start(t);o.stop(t+dur+.05)}
function noiseHit(t0,dur,vol,fc){const a=ac();if(!a)return;const n=Math.floor(a.sampleRate*dur),b=a.createBuffer(1,n,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);const s=a.createBufferSource();s.buffer=b;const f=a.createBiquadFilter();f.type="bandpass";f.frequency.value=fc||2500;const g=a.createGain();g.gain.value=Math.min(.95,(vol==null?.3:vol)*SFX_GAIN*SFX_BOOST);s.connect(f);f.connect(g);g.connect(a.destination);s.start(a.currentTime+t0)}
/* 内置音效音量：SFX_GAIN 整体调大；SFX_BOOST 为单次播放的额外增益（消息类用） */
let SFX_GAIN=2.1,SFX_BOOST=1;
const SYNTH={
 "叮咚":()=>{tone(880,0,.16,"sine",.3);tone(660,.17,.3,"sine",.28)},
 "温馨铃":()=>[523,587,659,784,659,880].forEach((f,i)=>tone(f,i*.22,.4,"sine",.22)),
 "晨曦铃":()=>[392,523,659,784,1047,1318].forEach((f,i)=>tone(f,i*.16,.5,"triangle",.2)),
 "松间铃":()=>[2093,2637,3136,2349,2794].forEach((f,i)=>tone(f,i*.24+Math.random()*.06,1.1,"sine",.12)),
};
const SND_MSG=["静音","叮咚"];
const SND_RING=["静音","温馨铃","晨曦铃","松间铃"];
let customUrlCache={};
function playCustom(block){const c=S.settings.sound[block].custom;if(!c||!c.blob)return;let u=customUrlCache[block];if(!u){u=URL.createObjectURL(c.blob);customUrlCache[block]=u}const a=new Audio(u);a.play().catch(()=>{})}
function playSoundName(block,name){if(!name||name==="静音")return;const cust=S.settings.sound[block].custom;if(cust&&(name==="自定义"||name===cust.name)){playCustom(block);return}const f=SYNTH[name];if(f)f()}
/* 试听：与总开关无关（用户主动点选时始终发声） */
function previewSound(block){const s=S.settings.sound;SFX_BOOST=(block==="ta"||block==="me")?1.25:1;try{playSoundName(block,s[block].sel)}finally{SFX_BOOST=1}}
/* 自动播放：受总开关控制；消息类（TA/我 发送消息）音量再放大一档 */
function playBlock(block){const s=S.settings.sound;if(!s.on)return;SFX_BOOST=(block==="ta"||block==="me")?1.25:1;try{playSoundName(block,s[block].sel)}finally{SFX_BOOST=1}}
let ringTimer=null;
function startRing(){stopRing();const s=S.settings.sound;if(!s.on||s.ring.sel==="静音")return;SFX_BOOST=1;playSoundName("ring",s.ring.sel);ringTimer=setInterval(()=>playSoundName("ring",s.ring.sel),2600)}
function stopRing(){if(ringTimer){clearInterval(ringTimer);ringTimer=null}}
