function openSheet(html,center){const m=$("#modal");m.className=center?"on center":"on";const sh=m.querySelector(".sheet");sh.className="sheet";sh.innerHTML=html;return sh}
function closeModal(){const m=$("#modal");m.className="";const sh=m.querySelector(".sheet");sh.className="sheet";sh.innerHTML=""}
/* 通用上传确认弹窗：备注输入 + 取消 / 确定（不允许静默上传） */
function uploadDialog(title,onOk){openSheet('<div class="mtitle center">'+esc(title)+'</div>'+
 '<input id="upnote" placeholder="备注 / 描述（可选）">'+
 '<div class="btnrow center" style="margin-top:12px"><button class="btn" data-r="x">取消</button><button class="btn pri" data-r="ok">确定</button></div>',true);
 $("#modal .sheet").onclick=e=>{const b=e.target.closest("[data-r]");if(!b)return;const note=($("#upnote")||{}).value||"";closeModal();if(b.dataset.r==="ok")onOk(note)}}
$("#modal").addEventListener("click",e=>{if(e.target.id==="modal"&&!e.currentTarget.classList.contains("stick")){try{avPanel=false}catch(_){};closeModal()}});
function confirmDlg(text,okLabel,danger){return new Promise(res=>{const sh=openSheet('<div class="mtitle center">'+esc(text)+'</div>'+'<div class="btnrow center"><button class="btn" data-r="0">取消</button><button class="btn '+(danger?"danger":"pri")+'" data-r="1">'+esc(okLabel||"确定")+"</button></div>",true);sh.classList.add("fit");sh.onclick=e=>{const b=e.target.closest("[data-r]");if(!b)return;const r=b.dataset.r==="1";closeModal();res(r)}})}
function actionSheet(title,opts){return new Promise(res=>{openSheet('<div class="mtitle">'+esc(title)+'<button class="ibtn" data-i="-1">'+ico("close")+"</button></div>"+opts.map((o,i)=>'<button class="row btn" style="border:none;background:none;width:100%;text-align:left;justify-content:flex-start" data-i="'+i+'">'+esc(o)+"</button>").join(""));$("#modal").querySelector(".sheet").onclick=e=>{const b=e.target.closest("[data-i]");if(!b)return;closeModal();res(+b.dataset.i)}})}
