   if(m)return [parseInt(m[1],16),parseInt(m[2],16),parseInt(m[3],16)];
   const m2=c.match(/rgba?\((\d+)[,\s]+(\d+)[,\s]+(\d+)/i);
   if(m2)return [ +m2[1],+m2[2],+m2[3] ];
