/* 让 AI 按人物设定写一句回复文本（A / B 共用） */
async function aiWriteReply(myText){const ar=S.settings.aiReply;const cfg=aiActive();if(!cfg||!cfg.apiKey)return null;
 const sys=buildAISystemPrompt("chat");
 let up="用户说："+(myText||"（没有说话）")+"\n请以角色的身份回复，只回这一句（不要解释、不要加引号）。";
 if(ar.allowNoReply)up+=" 如果这一轮不想理会，只回复 -1。";
 let out=String(await aiRequest(cfg,[{role:"system",content:sys},{role:"user",content:up}],{max_tokens:160,temperature:0.8})).trim();
 /* 说明：流式响应已移除，这里不再需要「流式解析为空就关流重试」的兜底 */
 return out}
function aiFailToast(){toast("AI 调用未成功，已回退为本地回复（可到「AI 调用记录」查看原因）")}
/* 发送一条语音消息：气泡含 播放键 / 时长 / 转写文本 */
async function sendVoiceReply(text){const t=String(text||"").trim();if(!t)return;
 try{toast("正在生成语音…");const blob=await minimaxTTS(t);const dur=voiceDur(blob);
  showTyping(false);pushChat({from:"ta",type:"voice",data:blob,dur,text:t});playBlock("ta");
  try{new Audio(URL.createObjectURL(blob)).play()}catch(e){}
 }catch(e){toast("语音生成失败："+(e&&e.message||e));showTyping(false);if(t){pushChat({from:"ta",type:"text",text:t});playBlock("ta")}}}
/* A：AI + 语音 → 先想后说 */
async function aiVoiceReply(myText){const cfg=aiActive();if(!cfg||!cfg.apiKey)return localVoiceReply(myText);
 showTyping(true,120000);
 try{const out=await aiWriteReply(myText);const ar=S.settings.aiReply;
  if(ar.allowNoReply&&out&&/(^|[^\d])-1([^\d]|$)/.test(out)){showTyping(false);markMeRead();pushChat({type:"sys",text:"TA 这轮没接话，已读不回"});return}
  if(!out){aiFailToast();localVoiceReply(myText);return}
  await sendVoiceReply(out);
 }catch(e){showTyping(false);aiFailToast();localVoiceReply(myText)}}
/* C：仅语音 → 从主字卡池抽一条转语音 */
async function localVoiceReply(){const pool=cardTexts("主字卡").concat(cardTexts(PICKUP_CAT));const t=pool.length?pick(pool):"在呢";await sendVoiceReply(t)}
/* B：仅 AI → 纯文字回复（绝不发语音） */
async function aiReplyFlow(myText){const cfg=aiActive();if(!cfg||!cfg.apiKey)return localTaReply(myText);
 showTyping(true,90000);
 try{
  const out=await aiWriteReply(myText);showTyping(false);const ar=S.settings.aiReply;
  if(ar.allowNoReply&&out&&/(^|[^\d])-1([^\d]|$)/.test(out)){markMeRead();pushChat({type:"sys",text:"TA 这轮没接话，已读不回"});return}
  if(!out){aiFailToast();localTaReply(myText);return}
  pushChat({from:"ta",type:"text",text:out});playBlock("ta");afterTaText();
 }catch(e){showTyping(false);aiFailToast();localTaReply(myText)}
}
