PAGES.letteredit={html(){const nm=esc(S.settings.taName||"TA");const rep=_le.mode==="reply";
 const l=rep?S.letters.find(function(x){return x.id===_le.replyId}):null;
 return phead(rep?("回信 · 给 "+nm):("写信 · 给 "+nm))+
  (rep&&l?'<div class="mlcard"><div class="mlch"><b>'+esc(nm)+'</b><span class="mltime">'+mailDate(l.ts)+'</span></div>'+(l.title?'<div class="mlct">'+esc(l.title)+"</div>":"")+'<div class="mlcc">'+esc(l.content)+"</div>"+(l.sticker?'<img class="mlst" src="'+l.sticker+'">':"")+"</div>":"")+
  '<div class="lebtns"><button class="ibtn" data-act="letter-emo" title="表情包">'+ico("sticker")+'</button><button class="ibtn" data-act="letter-img" title="图片">'+ico("img")+"</button></div>"+
  '<div class="mlcard edit"><div class="mlch"><b>'+esc(rep?"我的回信":(S.settings.myName||"我"))+'</b><span class="mltime">正在写…</span></div>'+
   '<input id="lt2" class="letitle" placeholder="标题（可空）" enterkeyhint="next">'+
   '<textarea id="lc2" class="lebody" placeholder="亲爱的，&#10;&#10;今天想跟你说…"></textarea>'+
   '<div id="lepic"></div>'+
  "</div>"+
  '<div class="lesend"><button class="btn pri" style="width:100%" data-act="letter-send">'+ico("send")+" 封 · 寄出</button></div>"},
 init(){try{document.getElementById("app").classList.add("lebar")}catch(e){};lePaint();
  /* 标题回车 = 跳到正文（不寄出）；正文回车 = 正常换行，只有点「寄出」才发送 */
  const t2=document.getElementById("lt2");
  if(t2)t2.addEventListener("keydown",function(e){if(e.key==="Enter"&&!e.isComposing){e.preventDefault();const b=document.getElementById("lc2");if(b)b.focus()}});
 }};
ACT["letter-emo"]=()=>{openStickerPicker(function(c){cardMediaUrl(c,function(u){if(!u)return;_le.sticker=u;try{lePaint()}catch(e){};toast("已添加表情")})});return;const cats=["表情包","颜文字","Emoji"];
 const sh=openSheet('<div class="mtitle">选个表情<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  '<div class="chips">'+cats.map(function(c){return '<button class="chip" data-lec="'+c+'">'+c+"</button>"}).join("")+"</div>"+
  '<div class="stkgrid" id="legrid" style="margin-top:10px"><div class="muted" style="padding:18px;text-align:center;grid-column:1/-1">点击上方分组查看</div></div>',true);
 sh.onclick=function(e){const c=e.target.closest("[data-lec]");
  if(c){const st=cardsOf(c.dataset.lec),g=sh.querySelector("#legrid");
   g.innerHTML=st.length?st.map(function(x){return '<button data-lep="'+x.id+'">'+(x.data?'<img src="'+x.data+'">':esc(x.content))+"</button>"}).join(""):'<div class="muted" style="padding:18px;text-align:center;grid-column:1/-1">该分组暂无内容</div>';return}
  const p2=e.target.closest("[data-lep]");
  if(p2){const c0=S.cards.find(function(x){return x.id===p2.dataset.lep});if(!c0)return;
   if(c0.data)_le.sticker=c0.data;else{const t2=document.getElementById("lc2");if(t2)t2.value=(t2.value||"")+c0.content}
   closeModal();lePaint();toast("已添加");return}
  if(e.target.closest("[data-r]"))closeModal()}};
ACT["letter-img"]=()=>pickFile("image/*",false,function(fs){if(!fs||!fs[0])return;readAsDataURL(fs[0]).then(function(u){_le.sticker=u;lePaint();toast("已添加图片")})});
ACT["letter-send"]=()=>{const t=(document.getElementById("lc2")||{}).value||"",ti=(document.getElementById("lt2")||{}).value||"";
 if(!String(t).trim()&&!_le.sticker)return toast("信纸是空的");
 if(_le.mode==="reply"){const l=S.letters.find(function(x){return x.id===_le.replyId});
  if(l){l.myReply={content:String(t).trim(),tm:Date.now(),sticker:_le.sticker||""};save("letters");
   toast("你寄出了一封回信");favTaCollectMail(l.title||"",t);scheduleLetterReply()}}
 else{S.letters.push({id:uid(),from:"me",to:"ta",title:String(ti).trim(),content:String(t).trim(),sticker:_le.sticker||"",ts:Date.now(),read:true});
  save("letters");toast("已寄出");scheduleLetterReply();favTaCollectMail(ti,t)}
 S.misc.letterTab=(_le.mode==="reply")?"in":"out";save("misc");_le={mode:"write",replyId:"",sticker:""};back()};
function letterSheet(id){const l=S.letters.find(function(x){return x.id===id});if(!l)return;l.read=true;save("letters");_letterSheetId=id;
 const mine=l.from==="me",nm=S.settings.taName||"TA";
 const card=function(who,ts,title,content,sticker){return '<div class="mlcard"><div class="mlch"><b>'+esc(who)+'</b><span class="mltime">'+mailDate(ts)+'</span></div>'+
  (title?'<div class="mlct">'+esc(title)+"</div>":"")+'<div class="mlcc">'+esc(content)+"</div>"+(sticker?'<img class="mlst" src="'+sticker+'">':"")+"</div>"};
 let body="";
 if(mine){body=card(S.settings.myName||"我",l.ts,l.title,l.content,l.sticker);
  if(l.taReply)body+=card(nm,l.taReply.ts,"对方的回信",l.taReply.content,l.taReply.sticker)}
 else{body=card(nm,l.ts,l.title,l.content,l.sticker);
  const rp=(l.myReply&&(String(l.myReply.content||"").trim()||l.myReply.sticker))?l.myReply:null;
  if(rp)body+=card(S.settings.myName||"我",rp.tm,"我的回信",rp.content,rp.sticker);
  if(l.taReply)body+=card(nm,l.taReply.ts,"回你的信",l.taReply.content,l.taReply.sticker)}
 const btns=mine
  ?'<div class="btnrow" style="margin-top:12px"><button class="btn danger" data-lg="del" style="flex:1">删除</button><button class="btn" data-lg="close" style="flex:1">关闭</button></div>'
  :'<div class="btnrow" style="margin-top:12px"><button class="btn" data-lg="fav" style="flex:1">'+(l.myFav?"已收藏":"收藏来信")+'</button>'+(!!l.taReply?'<button class="btn" data-lg="replied" style="flex:1;opacity:.55" aria-disabled="true">静候下一封信</button>':(!!(l.myReply&&(String(l.myReply.content||"").trim()||l.myReply.sticker))?'<button class="btn" data-lg="replied" style="flex:1;opacity:.55" aria-disabled="true">已回信</button>':'<button class="btn" data-lg="reply" style="flex:1">提笔回信</button>'))+'</div>'+
   '<div class="btnrow" style="margin-top:10px"><button class="btn danger" data-lg="del" style="flex:1">删除</button><button class="btn" data-lg="close" style="flex:1">关闭</button></div>';
 const sh=openSheet('<div class="mtitle">信件<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+body+btns,true);
 sh.onclick=function(e){const b=e.target.closest("[data-lg]");
  if(b){const k=b.dataset.lg;
   if(k==="close"){closeModal();if(cur==="mail")renderLetters();return}
   if(k==="reply"){closeModal();letterEditOpen("reply",l.id);return}
   if(k==="replied"){toast("这封信已经回过了，不能再回");return}
   if(k==="fav"){if(l.myFav){l.myFav=false;save("letters");toast("已取消收藏")}else if(favAdd({by:"me",kind:"mail",title:l.title||"",text:l.content})){l.myFav=true;save("letters");toast("已收藏到我的收藏")}else{l.myFav=true;save("letters");toast("已收藏")}
    closeModal();letterSheet(id);return}
   if(k==="del"){closeModal();confirmDlg("删除这封信？","删除",true).then(function(ok){if(!ok)return;
    S.letters=S.letters.filter(function(x){return x.id!==l.id});save("letters");if(cur==="mail")renderLetters();toast("已删除")});return}}
  if(e.target.closest("[data-r]")){closeModal();if(cur==="mail")renderLetters()}};
 if(cur==="mail")renderLetters()}
function letterReply(id,text){const l=S.letters.find(x=>x.id===id);if(!l)return;
 l.myReply={content:String(text||"").trim().slice(0,800),tm:Date.now()};save("letters");
 toast("你寄出了一封回信");favTaCollectMail(l.title||"",l.myReply.content);scheduleLetterReply();
 if(cur==="mail")renderLetters()}
function letterDataHtml(){const n=S.letters.length;let bytes=0;try{bytes=new Blob([JSON.stringify(S.letters)]).size}catch(e){bytes=JSON.stringify(S.letters).length}
 return '<div class="sect">信箱 · 数据管理</div><div class="card">'+
  '<div class="row" style="border:none;padding-bottom:0"><span class="lab"><b>信箱 · 数据管理</b></span><span class="val" data-act="letter-dataall" style="color:var(--muted)">全部功能 ›</span></div>'+
  '<div class="muted" style="padding:4px 0 12px">'+n+" 封 · "+fmtBytes(bytes)+"</div>"+
  '<div class="btnrow"><button class="btn sm" data-act="letter-export">导出数据</button><button class="btn sm" data-act="letter-import">导入数据</button><button class="btn sm danger" data-act="letter-clearall">清空数据</button></div></div>'}
ACT["letter-open"]=el=>letterSheet(el.dataset.id);
ACT["letter-dataall"]=()=>{closeModal();go("setstore")};
ACT["letter-export"]=()=>{try{download("星笺信箱_"+dayKey(Date.now())+".json",JSON.stringify({app:"xingjian",ver:1,data:{letters:S.letters}}));toast("已导出")}catch(e){toast("导出失败")}};
ACT["letter-import"]=()=>pickFile("application/json,.json",false,fs=>{readAsText(fs[0]).then(t=>{
 let o=null;try{o=JSON.parse(t)}catch(e){}
 if(!o||!o.data||!Array.isArray(o.data.letters))return toast("文件里没有信件数据");
 actionSheet("导入方式",["合并到现有信件","清空后导入"]).then(i=>{if(i==null)return;
  if(i===1)S.letters=[];
  let n=0;o.data.letters.forEach(x=>{const g=Object.assign({id:uid(),from:"ta",to:"me",title:"",content:"",ts:Date.now(),read:true},x);
   if(!S.letters.some(y=>y.ts===g.ts&&y.content===g.content)){S.letters.push(g);n++}});
  save("letters");render();toast("已导入 "+n+" 封")})})});
ACT["letter-clearall"]=()=>{confirmDlg("清空全部信件数据？删除后无法恢复","清空",true).then(ok=>{if(!ok)return;
 S.letters=[];save("letters");render();toast("已清空信箱")})};
function letterCompose(){openSheet('<div class="mtitle">写信给 '+esc(S.settings.taName)+'<button class="ibtn" data-r="x">'+ico("close")+'</button></div><input id="lt" placeholder="标题（可空）" enterkeyhint="next" style="margin-bottom:8px"><textarea id="lc" style="min-height:140px" placeholder="见字如面…"></textarea><div class="btnrow" style="justify-content:flex-end;margin-top:10px"><button class="btn pri" data-r="ok">寄出</button></div>',true);
 /* 标题回车 = 跳到正文；正文回车 = 换行，不直接寄出 */
 const _lt=document.getElementById("lt");
 if(_lt)_lt.addEventListener("keydown",function(e){if(e.key==="Enter"&&!e.isComposing){e.preventDefault();const b=document.getElementById("lc");if(b)b.focus()}});
 $("#modal .sheet").onclick=e=>{
  const b=e.target.closest("[data-r]");if(!b)return;
  /* 先读输入框，再关弹层（closeModal 会清空 .sheet，之后再读就取不到了） */
  const ti=($("#lt")||{value:""}).value.trim();
  const c=($("#lc")||{value:""}).value.trim();
  closeModal();
  if(b.dataset.r!=="ok")return;
  if(!c)return toast("信纸是空的");
  S.letters.push({id:uid(),from:"me",to:"ta",title:ti,content:c,ts:Date.now(),read:true});
  save("letters");renderLetters();toast("已寄出");favTaCollectMail(ti,c);scheduleLetterReply()}}
function letterSticker(){const r=S.settings.reply.letter;if(!chance(r.sticker))return null;const st=cardsOf("表情包");return st.length?pick(st).data:null}
function letterContent(){const r=S.settings.reply.letter;const n=rnd(r.minCards,r.maxCards);const pool=[...cardTexts("主字卡"),...cardTexts("情绪字卡")];let lines=[];for(let i=0;i<n;i++)lines.push(pool.length?pick(pool):"见字如面，甚是思念");let txt="见字如面：\n"+lines.join("\n")+"\n盼复";if(chance(r.kaomoji)){const k=cardTexts("颜文字");if(k.length)txt+=" "+pick(k)}if(chance(r.emoji)){const e=cardTexts("Emoji");if(e.length)txt+=pick(e)}return txt}
function scheduleLetterReply(){const r=S.settings.reply.letter;if(!chance(r.replyProb))return;setTimeout(()=>{
  try{
   /* 只在这一轮里回：找到「还没被 TA 回过」的那封，把回复挂在我回信的下面，不再另起一封 */
   const list=(S.letters||[]).filter(function(l){return l&&!l.taReply});
   let target=list.filter(function(l){return l.from==="ta"&&l.myReply&&(String(l.myReply.content||"").trim()||l.myReply.sticker)}).sort(function(a,b){return (b.myReply.tm||0)-(a.myReply.tm||0)})[0];
   if(!target)target=list.filter(function(l){return l.from==="me"}).sort(function(a,b){return (b.ts||0)-(a.ts||0)})[0];
   if(!target)return;
   let quote="";
   if(target.myReply){const raw=String(target.myReply.content||"");const t=raw.replace(/\s+/g," ").slice(0,40);if(t)quote="你信里说：「"+t+(raw.length>40?"…":"")+"」\n\n"}
   target.taReply={content:quote+letterContent(),sticker:letterSticker(),ts:Date.now()};
   save("letters");
   const nm=S.settings.taName||"TA";
   notifyTA(nm+" 给你回信了");
   if(cur==="mail"){renderLetters();toast(nm+" 给你回信了");try{if(document.querySelector("#modal .sheet")&&_letterSheetId===target.id)letterSheet(target.id)}catch(e){}}
  }catch(e){}
 },rnd(r.replyTimeMin,r.replyTimeMax)*3600000/60)}
function taLetterCheck(){const r=S.settings.reply.letter;const last=S.misc.lastTaLetter||0;const h=(Date.now()-last)/3600000;if(h<r.activeTimeMin)return;if(!chance(r.activeProb))return;S.misc.lastTaLetter=Date.now();save("misc");for(let i=0;i<Math.max(1,r.activeCount);i++)S.letters.push({id:uid(),from:"ta",to:"me",title:pick(["近安","见字如面","随笔","念你"]),content:letterContent(),sticker:letterSticker(),ts:Date.now(),read:false});save("letters");{const nm=S.settings.taName||"TA";notifyTA(nm+" 给你寄了一封信");if(cur==="mail")toast(nm+" 给你寄了一封信")}}
/* ================= MOMENTS ================= */
/* ---- 朋友圈：通知提醒 + 数据管理（对齐 mochi 链路） ---- */
function feedNotices(){if(!Array.isArray(S.misc.feedNotices))S.misc.feedNotices=[];return S.misc.feedNotices}
function feedUnread(){return feedNotices().filter(n=>!n.read).length}
function feedNotice(text){try{const l=feedNotices();l.unshift({id:uid(),text:String(text||""),ts:Date.now(),read:false});
 S.misc.feedNotices=l.slice(0,100);save("misc");
 if(cur==="moments"){toast(text);render()}else notifyTA(text)}catch(e){}}
function feedNoticeSheet(){const l=feedNotices();l.forEach(n=>{n.read=true});save("misc");
 openSheet('<div class="mtitle">通知提醒<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  (l.length?l.map(n=>'<div class="fnotice"><div class="fnt">'+esc(n.text)+'</div><div class="fnm">'+fmtFull(n.ts)+"</div></div>").join(""):'<div class="empty">暂时没有新的提醒</div>'),true);
 const sh=$("#modal .sheet");sh.onclick=e=>{if(e.target.closest("[data-r]")){closeModal();render()}}}
function feedDataHtml(){const n=S.moments.length;let bytes=0;try{bytes=new Blob([JSON.stringify(S.moments)]).size}catch(e){bytes=JSON.stringify(S.moments).length}
 return '<div class="sect">朋友圈 · 数据管理</div><div class="card">'+
  '<div class="row" style="border:none;padding-bottom:0"><span class="lab"><b>朋友圈 · 数据管理</b></span><span class="val" data-act="moment-dataall" style="color:var(--muted)">全部功能 ›</span></div>'+
  '<div class="muted" style="padding:4px 0 12px">'+n+" 条 · "+fmtBytes(bytes)+"</div>"+
  '<div class="btnrow"><button class="btn sm" data-act="moment-export">导出数据</button><button class="btn sm" data-act="moment-import">导入数据</button><button class="btn sm danger" data-act="moment-clearall">清空数据</button></div></div>'}
function feedClearSheet(){const mine=S.moments.filter(p=>p.who==="me").length;
 openSheet('<div class="mtitle">删除朋友圈动态<button class="ibtn" data-r="x">'+ico("close")+'</button></div><div class="muted" style="margin-bottom:8px">删除后无法恢复。当前 '+S.moments.length+" 条（我的 "+mine+" 条）</div>"+
  '<div class="chips">'+[["all","全部删除"],["mine","仅我的动态"],["ta","仅TA的动态"]].map(x=>'<button class="chip" data-fd="'+x[0]+'">'+x[1]+"</button>").join("")+"</div>",true);
 const sh=$("#modal .sheet");sh.onclick=e=>{const b=e.target.closest("[data-fd]");
  if(b){const k=b.dataset.fd;const nm=k==="mine"?"我的动态":(k==="ta"?"TA 的动态":"全部动态");
   confirmDlg("删除"+nm+"？删除后无法恢复","删除",true).then(ok=>{if(!ok)return;
    if(k==="all")S.moments=[];else if(k==="mine")S.moments=S.moments.filter(p=>p.who!=="me");else S.moments=S.moments.filter(p=>p.who==="me");
    save("moments");render();toast("已删除")});return}
  if(e.target.closest("[data-r]"))closeModal()}}
/* ---- 朋友圈：封面 + 头像（点头像直接开相册）+ 时间胶囊条 ---- */
function feedCover(){return S.misc.feedCover||""}
function feedSetAvatar(){pickFile("image/*",false,fs=>{if(!fs||!fs[0])return;readAsDataURL(fs[0]).then(function(u){try{setAvatar("me",u)}catch(e){S.assets.ava_me=u}save("assets");save("misc");render();toast("已更换我的头像")})})}
function feedSetCover(){pickFile("image/*",false,fs=>{if(!fs||!fs[0])return;readAsDataURL(fs[0]).then(function(u){S.misc.feedCover=u;save("misc");render();toast("已设置朋友圈背景")})})}
function feedNickSheet(){const sh=openSheet('<div class="mtitle">朋友圈昵称<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
 '<div class="row"><span class="lab">我的昵称</span><input id="fn-me" value="'+esc(S.settings.myName||"我")+'" maxlength="12" style="flex:none;width:120px"></div>'+
 '<div class="row"><span class="lab">'+esc(S.settings.taName||"TA")+' 的昵称</span><input id="fn-ta" value="'+esc(S.settings.taName||"TA")+'" maxlength="12" style="flex:none;width:120px"></div>'+
 '<div class="btnrow" style="margin-top:12px"><button class="btn" data-fn="reset" style="flex:1">恢复默认背景</button><button class="btn pri" data-fn="ok" style="flex:1">保存</button></div>',true);
 sh.onclick=e=>{const b=e.target.closest("[data-fn]");if(!b){if(e.target.closest("[data-r]"))closeModal();return}
  if(b.dataset.fn==="reset"){S.misc.feedCover="";save("misc");closeModal();render();toast("已恢复默认背景");return}
  const m=($("#fn-me")||{}).value||"我",t=($("#fn-ta")||{}).value||"TA";
  S.settings.myName=m.trim().slice(0,12)||"我";S.settings.taName=t.trim().slice(0,12)||"TA";save("settings");
  closeModal();render();toast("已保存昵称")}}
function feedWeekStart(){const d=new Date();d.setHours(0,0,0,0);const w=(d.getDay()+6)%7;d.setDate(d.getDate()-w);return d.getTime()}
function feedBuckets(){const list=[...S.moments];const wk=feedWeekStart();
 const inWeek=list.filter(function(p){return (p.ts||0)>=wk}).length;
 const map={},order=[];
 list.forEach(function(p){const d=new Date(p.ts||0);const k=d.getFullYear()+"-"+(d.getMonth()+1);
  if(!map[k]){map[k]={k:k,y:d.getFullYear(),m:d.getMonth()+1,n:0};order.push(map[k])}map[k].n++});
 order.sort(function(a,b){return (b.y*100+b.m)-(a.y*100+a.m)});
 return [{k:"week",label:"本周",n:inWeek}].concat(order.map(function(o){return {k:o.k,label:(o.m)+"月",n:o.n}}))}
function feedRange(){return S.misc.feedRange||"week"}
function feedInBucket(p,k){if(k==="week")return (p.ts||0)>=feedWeekStart();
 const d=new Date(p.ts||0);return (d.getFullYear()+"-"+(d.getMonth()+1))===k}
function feedBarHtml(bk,rk){const i=bk.findIndex(function(b){return b.k===rk});
 return '<div class="fbar"><button class="fnav" data-act="moment-range" data-fr="prev" '+(i>0?"":"disabled")+">"+ico("next")+'</button>'+
  bk.map(function(b){return '<button class="fcap'+(b.k===rk?" on":"")+'" data-act="moment-range" data-fr="go" data-k="'+b.k+'">'+esc(b.label)+' <b>'+b.n+"</b></button>"}).join("")+
  '<button class="fnav" data-act="moment-range" data-fr="next" '+(i<bk.length-1?"":"disabled")+'>'+ico("next")+"</button></div>"}
PAGES.moments={html(){const un=feedUnread();
 return phead("朋友圈",'<button class="ibtn" data-act="moment-notice" title="通知提醒">'+ico("bell")+(un?'<span class="fdot">'+(un>99?"99+":un)+"</span>":"")+'</button><button class="ibtn" data-act="moment-new" title="发布">'+ico("plus")+'</button><button class="ibtn" data-act="moment-data" title="数据管理">'+ico("dotsLine")+'</button><button class="ibtn" data-act="moment-clear" title="删除动态">'+ico("trash")+"</button>")+
 '<div class="fcover"'+(feedCover()?' style="background-image:url('+feedCover()+')"':"")+' data-act="moment-cover"><span class="favme"><span class="favav" data-act="moment-myavatar">'+avatarHtml({src:avatarSrc("me"),name:S.settings.myName,me:true})+'</span><span class="favnm" data-act="moment-myname">'+esc(S.settings.myName||"我")+"</span></span></div>"+
 feedBarHtml(feedBuckets(),feedRange())+
 '<div id="mbox"></div>'},
 init(){renderMoments()}};
ACT["moment-cover"]=()=>feedSetCover();
ACT["moment-myavatar"]=()=>feedSetAvatar();
ACT["moment-myname"]=()=>feedNickSheet();
ACT["moment-data"]=()=>{const n=S.moments.length;let bytes=0;try{bytes=new Blob([JSON.stringify(S.moments)]).size}catch(e){}
 const sh=openSheet('<div class="mtitle">朋友圈 · 数据管理<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  '<div class="muted" style="padding:2px 2px 12px">'+n+" 条动态 · "+fmtBytes(bytes)+"</div>"+
  '<div class="chips" style="margin-bottom:10px"><button class="chip" data-fd2="all">全部功能 ›</button></div>'+
  '<div class="btnrow"><button class="btn" data-fd2="export" style="flex:1">导出数据</button><button class="btn" data-fd2="import" style="flex:1">导入数据</button></div>'+
  '<div class="btnrow" style="margin-top:10px"><button class="btn danger" data-fd2="clear" style="flex:1">清空数据</button></div>',true);
 sh.onclick=function(e){const b=e.target.closest("[data-fd2]");
  if(b){const k=b.dataset.fd2;closeModal();if(k==="all")ACT["moment-dataall"]();else if(k==="export")ACT["moment-export"]();else if(k==="import")ACT["moment-import"]();else ACT["moment-clearall"]();return}
  if(e.target.closest("[data-r]"))closeModal()}};
ACT["moment-range"]=el=>{const d=el.dataset.fr;const bk=feedBuckets();const i=bk.findIndex(function(b){return b.k===feedRange()});
 if(d==="go")S.misc.feedRange=el.dataset.k;
 else if(d==="prev"&&i>0)S.misc.feedRange=bk[i-1].k;
 else if(d==="next"&&i<bk.length-1)S.misc.feedRange=bk[i+1].k;
 save("misc");render()};
ACT["moment-notice"]=()=>feedNoticeSheet();
ACT["moment-clear"]=()=>feedClearSheet();
ACT["moment-dataall"]=()=>{closeModal();go("setstore")};
ACT["moment-export"]=()=>{try{download("星笺朋友圈_"+dayKey(Date.now())+".json",JSON.stringify({app:"xingjian",ver:1,data:{moments:S.moments}}));toast("已导出")}catch(e){toast("导出失败")}};
ACT["moment-import"]=()=>pickFile("application/json,.json",false,fs=>{readAsText(fs[0]).then(t=>{
 let o=null;try{o=JSON.parse(t)}catch(e){}
 if(!o||!o.data||!Array.isArray(o.data.moments))return toast("文件里没有朋友圈数据");
 actionSheet("导入方式",["合并到现有动态","清空后导入"]).then(i=>{if(i==null)return;
  if(i===1)S.moments=[];
  let n=0;o.data.moments.forEach(p=>{const g=Object.assign({id:uid(),who:"me",content:"",imgs:[],ts:Date.now(),likes:0,likesWho:[],cmts:[]},p);
   if(!S.moments.some(x=>x.ts===g.ts&&x.content===g.content)){S.moments.push(g);n++}});
  save("moments");render();toast("已导入 "+n+" 条动态")})})});
ACT["moment-clearall"]=()=>{confirmDlg("清空全部朋友圈数据？删除后无法恢复","清空",true).then(ok=>{if(!ok)return;
 S.moments=[];S.misc.feedNotices=[];save("moments");save("misc");render();toast("已清空朋友圈")})};
/* ---- 朋友圈：固定底栏评论 + 点名字回复 + 点赞/收藏状态 ---- */
let _fc={pid:"",ci:null,img:"",cid:""};
function feedPost(id){return S.moments.find(function(x){return x.id===id})}
function feedCmtAttach(d,cid){_fc.img=d||"";_fc.cid=cid||"";feedCmtBar();if(_fc.img)toast("已附加，点「发送」一起发出")}
function feedCmtSend(text,img){const p=feedPost(_fc.pid);if(!p)return;
 const t=String(text||"").trim();if(!t&&!img)return toast("写点什么吧");
 const parts={text:t,img:img||""};
 if(_fc.cid&&img)parts.cid=_fc.cid;
 if(_fc.ci!=null){const c=(p.cmts||[])[_fc.ci];if(c)parts.to=c.who}
 addMyComment(p,parts);const pid=_fc.pid;_fc={pid:pid,ci:null,img:"",cid:""};feedCmtBar()}
function feedCmtBar(){let el=document.getElementById("fcbar");
 const show=!!(cur==="moments"&&_fc.pid);
 const app=document.getElementById("app");if(app)app.classList.toggle("feedbar",show);
 if(!show){if(el)el.remove();return}
 if(!el){el=document.createElement("div");el.id="fcbar";el.className="fcbar";document.body.appendChild(el);
  el.onclick=function(e){const b=e.target.closest("[data-fc]");if(!b)return;const k=b.dataset.fc;
       if(k==="emo"){openStickerPicker(function(c){cardMediaUrl(c,function(u){if(u)feedCmtAttach(u,c.id)})});return}
   if(k==="img"){pickFile("image/*",false,function(fs){if(!fs||!fs[0])return;readAsDataURL(fs[0]).then(function(u){feedCmtAttach(u,"")})});return}
   if(k==="rm"){_fc.img="";_fc.cid="";feedCmtBar();return}
   if(k==="send"){const i=document.getElementById("fcin");const v=i?i.value:"";const im=_fc.img||"";if(i)i.value="";_fc.img="";feedCmtSend(v,im);return}
   if(k==="close"){_fc={pid:"",ci:null,img:"",cid:""};feedCmtBar();return}}
 }
 const p=feedPost(_fc.pid),c=(p&&_fc.ci!=null)?(p.cmts||[])[_fc.ci]:null;
 const oldIn=document.getElementById("fcin");
 const keepTxt=oldIn?oldIn.value:"";
 const hadFocus=!!(oldIn&&document.activeElement===oldIn);
 el.innerHTML='<button class="ibtn" data-fc="emo" title="表情包">'+ico("sticker")+'</button><button class="ibtn" data-fc="img" title="图片">'+ico("img")+'</button>'+
  (_fc.img?('<span class="fcatt"><img src="'+_fc.img+'"><button data-fc="rm" title="移除">'+ico("close")+'</button></span>'):"")+
  '<input id="fcin" type="search" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" enterkeyhint="send" value="'+esc(keepTxt)+'" placeholder="'+(c?("回复 "+esc(c.who)+"…"):"评论…")+'">'+
  '<button class="btn pri" data-fc="send">发送</button>';
 el.onkeydown=function(e){if(e.key==="Enter"&&!e.isComposing){const s=el.querySelector('[data-fc="send"]');if(s){e.preventDefault();s.click()}}};
 if(hadFocus){const ni=document.getElementById("fcin");if(ni){try{ni.focus();ni.setSelectionRange(ni.value.length,ni.value.length)}catch(e){}}}}
/* 朋友圈语音：胶囊按钮 + 音波 + 播放/暂停双图标（播放中音波跳动） */
function feedVoiceBtn(id,dur){return '<button class="voice feedvoice" data-act="play-voice" data-id="'+esc(String(id||""))+'" title="播放语音">'+
 '<span class="fv-ico fv-play">'+ico("play")+'</span><span class="fv-ico fv-pause">'+ico("pause")+'</span>'+
 '<span class="fv-waves"><i></i><i></i><i></i><i></i><i></i></span>'+
 '<span class="fv-dur">'+(dur?esc(String(dur)+"″"):"语音")+'</span></button>'}
function renderMoments(){const box=$("#mbox");if(!box)return;
 const me=S.settings.myName||"我",ta=S.settings.taName||"TA";
 const list=[...S.moments].filter(function(p){return feedInBucket(p,feedRange())}).sort(function(a,b){return b.ts-a.ts});
 if(!list.length){box.innerHTML='<div class="empty">'+(feedRange()==="week"?"本周还没有动态<br>点上面那条胶囊翻更早的月份":"这个月还没有动态")+"</div>";return}
 box.innerHTML=list.map(function(p){const mine=p.who==="me";
  const liked=(p.likesWho||[]).indexOf(me)>=0,taLiked=(p.likesWho||[]).indexOf(ta)>=0;
  const cmts=(p.cmts||[]).map(function(c,i){return '<div class="fcmt"><b class="'+(c.who===ta?"ta":"")+'" data-act="feed-reply" data-id="'+p.id+'" data-i="'+i+'">'+esc(c.who)+"</b>"+(c.to?(" 回复 "+esc(c.to)):"")+"："+((c.img||c.imgMedia)?'<img class="zoomable fcimg" data-act="img-view" data-mid="'+c.id+'" src="'+mediaUrl(c.img,"mc"+c.id)+'">':"")+esc(c.text||"")+(c.voiceData?feedVoiceBtn(c.id,c.voiceDur):"")+"</div>"}).join("");
  return '<div class="card post"><div class="who">'+avatarHtml({src:avatarSrc(mine?"me":"ta"),name:mine?me:ta,me:mine})+'<div><b>'+esc(mine?me:ta)+'</b><br><time>'+mailDate(p.ts)+'</time></div>'+
   '<button class="ibtn" data-act="moment-del" data-id="'+p.id+'" style="margin-left:auto">'+ico("trash")+"</button></div>"+
   '<div class="txt">'+esc(p.content)+"</div>"+(p.imgs&&p.imgs.length?'<div class="pics">'+p.imgs.map(function(i,ix){return '<img class="zoomable" data-act="img-view" data-mid="'+p.id+'" data-mi="'+ix+'" src="'+mediaUrl(i,"f"+p.id+ix)+'">'}).join("")+"</div>":"")+
   (p.voice?feedVoiceBtn(p.id,p.voiceDur):"")+
   '<div class="acts"><span class="'+(liked?"on":"")+(taLiked?" taon":"")+'" data-act="moment-like" data-id="'+p.id+'">'+ico("heart")+" "+(p.likes||0)+'</span><span data-act="moment-cmt" data-id="'+p.id+'">'+ico("cmt")+" 评论</span>"+'<span class="'+(p.myFav?"on":"")+(p.taFav?" taon":"")+'" data-act="moment-fav" data-id="'+p.id+'">'+ico("fav")+" 收藏</span></div>"+
   ((p.likesWho&&p.likesWho.length)||cmts?'<div class="cmts">'+((p.likesWho&&p.likesWho.length)?'<div>♥ '+esc(p.likesWho.join("、"))+"</div>":"")+cmts+"</div>":"")+
  "</div>"}).join("")}
ACT["moment-cmt"]=el=>{_fc={pid:el.dataset.id,ci:null};feedCmtBar();const i=document.getElementById("fcin");if(i)i.focus()};
ACT["feed-reply"]=el=>{_fc={pid:el.dataset.id,ci:+el.dataset.i};feedCmtBar();const i=document.getElementById("fcin");if(i)i.focus()};
ACT["moment-del"]=el=>{const p=feedPost(el.dataset.id);if(!p)return;
 confirmDlg("删除这条动态？","删除",true).then(function(ok){if(!ok)return;
  S.moments=S.moments.filter(function(x){return x.id!==p.id});save("moments");if(_fc.pid===p.id){_fc={pid:"",ci:null}}render();toast("已删除")})};
let _mcDraft=null;function mcDraftState(){if(!_mcDraft)_mcDraft={text:"",imgs:[],imgCids:[]};return _mcDraft}
function momentCompose(){openSheet('<div class="mtitle">发朋友圈<button class="ibtn" data-r="x">'+ico("close")+'</button></div><textarea id="mc" placeholder="记录此刻…" enterkeyhint="send"></textarea><div id="mpics" class="pics" style="margin-top:8px"></div><div id="mstk" class="mstkwrap" style="display:none;margin-top:8px"></div><div class="btnrow" style="margin-top:10px"><button class="btn sm" data-addimg="1">'+ico("img")+' 添加图片</button><button class="btn sm" data-addsticker="1">'+ico("sticker")+' 表情包</button><button class="btn pri" data-r="ok" style="margin-left:auto">发布</button></div>',true);
 const st=mcDraftState();const imgs=st.imgs,imgCids=st.imgCids;const sh=$("#modal .sheet");
 const mcEl=sh.querySelector("#mc");if(mcEl){mcEl.value=st.text||"";mcEl.addEventListener("input",function(){st.text=mcEl.value});
  mcEl.addEventListener("keydown",function(e){if(e.key==="Enter"&&!e.isComposing&&!e.shiftKey){e.preventDefault();const b=sh.querySelector('[data-r="ok"]');if(b)b.click()}})}
 const paint=()=>{const el=sh.querySelector("#mpics");if(!el)return;
  el.innerHTML=imgs.map(function(u,i){return '<span class="mpic"><img src="'+u+'" alt=""><button type="button" class="mrm" data-rmimg="'+i+'" title="移除">'+ico("close")+'</button></span>'}).join("")};paint();
 /* 与聊天共用的表情包池：最近使用 + 全部 + 各分组 */
 const paintStk=function(){
  const g=sh.querySelector("#mstk");if(!g)return;
  const k=(S.misc.stkG===undefined?"__recent":S.misc.stkG);
  g.innerHTML='<div class="mstkhead"><span>选表情包</span><button type="button" data-stkclose="1">收起</button></div>'+stkPickBody(k);
  try{loadCardImgsIn(sh)}catch(err){}
 };
 sh.onclick=e=>{
  /* 选错了就点缩略图右上角的 ×，只移除这一张，不退出编辑面板 */
  const rm=e.target.closest("[data-rmimg]");
  if(rm){const ix=+rm.dataset.rmimg;if(ix>=0){imgs.splice(ix,1);imgCids.splice(ix,1);paint()}return}
  if(e.target.closest("[data-stkclose]")){const g0=sh.querySelector("#mstk");if(g0){g0.dataset.on="";g0.style.display="none"}return}
  if(e.target.closest("[data-addimg]")){pickFile("image/*",true,fs=>{Promise.all(fs.map(readAsDataURL)).then(rs=>{rs.forEach(function(u){imgs.push(u);imgCids.push("")});if(!document.getElementById("mc")){momentCompose();return}paint()}).catch(function(){toast("图片读取失败")})});return}
     if(e.target.closest("[data-addsticker]")){
  /* 用编辑页里的内嵌表情网格，不能 openStickerPicker —— 它会复用同一个 .sheet，
     把发朋友圈的输入框/已选图片全部清空，看起来就是“发不出去、直接回到朋友圈”。 */
  const g=sh.querySelector("#mstk");if(!g)return;
  if(g.dataset.on==="1"){g.dataset.on="";g.style.display="none";return}
  g.dataset.on="1";g.style.display="";
  paintStk();
  return;
}
  const chip=e.target.closest("[data-spk]");
  if(chip){S.misc.stkG=chip.dataset.spk||"";save("misc");paintStk();return}
  const sk=e.target.closest("[data-spki]");
  if(sk){const c0=S.cards.find(x=>x.id===sk.dataset.spki);if(c0)cardMediaUrl(c0,function(u){if(u){imgs.push(u);imgCids.push(c0.id||"");paint();stkRecentTouch(c0.id);toast("已添加表情")}});return}
  const b=e.target.closest("[data-r]");if(!b)return;
  const _c=($("#mc")||{value:""}).value;closeModal();if(b.dataset.r!=="ok")return;
  const c=(_c||"").trim();
  const finalImgs=(st.imgs||[]).filter(function(x){return typeof x==="string"&&x});
  if(!c&&!finalImgs.length)return toast("说点什么吧");
  const p={id:uid(),who:"me",content:c,imgs:finalImgs,imgCids:(st.imgCids||[]).slice(0,finalImgs.length),ts:Date.now(),likes:0,likesWho:[],cmts:[]};
  S.moments.push(p);
  try{save("moments")}catch(err){}
  try{renderMoments()}catch(err){try{toast("已发布，重新进入朋友圈即可看到")}catch(e2){}}
  _mcDraft=null;
  try{taReactTo(p)}catch(err){}
  try{favTaCollectFeed(c,finalImgs)}catch(err){}
 };
 }
function taMomentContent(){const r=S.settings.reply.moments;const pool=[...cardTexts("主字卡"),...cardTexts("情绪字卡"),...cardTexts("状态")];let parts=[];for(let i=0;i<Math.max(1,r.cards);i++)parts.push(pool.length?pick(pool):"今天也是平常的一天");let t=parts.join("。");if(chance(r.kaomoji)){const k=cardTexts("颜文字");if(k.length)t+=" "+pick(k)}if(chance(r.emoji)){const e=cardTexts("Emoji");if(e.length)t+=pick(e)}return t}
function taReactTo(p){const r=S.settings.reply.moments;
 if(chance(r.likeProb))setTimeout(()=>{p.likes=(p.likes||0)+1;p.likesWho=p.likesWho||[];p.likesWho.push(S.settings.taName);save("moments");if(cur==="moments")renderMoments();feedNotice((S.settings.taName||"TA")+" 赞了你的动态")},rnd(20,120)*1000);
 if(chance(r.cmtProb))setTimeout(()=>{let t=cardTexts("情绪字卡").length?pick(cardTexts("情绪字卡")):"真好";if(chance(r.cmtKaomoji)){const k=cardTexts("颜文字");if(k.length)t+=" "+pick(k)}if(chance(r.cmtEmoji)){const e=cardTexts("Emoji");if(e.length)t+=pick(e)}const cmt={id:uid(),who:S.settings.taName,text:t};if(chance(r.cmtSticker)){const st=cardsOf("表情包");if(st.length){const c0=pick(st);cmt.stkCid=c0.id;cardMediaUrl(c0,function(u){if(u){cmt.img=u;try{save("moments");if(cur==="moments")renderMoments()}catch(e){}}})}}if(chance(r.cmtVoice)){const vc=cardsOf("语音字卡");if(vc.length)mediaFromCardInto(pick(vc),cmt,"voiceData")}p.cmts=p.cmts||[];p.cmts.push(cmt);save("moments");if(cur==="moments")renderMoments();feedNotice((S.settings.taName||"TA")+" 评论了你的动态")},rnd(60,300)*1000)}
function taMomentCheck(){const r=S.settings.reply.moments;const day=MEMO_TODAY();const fd=S.misc.feedDay||(S.misc.feedDay={d:day,n:0});if(fd.d!==day){fd.d=day;fd.n=0;save("misc")}if(Date.now()<(S.misc.feedCoolUntil||0))return;const last=S.misc.lastTaMoment||0;if((Date.now()-last)/3600000<r.intervalH)return;if(fd.n>=(r.dailyMax==null?5:r.dailyMax))return;if(!chance(r.activeProb))return;S.misc.lastTaMoment=Date.now();fd.n++;S.misc.feedCoolUntil=Date.now()+(r.cool==null?30:r.cool)*60000;save("misc");const p={id:uid(),who:"ta",content:taMomentContent(),imgs:[],ts:Date.now(),likes:0,likesWho:[],cmts:[]};if(chance(r.sticker)){const st=cardsOf("表情包");if(st.length){const c0=pick(st);p.stkCid=c0.id;cardMediaUrl(c0,function(u){try{p.imgs=u?[u]:[];save("moments");if(cur==="moments")renderMoments()}catch(e){}})}}if(chance(r.voice)){const vc=cardsOf("语音字卡");if(vc.length){const v0=pick(vc);p.voice=true;mediaFromCardInto(v0,p,"voiceData",function(){try{if(!p.voiceData)p.voice=false}catch(e){}})}}S.moments.push(p);save("moments");if(cur==="moments")renderMoments();feedNotice((S.settings.taName||"TA")+" 发布了一条朋友圈动态")}
/* ================= CALENDAR ================= */
PAGES.cal={html(){return phead("日历")+'<div class="card"><div class="calhead"><button class="ibtn" data-act="cal-prev">'+ico("back")+'</button><b id="caltitle"></b><button class="ibtn" data-act="cal-next">'+ico("back")+' </button></div><div class="calgrid" id="calgrid"></div></div><div id="calday"></div>'},
 init(){S.misc.calY=S.misc.calY||new Date().getFullYear();S.misc.calM=S.misc.calM==null?new Date().getMonth():S.misc.calM;renderCal()}};
function renderCal(){const y=S.misc.calY,m=S.misc.calM;$("#caltitle").textContent=y+"年"+(m+1)+"月";const g=$("#calgrid");const first=new Date(y,m,1).getDay();const days=new Date(y,m+1,0).getDate();const prevDays=new Date(y,m,0).getDate();let html=["日","一","二","三","四","五","六"].map(w=>'<div class="wd">'+w+"</div>").join("");const today=dayKey(Date.now());
 const marks={};S.annivs.forEach(a=>{const d=new Date(a.date);if(d.getMonth()===m&&d.getFullYear()===y){marks[d.getDate()]=marks[d.getDate()]||[];marks[d.getDate()].push("anniv")}});
 const pred=periodPredict();pred.forEach(ts=>{const d=new Date(ts);if(d.getMonth()===m&&d.getFullYear()===y){marks[d.getDate()]=marks[d.getDate()]||[];marks[d.getDate()].push("period")}});
 for(let i=0;i<first;i++)html+='<div class="d off">'+(prevDays-first+i+1)+"</div>";
 for(let d=1;d<=days;d++){const k=y+"-"+pad(m+1)+"-"+pad(d);const mk=(marks[d]||[]);html+='<div class="d'+(k===today?" today":"")+'" data-act="cal-day" data-d="'+d+'">'+d+(mk.length?'<span class="mk">'+mk.map(t=>t==="anniv"?ico("heart"):ico("period")).join("")+"</span>":"")+"</div>"}
 g.innerHTML=html;renderCalDay(S.misc.calSelD||new Date().getDate())}
function renderCalDay(d){const y=S.misc.calY,m=S.misc.calM;S.misc.calSelD=d;const box=$("#calday");const ts=new Date(y,m,d).getTime();const evs=[];S.annivs.forEach(a=>{const ad=new Date(a.date);if(ad.getMonth()===m&&ad.getDate()===d&&ad.getFullYear()===y)evs.push("纪念日："+a.name)});const pred=periodPredict();pred.forEach(t=>{const pd=new Date(t);if(pd.getMonth()===m&&pd.getDate()===d&&pd.getFullYear()===y)evs.push("月经预测")});
 box.innerHTML='<div class="card"><h3>'+(m+1)+"月"+d+'日</h3>'+(evs.length?evs.map(e=>'<div style="font-size:14px;padding:3px 0">'+esc(e)+"</div>").join(""):'<div class="muted">无安排</div>')+"</div>"}
/* ================= ANNIV ================= */
PAGES.anniv={html(){return phead("纪念日",'<button class="ibtn" data-act="anniv-add">'+ico("plus")+"</button>")+'<div class="card"><div class="row"><span class="lab">在一起的时间起点</span><span class="val">'+esc(S.settings.together?fmtFull(new Date(S.settings.together).getTime()):"未设置")+'</span><button class="btn sm" data-act="anniv-together">设置</button></div></div><div id="abox"></div>'},
 init(){renderAnnivs()}};
function renderAnnivs(){const box=$("#abox");if(!box)return;box.innerHTML=S.annivs.length?S.annivs.map(a=>{const ms=Date.now()-new Date(a.date).getTime();const d=Math.floor(ms/86400000);const txt=a.type==="down"?(d>=0?"已过去 "+d+" 天":"还有 "+(-d)+" 天"):(d>=0?"已经 "+d+" 天":"还有 "+(-d)+" 天");return '<div class="card"><div class="row"><span class="lab"><b>'+esc(a.name)+'</b><br><span class="sub">'+fmtFull(new Date(a.date).getTime())+'</span></span><span class="val" style="color:var(--primary);font-weight:600">'+txt+'</span><button class="ibtn" data-act="anniv-del" data-id="'+a.id+'">'+ico("trash")+"</button></div></div>"}).join(""):'<div class="empty">还没有纪念日，点右上添加</div>'}
/* ================= DIVINE ================= */
