function muListsHtml(){const ls=muLists(),st=muState();
 return '<div class="card mulist">'+(ls.length?ls.map(function(l){const n=S.audios.filter(function(a){return (a.listId||"")===l.id}).length;
   return '<div class="musong'+(st.listId===l.id?" on":"")+'"><span class="mucov" data-act="mu-openlist" data-id="'+l.id+'">'+ico("music")+'</span><span class="mumid" data-act="mu-openlist" data-id="'+l.id+'"><b>'+esc(l.name)+'</b><span>'+n+' 首</span></span><button class="ibtn" data-act="mu-lren" data-id="'+l.id+'">'+ico("edit")+'</button><button class="ibtn" data-act="mu-ldel" data-id="'+l.id+'">'+ico("trash")+"</button></div>"}).join(""):'<div class="empty" style="padding:20px 0">还没有歌单</div>')+"</div>"+
  '<div class="btnrow" style="margin-top:10px"><button class="btn pri" style="width:100%" data-act="mu-lnew">＋ 新建歌单</button></div>'+
  (st.listId?'<div class="btnrow" style="margin-top:8px"><button class="btn" style="width:100%" data-act="mu-tab" data-v="songs">← 返回全部歌曲（当前：'+esc(muListName(st.listId))+"）</button></div>":"")}
function muDataHtml(){let n=0;try{S.audios.forEach(function(a){if(muHasLocal(a))n+=((a.dlBytes||(a.blob&&a.blob.size))||0)})}catch(e){}
 return '<div class="sect">音乐 · 数据管理</div><div class="card">'+
  '<div class="row" style="border:none;padding-bottom:0"><span class="lab"><b>音乐 · 数据管理</b></span><span class="val" data-act="mu-dataall" style="color:var(--muted)">全部功能 ›</span></div>'+
  '<div class="muted" style="padding:4px 0 12px">'+S.audios.length+" 首 · 本地缓存 "+fmtBytes(n)+"</div>"+
  '<div class="btnrow"><button class="btn sm danger" data-act="mu-clearall">清空音乐库</button></div>'+
  (muDeadCount()?'<div class="btnrow" style="margin-top:8px"><button class="btn sm" data-act="mu-deadclear" style="width:100%">清理无法播放的歌曲（'+muDeadCount()+' 首）</button></div>':"")+'</div>'+
  '<div class="sect">导出 / 导入</div><div class="card" style="padding:0 12px">'+
   actionRow("down","导出音乐数据",'data-act="mu-export"')+
   actionRow("up","导入音乐数据",'data-act="mu-import-data"')+
   '<div class="muted" style="padding:2px 2px 10px;line-height:1.6">导出会把曲库、歌单、TA 的音乐设置一起打包；若已「下载到本机」，音频也会一并写进文件（可能几百 MB）。导入会覆盖当前曲库。</div>'+
  "</div>"}
/* ---------- 音乐数据 导出 / 导入（曲库 + 歌单 + TA 音乐设置 + 本机音频） ---------- */
async function muExportData(){
 const st=muState();
 const data={app:"xingjian",ver:1,kind:"music",data:{
  audios:await prepExport("audios"),
  muLists:S.misc.muLists||[],
  mu:{tab:st.tab,listId:st.listId,mode:st.mode,favs:st.favs||[],recent:st.recent||[],queue:st.queue||[]},
  muTaFavs:S.misc.muTaFavs||[],
  muDead:S.misc.muDead||{},
  muFloatBg:S.misc.muFloatBg||"",
  muCfg:S.settings.mu||{}
 }};
 download("星笺音乐_"+dayKey(Date.now())+".json",JSON.stringify(data));
 toast("已导出音乐数据")}
async function muImportDataObj(o){
 const d=(o&&o.data)?o.data:o;
 if(!d||typeof d!=="object")throw new Error("文件内容不对");
 if(Array.isArray(d.audios))S.audios=await restoreVal("audios",JSON.parse(JSON.stringify(d.audios)));
 if(Array.isArray(d.muLists))S.misc.muLists=d.muLists;
 if(d.mu&&typeof d.mu==="object"){const st=muState();
  ["tab","listId","mode","favs","recent","queue"].forEach(function(k){if(d.mu[k]!==undefined)st[k]=d.mu[k]})}
 if(Array.isArray(d.muTaFavs))S.misc.muTaFavs=d.muTaFavs;
 if(d.muDead&&typeof d.muDead==="object")S.misc.muDead=d.muDead;
 if(typeof d.muFloatBg==="string")S.misc.muFloatBg=d.muFloatBg;
 if(d.muCfg&&typeof d.muCfg==="object")S.settings.mu=deepMerge(S.settings.mu||{},d.muCfg);
 save("audios");save("misc");save("settings");
 if(muAudio){try{muAudio.pause()}catch(e){}}
 try{muPaint()}catch(e){};render();toast("已导入音乐数据："+S.audios.length+" 首")}
ACT["mu-export"]=async()=>{try{toast("正在打包…");await muExportData()}catch(e){toast("导出失败："+(e&&e.message||e))}};
ACT["mu-import-data"]=()=>pickFile("application/json,.json",false,fs=>{const f=fs&&fs[0];if(!f)return;
 readAsText(f).then(async function(t){
  let o=null;try{o=JSON.parse(t)}catch(e){}
  if(!o)return toast("文件解析失败");
  const d=(o&&o.data)?o.data:o;
  const n=Array.isArray(d&&d.audios)?d.audios.length:0;
  const yes=await confirmDlg("导入音乐数据？\n\n当前 "+S.audios.length+" 首 → 文件里 "+n+" 首（会覆盖当前曲库）","导入",true);
  if(!yes)return;
  try{await muImportDataObj(o);closeModal();render()}catch(e){toast("导入失败："+(e&&e.message||e))}
 }).catch(function(){toast("读取文件失败")})});
ACT["mu-deadclear"]=()=>{const n=muDeadCount();if(!n)return toast("没有需要清理的歌曲");
 confirmDlg("清理 "+n+" 首没有音源的歌曲？只是从曲库移除","清理",true).then(function(ok){if(!ok)return;
  const dm=muDead();S.audios=S.audios.filter(function(a){return !dm[a.id]});
  const st=muState();if(dm[st.cur]){st.cur="";st.favs=st.favs.filter(function(id){return !dm[id]})}
  S.misc.muDead={};save("audios");save("misc");closeModal();render();toast("已清理 "+n+" 首")})};
PAGES.music={html(){const st=muState();const tabs=[["songs","歌曲"],["lists","歌单"],["recent","最近播放"],["tafav",(S.settings.taName||"TA")+" 的收藏"]];
 const rows=muRows();
 return phead("音乐",'<button class="ibtn" data-act="mu-searchbtn" title="搜索">'+ico("search")+'</button><button class="ibtn" data-act="mu-menu" title="更多">'+ico("dotsLine")+"</button>")+
  (st.searchOn?'<div class="card" id="musearch" style="padding:8px 12px;margin-bottom:10px"><input id="muq" placeholder="搜索歌名 / 歌手" value="'+esc(st.q)+'"></div>':"")+
  (st.tab==="lists"?"":'<div class="card muhero"><div class="mumid" style="flex:1"><b>'+esc(muListName(st.listId))+'</b><span>共 '+rows.length+" 首 · "+muModeName()+'</span></div><button class="btn pri" data-act="mu-playall">'+ico("play")+' 播放全部</button><button class="btn mumode" data-act="mu-mode" title="'+esc(muModeName())+'">'+muModeIcon()+'<span>'+muModeShort()+'</span></button></div>')+
  '<div class="chips mutabs">'+tabs.map(function(t){return '<button class="chip'+(st.tab===t[0]?" on":"")+'" data-act="mu-tab" data-v="'+t[0]+'">'+t[1]+"</button>"}).join("")+"</div>"+
  (st.tab==="lists"?muListsHtml():(st.tab==="tafav"?muTaFavHtml():muSongsHtml()))},
 init(){muPaint();
  const i=document.getElementById("muq");
  if(i)i.addEventListener("input",function(){const st2=muState();st2.q=i.value;save("misc");
   const box=document.querySelector(".mulist");const _q=String(i.value||"").trim().toLowerCase();
   const rows2=muRows().filter(function(a){return !_q||String(a.name||"").toLowerCase().indexOf(_q)>=0||String(a.artist||"").toLowerCase().indexOf(_q)>=0});
   if(box){box.innerHTML=rows2.map(muSongRow).join("")||'<div class="empty" style="padding:20px 0">没有匹配的歌曲</div>'}
   const h=document.querySelector(".muhero .mumid span");if(h)h.textContent="共 "+rows2.length+" 首 · "+muModeName()})}};
function muSongRow(a){const st=muState(),on=st.cur===a.id;
 return '<div class="musong'+(on?" on":"")+'" data-act="mu-play" data-id="'+a.id+'"><span class="mucov">'+muCover(a)+'</span>'+
  '<span class="mumid"><b>'+esc(muName(a))+'</b><span>'+esc(a.artist||"未知歌手")+(muHasLocal(a)?" · 本机":(a.url?" · 网络":" · 本地"))+(on?" · 正在播放":"")+'</span></span>'+
  '<span class="mudur">'+(on&&muAudio&&muAudio.duration?muFmt(muAudio.duration):"--:--")+'</span>'+
  muFavBtn(a.id)+
  '<button class="ibtn" data-act="mu-more" data-id="'+a.id+'">'+ico("dots")+"</button></div>"}
