function muCfg(){const s=S.settings;if(!s.mu||typeof s.mu!=="object")s.mu={};
 const m=s.mu,d={invite:5,reserve:6,next:15,rand:10,modeP:5,pauseEn:true,pause:3,fav:20,floatEn:true};
 Object.keys(d).forEach(function(k){if(m[k]===undefined)m[k]=d[k]});return m}
