function muModeIcon(){const m=muState().mode;const x=MU_MODES.find(function(v){return v[0]===m});return ico(x?x[2]:"seq")}
function muModeShort(){const m=muState().mode;return m==="loop"?"循环":(m==="shuffle"?"随机":(m==="single"?"单曲":"顺序"))}
