 if(Date.now()-(S.misc.muTaFavAt||0)<90000)return;
 S.misc.muTaFavAt=Date.now();muTaFavs().unshift({id:a.id,name:muName(a),artist:a.artist||"",pic:a.pic||"",at:Date.now()});save("misc");
