function muEndedTA(){const st=muState(),c=muCfg(),nm=S.settings.taName||"TA";
 const roll=Math.random()*100;
 if(roll<(c.next==null?15:c.next)){muTaSay(nm+" 切到了下一首");muTaNext(1);return true}
 if(roll<((c.next==null?15:c.next)+(c.rand==null?10:c.rand))){muTaSay(nm+" 随机挑了一首");muTaNext(2);return true}
 if(roll<((c.next==null?15:c.next)+(c.rand==null?10:c.rand)+(c.modeP==null?5:c.modeP))){
  const i=MU_MODES.findIndex(function(v){return v[0]===st.mode});st.mode=MU_MODES[(i+1)%MU_MODES.length][0];save("misc");
  muTaSay(nm+" 把播放模式换成了"+muModeName());muTaNext(1);return true}
 return false}
