ACT["mu-tafavdel"]=el=>{S.misc.muTaFavs=muTaFavs().filter(function(f){return f.id!==el.dataset.id});save("misc");render();toast("已移出 TA 的收藏")};
/* ================= TRACE · TA 的日常（参考 mochi：在哪里 / 在做什么 / 想对你说） ================= */
/* ================= 寻踪：TA 的日常 + TA 在身边（对齐 mochi 寻踪链路） ================= */
const TR_FB={place:["在家","在公司","在咖啡店","在公园","在图书馆","在路上"],action:["刷手机","看书","发呆","听歌","散步"],msg:["想你了","记得按时吃饭","早点休息","今天过得怎么样"]};
const TR_CATS=["寻踪·在哪里","寻踪·在做什么","寻踪·想对你说"];
/* TA 在身边：位置字卡分类（字卡库里维护）+ 方位感知固定词表 */
const LOC_CATS=["位置·方向","位置·距离","位置·状态","位置·感觉"];
const LOC_FB={dir:["在你左边","在你右边","在你身后","在你前面"],dist:["再近一点","再远一点","就停这儿"],state:["跟在你后面","陪你走着","在你身边"],sense:["一直没走远","隐约在你身旁","感觉到了吗"]};
const LOC_DIRECT=["正前方","右前方","右侧","右后方","后方","左后方","左侧","左前方","身边","无法判断"];
const LOC_ARROW={"正前方":"↑","右前方":"↗","右侧":"→","右后方":"↘","后方":"↓","左后方":"↙","左侧":"←","左前方":"↖"};
const LOC_RANGE=["很近","近","稍远","很远","无法判断"];
const LOC_POWER=["明显","微弱","若有若无","消失"];
const LOC_TOUCH=["好像碰到了你的手","有什么轻轻碰了一下你的肩","耳边好像有气息拂过","衣角被轻轻拉了一下"];
const LOC_EGG="在你心里";
const LOC_DIRMAP=[["左前方","左前方"],["左后方","左后方"],["左边","左侧"],["左侧","左侧"],["左","左侧"],["右前方","右前方"],["右后方","右后方"],["右边","右侧"],["右侧","右侧"],["右","右侧"],["正前","正前方"],["眼前","正前方"],["面前","正前方"],["前面","正前方"],["前方","正前方"],["正后","后方"],["背后","后方"],["身后","后方"],["后面","后方"],["后方","后方"],["旁边","身边"],["身边","身边"]];
/* 回到前台后给 90 秒冷静期，避免一回来就弹消息 */
let _wakeAt=0;
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")_wakeAt=Date.now()+90000});
/* ---------- TA 的日常 ---------- */
function trState(){const m=S.misc;m.trace=(m.trace&&typeof m.trace==="object")?m.trace:{};
 const t=m.trace;if(!t.cur||typeof t.cur!=="object")t.cur=null;if(!Array.isArray(t.hist))t.hist=[];if(typeof t.last!=="number")t.last=0;if(typeof t.next!=="number")t.next=0;return t}
function trCfg(){const r=S.settings.reply;r.trace=deepMerge({on:true,prob:100},r.trace||{});return r.trace}
function trPool(cat,fb){const a=cardTexts(cat);return a.length?a:fb}
function trGen(){const c={ts:Date.now(),place:pick(trPool(TR_CATS[0],TR_FB.place)),action:pick(trPool(TR_CATS[1],TR_FB.action)),msg:pick(trPool(TR_CATS[2],TR_FB.msg))};trState().cur=c;return c}
function trLine(c){return [c.place,c.action,c.msg].filter(Boolean).join(" · ")}
let _trLastRefresh=0;
function trDo(manual){const cfg=trCfg(),t=trState(),now=Date.now();
 if(manual&&now-_trLastRefresh<5000)return toast("刷新太频繁，稍后再试");
 if(manual)_trLastRefresh=now;
 if(!cfg.on&&!manual)return null;
 const c=trGen();t.hist.unshift(c);t.hist=t.hist.slice(0,80);t.last=now;t.next=1+Math.random()*7;save("misc");
 if(!manual&&chance(cfg.prob)){const nm=S.settings.taName||"TA";
  pushChat({type:"sys",text:nm+" 更新了一条日常"});
  pushChat({from:"ta",type:"text",text:trLine(c)});
  if(Math.random()<0.3){};
  notifyTA("更新了一条日常")}
 if(cur==="trace")render();else if(manual)toast("已更新 TA 的日常");
 return c}
function trCheck(){try{if(document.hidden)return;if(Date.now()<_wakeAt)return;const cfg=trCfg();if(!cfg||!cfg.on)return;const t=trState();
 if(!t.last){trDo(true);return}
 if((Date.now()-t.last)/36e5<t.next)return;trDo(false)}catch(e){}}
/* ---------- 寻踪记录：按月分组、可折叠 ---------- */
function trFold(){S.misc.trFold=(S.misc.trFold&&typeof S.misc.trFold==="object")?S.misc.trFold:{};return S.misc.trFold}
function trMonthKey(ts){const d=new Date(ts);return d.getFullYear()+"-"+(d.getMonth()+1)}
function trMonthLabel(ts){const d=new Date(ts);return d.getFullYear()+"年"+(d.getMonth()+1)+"月"}
function trHistHtml(){const t=trState();
 if(!t.hist.length)return '<div class="card"><div class="empty">还没有寻踪记录</div></div>';
 const fold=trFold(),now=new Date(),curKey=now.getFullYear()+"-"+(now.getMonth()+1);
 const groups=[],map={};
 t.hist.forEach((h,i)=>{const k=trMonthKey(h.ts||0);if(!map[k]){map[k]={k:k,label:trMonthLabel(h.ts||0),items:[]};groups.push(map[k])}map[k].items.push({h:h,i:i})});
 return groups.map(g=>{
  const on=(g.k in fold)?!!fold[g.k]:(g.k===curKey);
  return '<button class="mon" data-act="trace-mon" data-k="'+g.k+'"><span class="mk">'+esc(g.label)+'</span><span class="mc">'+g.items.length+' 条 <span class="lv'+(on?" on":"")+'">'+ico("next")+"</span></span></button>"+
   (on?'<div class="card" style="padding:2px 14px;margin-top:8px">'+g.items.map(it=>'<div class="hrow"><div class="hb"><div class="ht">'+esc(fmtTime(it.h.ts||0)+" · "+(it.h.place||"")+(it.h.action?" · "+it.h.action:""))+"</div>"+(it.h.msg?'<div class="hm">'+esc(it.h.msg)+"</div>":"")+'</div><button class="tldel" data-act="trace-del" data-i="'+it.i+'">删除</button></div>').join("")+"</div>":"");
 }).join("")}
/* ---------- TA 在身边（位置） ---------- */
const LOC_POWER_DESC={"明显":"感觉到了，很确定 TA 就在那儿。","微弱":"有，但很轻，像是错觉。","若有若无":"不太确定，好像有那么一点。","消失":"刚才似乎还在，现在已经感觉不到了。"};
const LOC_RING=[["正前方","t"],["右前方","tr"],["右侧","r"],["右后方","br"],["后方","b"],["左后方","bl"],["左侧","l"],["左前方","tl"]];
let _locDayOff=0;
function locState(){const m=S.misc;m.loc=(m.loc&&typeof m.loc==="object")?m.loc:{};
 const t=m.loc;if(!t.cur||typeof t.cur!=="object")t.cur=null;if(!Array.isArray(t.hist))t.hist=[];
 if(typeof t.last!=="number")t.last=0;if(typeof t.next!=="number")t.next=0;if(typeof t.eggLast!=="number")t.eggLast=0;if(typeof t.senseAt!=="number")t.senseAt=0;if(typeof t.hintAt!=="number")t.hintAt=0;
 t.sense=(t.sense&&typeof t.sense==="object")?t.sense:{};
 const s=t.sense;if(typeof s.dir!=="string")s.dir="";if(typeof s.nextDirAt!=="number")s.nextDirAt=0;
 if(typeof s.rangef!=="string")s.rangef="";if(typeof s.power!=="string")s.power="";if(typeof s.touch!=="string")s.touch="";if(typeof s.touchAt!=="number")s.touchAt=0;
 return t}
function locCfg(){const r=S.settings.reply;r.loc=deepMerge({auto:true,bubble:true,chat:true},r.loc||{});return r.loc}
function locCurText(){const t=locState();return t.cur&&t.cur.text?String(t.cur.text):""}
function locDirFromText(x){const s=String(x||"");for(const m of LOC_DIRMAP){if(s.indexOf(m[0])>=0)return m[1]}return ""}
function locCatOf(text){const x=String(text||""),names=["dir","dist","state","sense"];
 for(let i=0;i<4;i++){if(cardTexts(LOC_CATS[i]).indexOf(x)>=0)return names[i]}
 return ""}
function locFeelText(){const txt=locCurText(),nm=S.settings.taName||"TA";
 if(!txt)return "还没有感觉到 TA 的位置，点一下上面的「感知一下」。";
 const c=locCatOf(txt);if(c==="dir"||c==="dist")return nm+" "+txt+"。";
 return nm+" "+txt+"，就在身边。"}
function locGenAuto(avoid){const i0=["dir","dist","state","sense"];
 const soft=[].concat(cardTexts(LOC_CATS[2]).length?cardTexts(LOC_CATS[2]):LOC_FB.state,cardTexts(LOC_CATS[3]).length?cardTexts(LOC_CATS[3]):LOC_FB.sense);
 let all=[];LOC_CATS.forEach((c,i)=>{const a=cardTexts(c);all=all.concat(a.length?a:LOC_FB[i0[i]])});
 let pool=Math.random()<0.7?soft:all;if(!pool.length)pool=soft;if(!pool.length)pool=[LOC_EGG];
 if(pool.length>1&&avoid){const f=pool.filter(x=>x!==avoid);if(f.length)pool=f}
 return pick(pool)}
function locSetCur(text,kind,auto){const t=locState(),now=Date.now();
 t.cur={text:String(text||""),type:kind||"pos",ts:now,auto:!!auto};
 t.hist.unshift({k:"pos",text:String(text||""),type:kind||"pos",ts:now,auto:!!auto});t.hist=t.hist.slice(0,120);save("misc")}
function locSenseLine(){const s=locState().sense;return ((LOC_ARROW[s.dir]||"")+s.dir+" · "+(s.rangef||"")+" · "+(s.power||""))}
function locFire(text,kind,auto,feel){const cfg=locCfg(),t=locState(),nm=S.settings.taName||"TA",prev=locCurText();
 if(!text)return "";
 locSetCur(text,kind,auto);t.last=Date.now();t.next=2+Math.random()*4;save("misc");
 if(cfg.chat){pushChat({from:"ta",type:"text",text:text});playBlock("ta")}
 if(cfg.bubble&&text!==prev)toast((auto||feel)?("你感觉到 "+nm+" 换了位置："+text):("位置已更新："+text));
 if(cur==="trace"||cur==="loc")render();
 return text}
function locDo(manual){const cfg=locCfg(),t=locState();
 if(!manual&&!cfg.auto)return "";
 let text;
 if(chance(3)&&Date.now()-t.eggLast>7*864e5){t.eggLast=Date.now();text=LOC_EGG}
 else text=locGenAuto(locCurText());
 return locFire(text,manual?"pos":"auto",!manual,false)}
function locCombo(){const t=locState();
 if(chance(3)&&Date.now()-t.eggLast>7*864e5){t.eggLast=Date.now();return LOC_EGG}
 return pick(trPool(LOC_CATS[0],LOC_FB.dir))+" "+pick(trPool(LOC_CATS[1],LOC_FB.dist))}
function locAskWhere(){const nm=S.settings.taName||"TA";
 pushChat({from:"me",type:"text",text:"你在哪？"});playBlock("me");
 const ms=rnd(2000,4000);showTyping(true,ms);
 setTimeout(()=>{showTyping(false);const text=locCombo(),t=locState();
  locSetCur(text,"combo",false);t.last=Date.now();t.next=2+Math.random()*4;save("misc");
  pushChat({from:"ta",type:"text",text:text});playBlock("ta");
  if(cur==="trace"||cur==="loc")render();else toast(nm+"："+text)},ms)}
function locSense(){const t=locState(),s=t.sense,now=Date.now();
 if(now-t.senseAt<4000)return null;
 t.senseAt=now;
 let text;
 if(chance(3)&&now-t.eggLast>7*864e5){t.eggLast=now;text=LOC_EGG}
 else text=locGenAuto(locCurText());
 locFire(text,"pos",false,true);
 locSenseDir(true);
 s.rangef=pick(LOC_RANGE);s.power=pick(LOC_POWER);s.touch="";
 if(now-s.touchAt>3600000&&chance(4)){s.touch=pick(LOC_TOUCH);s.touchAt=now}
 t.hist.unshift({k:"sense",text:locSenseLine(),ts:Date.now(),auto:false});t.hist=t.hist.slice(0,120);
 save("misc");if(cur==="trace"||cur==="loc")render();
 return s}
/* 被动提示：每 30 秒一次检查，2% 概率冒一句（1 小时最多一次，和 mochi 一致） */
function locSenseDir(force){const t=locState(),s=t.sense,now=Date.now();
 const pin=locDirFromText(locCurText());
 if(pin){if(s.dir!==pin){s.dir=pin;save("misc")}return pin}
 if(force||!s.dir||now>=s.nextDirAt){const d=pick(LOC_DIRECT);s.dir=d;s.nextDirAt=now+rnd(15,45)*60000;save("misc");return d}
 return s.dir}
function locHintTick(){try{
 if(document.hidden)return;
 const win=Math.floor(Date.now()/30000);if(win===_hintTick)return;_hintTick=win;
 const t=locState(),now=Date.now();
 if(t.hintAt&&now-t.hintAt<3600000)return;
 if(Math.random()>=0.02)return;
 const dir=locSenseDir(false);
 if(!dir||dir==="无法判断"||dir==="身边")return;
 t.hintAt=now;save("misc");
 toast("……好像有人"+(LOC_ARROW[dir]?LOC_ARROW[dir]+" ":"")+"在你"+dir+"……")}catch(e){}}
let _hintTick=0;
function locCheck(){try{if(document.hidden)return;if(Date.now()<_wakeAt)return;const t=locState();if(!locCfg().auto)return;
 if(!t.last){locDo(true);return}
 if((Date.now()-t.last)/36e5<t.next)return;
 locDo(false)}catch(e){}}
/* 位置时间线：按天看 */
function locDayLabel(off){const d=new Date();d.setDate(d.getDate()-off);
 if(off===0)return "今天";if(off===1)return "昨天";return (d.getMonth()+1)+"月"+d.getDate()+"日"}
function locDayItems(off){const d=new Date();d.setHours(0,0,0,0);const a=d.getTime()-off*864e5,b=a+864e5;
 return locState().hist.map((e,i)=>({e:e,i:i})).filter(x=>x.e&&x.e.ts>=a&&x.e.ts<b)}
function locTlHtml(){const items=locDayItems(_locDayOff),older=locDayItems(_locDayOff+1).length>0;
 const body=items.length?items.map(x=>'<div class="tlrow"><span class="tlt">'+fmtTime(x.e.ts)+'</span><span class="tlb'+(x.e.k==="sense"?" sn":"")+'">'+esc(x.e.k==="sense"?("方位感知："+(x.e.text||"")):(x.e.text||""))+'</span><span class="tld"></span>'+(x.e.auto?'<span class="tltag">TA</span>':"")+'<button class="tldel" data-act="loc-tl-del" data-i="'+x.i+'">删除</button></div>').join(""):'<div class="empty">这天没有记录</div>';
 return '<div class="card" style="margin-top:12px"><div class="nt">位置时间线</div>'+
  '<div class="daynav"><button class="dnb l" data-act="loc-day" data-d="1" '+(older?"":"disabled")+">"+ico("next")+'</button><span class="dl">'+esc(locDayLabel(_locDayOff))+'</span><button class="dnb" data-act="loc-day" data-d="-1" '+(_locDayOff>0?"":"disabled")+">"+ico("next")+"</button></div>"+
  body+'<div class="tlcount">共 '+items.length+" 条</div></div>"}
/* ---------- 页面：寻踪 ---------- */
PAGES.trace={html(){const t=trState(),c=t.cur||{},nm=esc(S.settings.taName||"TA");
 return phead("寻踪")+
 '<div class="card">'+
  '<div class="chead"><span class="ctitle">'+nm+' 的日常</span><button class="pillbtn" data-act="trace-do">'+ico("refresh")+"刷新</button></div>"+
  '<div class="fld"><div class="k">'+nm+' 在哪里</div><div class="v">'+esc(c.place||"—")+'</div></div>'+
  '<div class="fld"><div class="k">'+nm+' 在做什么</div><div class="v">'+esc(c.action||"—")+'</div></div>'+
  '<div class="fld"><div class="k">'+nm+' 想对你说</div><div class="v">'+esc(c.msg||"—")+'</div></div>'+
  '<button class="locentry" data-act="loc-open"><span class="pin">'+ico("trace")+'</span><span class="tt"><b>TA在身边 · 位置感知</b><span>方位感知 · 位置时间线 · 换位开关</span></span><span class="ch">'+ico("next")+"</span></button>"+
 "</div>"+
 '<div class="sect">寻踪记录</div>'+trHistHtml()+
 '<div class="muted" style="padding:12px 2px 0">「寻踪·在哪里 / 寻踪·在做什么 / 寻踪·想对你说」在「字卡库」对应分类里维护，不想要的字卡可以在字卡库里屏蔽；日常约每 1~8 小时自动更新一次（开关和推送概率在「设置 → 回复设置」里）。</div>'},
 init(){}};
ACT["trace-do"]=()=>trDo(true);
ACT["trace-del"]=el=>{const t=trState();t.hist.splice(+el.dataset.i,1);save("misc");render();toast("已删除")};
ACT["trace-mon"]=el=>{const f=trFold(),k=el.dataset.k,now=new Date(),curKey=now.getFullYear()+"-"+(now.getMonth()+1);
 const cur=(k in f)?!!f[k]:(k===curKey);f[k]=!cur;save("misc");render()};
/* ---------- 页面：TA在身边 ---------- */
PAGES.loc={html(){const t=locState(),s=t.sense,lc=t.cur||{},lcfg=locCfg(),nm=esc(S.settings.taName||"TA"),dir=s.dir||"";
 const arrow=LOC_ARROW[dir]||"";
 const ring=LOC_RING.map(d=>'<span class="dc '+d[1]+(dir===d[0]?" on":"")+'">'+esc(LOC_ARROW[d[0]]||"")+"</span>").join("");
 return phead("TA在身边 · "+nm+" 的位置")+
 '<div class="sechead"><b>方位感知</b><span class="sub">不是精确定位 · 是你对 TA 的模糊感觉</span></div>'+
 '<div class="compass">'+ring+'<span class="me">你</span>'+(dir?'<span class="lb">'+esc(arrow+dir)+"</span>":"")+"</div>"+
 '<div class="stats">'+
  '<div class="st"><div class="k">方向</div><div class="v">'+esc(dir?(arrow+dir):"—")+'</div></div>'+
  '<div class="st"><div class="k">距离感</div><div class="v">'+esc(s.rangef||"—")+'</div></div>'+
  '<div class="st"><div class="k">感知强度</div><div class="v">'+esc(s.power||"—")+'</div></div>'+
 "</div>"+
 '<div class="btnrow" style="margin-top:16px"><button class="btn pri inkbtn" style="flex:1" data-act="loc-sense">'+ico("flower")+" 感知一下</button></div>"+
 (s.power?'<div class="note warm"><div class="nt2">方位感知 · '+nm+'</div><div class="nb">'+esc(LOC_POWER_DESC[s.power]||"")+"</div></div>":"")+
 '<div class="note warm"><div class="nt"><span class="dot"></span>你感觉到的</div><div class="nb">'+esc(locFeelText())+"</div></div>"+
 '<div class="note"><div class="nt">此刻的位置</div><div class="locnow"><span class="pin">'+ico("trace")+'</span><span class="tt"><b>'+esc(lc.text||"—")+"</b><span>位置卡 · "+(lc.ts?fmtTime(lc.ts):"—")+"</span></span></div></div>"+
 locTlHtml()+
 '<div class="muted" style="padding:12px 2px 0">光点落在哪儿，就是 TA 在哪儿：方位卡落在画面对应方向；距离卡、状态卡跟着最近一张方位卡的方向走——「再近一点」朝中间靠、「再远一点」朝外圈退开。</div>'+
 '<div class="card" style="margin-top:12px">'+
  '<div class="row"><span class="lab">TA 自动换位</span><label class="sw"><input type="checkbox" data-set="reply.loc.auto" '+(lcfg.auto?"checked":"")+'><i></i></label></div>'+
  '<div class="row"><span class="lab">换位提醒弹窗</span><label class="sw"><input type="checkbox" data-set="reply.loc.bubble" '+(lcfg.bubble?"checked":"")+'><i></i></label></div>'+
  '<div class="row"><span class="lab">换位发到聊天</span><label class="sw"><input type="checkbox" data-set="reply.loc.chat" '+(lcfg.chat?"checked":"")+'><i></i></label></div>'+
 "</div>"+
 '<div class="muted" style="padding:10px 2px 0">TA 自动换位：开启后每 2~6 小时随机换一次位置；内容 70% 是陪伴卡（在你身边／一直没走远等）、30% 从字卡库启用的位置卡里随机，每次换位都记进「位置时间线」，和上一次不同时才弹提醒。<br>换位提醒弹窗：TA 换位时顶部弹一条轻提示。<br>换位发到聊天：关掉后只记进「位置时间线」，不再发进聊天记录。<br>「感知一下」：点了会先让 TA 当场换一次位置、再按新位置报方位，不用等那 2~6 小时。</div>'+
 '<div class="btnrow" style="margin-top:16px"><button class="btn pri inkbtn" style="flex:1" data-act="loc-ask">问 '+nm+' 一声「你在哪?」</button></div>'},
 init(){}};
ACT["loc-open"]=()=>{_locDayOff=0;go("loc")};
ACT["loc-do"]=()=>locDo(true);
ACT["loc-ask"]=()=>locAskWhere();
ACT["loc-sense"]=()=>locSense();
ACT["loc-day"]=el=>{_locDayOff=Math.max(0,_locDayOff+(+el.dataset.d));render()};
ACT["loc-tl-del"]=el=>{const t=locState();t.hist.splice(+el.dataset.i,1);save("misc");render();toast("已删除")};
/* ================= POMODORO ================= */
PAGES.pomo={html(){return phead("番茄钟")+'<div class="pomoring" id="pring"><div class="in"><div class="tm" id="ptm">25:00</div><div class="muted" id="pmode">专注时间</div></div></div><div class="btnrow" style="justify-content:center"><button class="btn pri" data-act="pomo-toggle" id="pbtn">开始</button><button class="btn" data-act="pomo-reset">重置</button></div><div class="card" style="margin-top:16px"><div class="row"><span class="lab">今日完成番茄</span><span class="val" id="pcount">0</span></div><div class="row"><span class="lab">累计完成番茄</span><span class="val" id="pall">0</span></div></div>'},
 init(){pomoRender()}};
let pomo={left:25*60,mode:"focus",running:false,timer:null};
function pomoRender(){const tm=$("#ptm");if(!tm)return;tm.textContent=pad(Math.floor(pomo.left/60))+":"+pad(pomo.left%60);$("#pmode").textContent=pomo.mode==="focus"?"专注时间":"休息一下";const total=pomo.mode==="focus"?25*60:5*60;$("#pring").style.setProperty("--pg",((1-pomo.left/total)*100)+"%");const b=$("#pbtn");if(b)b.textContent=pomo.running?"暂停":"开始";const st=S.misc.pomo||{day:"",count:0,total:0};if(st.day!==dayKey(Date.now())){st.day=dayKey(Date.now());st.count=0}$("#pcount").textContent=st.count;$("#pall").textContent=st.total}
function pomoToggle(){if(pomo.running){clearInterval(pomo.timer);pomo.running=false}else{pomo.running=true;pomo.timer=setInterval(()=>{pomo.left--;if(pomo.left<=0){clearInterval(pomo.timer);pomo.running=false;playSoundName("ta","叮咚");if(pomo.mode==="focus"){const st=S.misc.pomo||{day:dayKey(Date.now()),count:0,total:0};if(st.day!==dayKey(Date.now())){st.day=dayKey(Date.now());st.count=0}st.count++;st.total++;S.misc.pomo=st;save("misc");toast("专注完成，休息 5 分钟");pomo.mode="break";pomo.left=5*60}else{toast("休息结束，开始专注");pomo.mode="focus";pomo.left=25*60}}pomoRender()},1000)}pomoRender()}
/* ================= PERIOD ================= */
/* ================= 经期（对齐 mochi：状态/预测/相位 + 提醒关心链） ================= */
const PC_SOON=["经期快到了，这几天早点休息、少熬夜","快来例假了，注意保暖、别贪凉","这几天可能会有点小情绪，我都在"];
const PC_IN=["经期辛苦啦，记得多喝热水、注意保暖","别硬撑，难受就躺一会儿，我陪着你","记得按时吃饭，凉的先别碰"];
const PC_LATE=["经期好像推迟了，别太紧张，注意休息；要是迟迟不来记得看看医生","已经推迟几天啦，要不要记一下，或者去医院看看？"];
function periodSet(){S.misc.periodSet=Object.assign({cycle:28,dur:5,luteal:14},S.misc.periodSet||{});
 const p=S.misc.periodSet;p.cycle=Math.max(15,Math.min(60,+p.cycle||28));p.dur=Math.max(2,Math.min(14,+p.dur||5));p.luteal=Math.max(7,Math.min(20,+p.luteal||14));return p}
function pcCfg(){S.misc.pcRemind=Object.assign({en:true,adv:[3,1,0],hour:9,prob:70,fired:{}},S.misc.pcRemind||{});const c=S.misc.pcRemind;
 if(!Array.isArray(c.adv))c.adv=[3,1,0];if(!c.fired||typeof c.fired!=="object")c.fired={};
 if(c.prob==null)c.prob=70;else c.prob=Math.max(0,Math.min(100,+c.prob||0));
 return c}
function pcDay(d){const x=d||new Date();return x.getFullYear()+"-"+pad(x.getMonth()+1)+"-"+pad(x.getDate())}
function pcMid(ds){const d=new Date(String(ds||"").slice(0,10)+"T00:00:00");d.setHours(0,0,0,0);return d.getTime()}
function pcTodayMid(){const d=new Date();d.setHours(0,0,0,0);return d.getTime()}
function periodIntervals(){const rs=S.periods.slice().sort((a,b)=>pcMid(a.start)-pcMid(b.start));const out=[];
 for(let i=1;i<rs.length;i++){const d=Math.round((pcMid(rs[i].start)-pcMid(rs[i-1].start))/864e5);if(d>=15&&d<=60)out.push(d)}
 return out.slice(-6)}
function periodInfo(){const p=periodSet(),rs=S.periods.slice().sort((a,b)=>pcMid(a.start)-pcMid(b.start));
 if(!rs.length)return null;const last=rs[rs.length-1];
 const iv=periodIntervals();let cl=p.cycle;
 if(iv.length){const s=iv.slice().sort((a,b)=>a-b);cl=s.length%2?s[(s.length-1)/2]:Math.round((s[s.length/2-1]+s[s.length/2])/2)}
 const st=pcMid(last.start),today=pcTodayMid();
 let inPeriod=false;
 if(!last.end){inPeriod=today>=st&&(today-st)<=(p.dur)*864e5}
 else{const en=pcMid(last.end);inPeriod=today>=st&&today<=en}
 const day=Math.floor((today-st)/864e5)+1;
 let nd=st+cl*864e5,g=0;while(nd<today&&g++<400)nd+=cl*864e5;
 const delay=Math.max(0,Math.round((today-(st+cl*864e5))/864e5));
 const dayCl=((day-1)%cl+cl)%cl+1,ovu=Math.max(1,cl-periodSet().luteal);
 const phase=inPeriod?"period":((dayCl>=ovu-5&&dayCl<=ovu+1)?"fertile":"safe");
 let reg="记录 3 次后显示";if(iv.length>=3){const mean=iv.reduce((a,b)=>a+b,0)/iv.length;
  const sd=Math.sqrt(iv.reduce((a,b)=>a+(b-mean)*(b-mean),0)/iv.length);const cv=mean?sd/mean:0;
  reg=cv<0.1?"很规律":(cv<0.2?"较规律":"不规律")}
 return {last:last,cl:cl,day:day,dayCl:dayCl,ovu:ovu,phase:phase,inPeriod:inPeriod,
  next:nd,toNext:Math.round((nd-today)/864e5),delay:delay,reg:reg,n:iv.length}}
function periodDataHtml(){const n=S.periods.length;let bytes=0;try{bytes=new Blob([JSON.stringify(S.periods)]).size}catch(e){bytes=JSON.stringify(S.periods).length}
 return '<div class="sect">经期 · 数据管理</div><div class="card">'+
  '<div class="row" style="border:none;padding-bottom:0"><span class="lab"><b>经期 · 数据管理</b></span><span class="val" data-act="period-dataall" style="color:var(--muted)">全部功能 ›</span></div>'+
  '<div class="muted" style="padding:4px 0 12px">'+n+" 次记录 · "+fmtBytes(bytes)+"</div>"+
  '<div class="btnrow even3"><button class="btn sm" data-act="period-export">导出数据</button><button class="btn sm" data-act="period-import">导入数据</button><button class="btn sm danger" data-act="period-clearall">清空数据</button></div>'+
 "</div>"}
function pcMon(){if(typeof S.misc.pcMon!=="string"||S.misc.pcMon.length!==7)S.misc.pcMon=pcDay().slice(0,7);return S.misc.pcMon}
function pcYmd(d){return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate())}
function periodHasDay(ds){for(let i=0;i<S.periods.length;i++){const r=S.periods[i];if(!r.start)continue;const s=String(r.start).slice(0,10);const e=r.end?String(r.end).slice(0,10):s;if(ds>=s&&ds<=e)return true}return false}
function periodRecOn(ds){for(let i=0;i<S.periods.length;i++){const r=S.periods[i];if(!r.start)continue;const s=String(r.start).slice(0,10);const e=r.end?String(r.end).slice(0,10):s;if(ds>=s&&ds<=e)return r}return null}
const PC_FLOWS=["少","中","多"];
const PC_SYMS=["痛经","腰酸","头痛","乳房胀痛","情绪波动","失眠","乏力","干净"];
const PC_MOODS=["好","一般","差"];
function periodCalHtml(){
 const inf=periodInfo(),p=periodSet(),ym=pcMon();
 const y=parseInt(ym.slice(0,4),10),m=parseInt(ym.slice(5,7),10);
 const lead=(new Date(y,m-1,1).getDay()+6)%7,days=new Date(y,m,0).getDate(),today=pcDay();
 let pred={},ovu="",i,k,d;
 if(inf){let nd=inf.next;
  for(k=0;k<3;k++){for(i=0;i<p.dur;i++){pred[pcYmd(new Date(nd+i*864e5))]=1}nd+=inf.cl*864e5}
  ovu=pcYmd(new Date(inf.next-p.luteal*864e5))}
 let wd="";const wk="一二三四五六日".split("");
 for(i=0;i<7;i++){wd+="<span>"+wk[i]+"</span>"}
 let cells="";
 for(i=0;i<lead;i++){cells+='<span class="pcc lead"></span>'}
 for(d=1;d<=days;d++){const ds=y+"-"+pad(m)+"-"+pad(d);let cls="pcc";
  if(periodHasDay(ds))cls+=" on";else if(pred[ds])cls+=" pred";else if(ds===ovu)cls+=" ovu";
  if(ds===today)cls+=" now";
  cells+='<button class="'+cls+'" data-act="period-day" data-d="'+ds+'">'+d+"</button>"}
 return '<div class="pmon"><button class="ibtn" data-act="period-mon" data-v="-1">'+ico("back")+"</button><b>"+y+" 年 "+m+' 月</b><button class="ibtn" data-act="period-mon" data-v="1">'+ico("next")+"</button></div>"+
  '<div class="pwk">'+wd+'</div><div class="pgrid">'+cells+"</div>"+
  '<div class="pleg"><span><i class="on"></i>经期</span><span><i class="pred"></i>预测</span><span><i class="ovu"></i>排卵</span></div>'}
function periodStatsHtml(){
 const iv=periodIntervals(),rs=S.periods.slice().sort(function(a,b){return String(a.start).localeCompare(String(b.start))});
 let avg="—",sum=0,i;
 if(iv.length){for(i=0;i<iv.length;i++){sum+=iv[i]}avg=Math.round(sum/iv.length)}
 let durs=[],avgD="—";
 for(i=0;i<rs.length;i++){const r=rs[i];if(r.end){durs.push(Math.max(1,Math.round((pcMid(r.end)-pcMid(r.start))/864e5)+1))}}
 if(durs.length){let s2=0;for(i=0;i<durs.length;i++){s2+=durs[i]}avgD=Math.round(s2/durs.length)}
 let html='<div class="row"><span class="lab">平均周期</span><span class="val">'+avg+' <span class="sub">天</span></span></div>'+
  '<div class="row"><span class="lab">平均经期</span><span class="val">'+avgD+' <span class="sub">天</span></span></div>'+
  '<div class="row"><span class="lab">记录次数</span><span class="val">'+rs.length+' <span class="sub">次</span></span></div>';
 const recent=rs.slice(-6).reverse();
 if(recent.length){html+='<div class="sect" style="margin:12px 2px 4px">最近记录</div>';
  for(i=0;i<recent.length;i++){const q=recent[i];
   html+='<div class="row"><span class="lab">'+esc(String(q.start).slice(0,10))+" ~ "+esc(q.end?String(q.end).slice(0,10):"进行中")+'</span><button class="ibtn" data-act="period-del" data-id="'+q.id+'" title="删除">'+ico("trash")+"</button></div>"}}
 return html}
function periodHeroHtml(){const inf=periodInfo();
 const cls=inf?(inf.inPeriod?"p-period":"p-safe"):"p-none";
 const t=inf?(inf.inPeriod?"经期中":"非经期"):"还没有记录";
 let sub2="点下面「标记今天开始」，或点日历里的某一天记录";
 if(inf){sub2=inf.inPeriod?("周期第 "+inf.dayCl+" 天 · 经期第 "+inf.day+" 天"):(inf.delay>0?("已推迟 "+inf.delay+" 天"):("周期第 "+inf.dayCl+" 天 · 距下次经期 "+Math.max(0,inf.toNext)+" 天"))}
 let pct=0;if(inf){pct=Math.round(inf.dayCl/Math.max(1,inf.cl)*100);if(pct<4)pct=4;if(pct>100)pct=100}
 let tags="";
 if(inf){tags="<span>上次 "+esc(String(inf.last.start).slice(5,10))+"</span><span>下次 "+esc(pcDay(new Date(inf.next)).slice(5,10))+"</span><span>规律性 "+esc(inf.reg)+"</span>"}
 return '<div class="pchero '+cls+'"><div class="phe1">'+esc(t)+'</div><div class="phe2">'+esc(sub2)+'</div><div class="phbar"><span style="width:'+pct+'%"></span></div><div class="phtags">'+tags+"</div></div>"}
PAGES.period={html(){const p=periodSet(),c=pcCfg();
 const row=(k,lb,unit)=>'<div class="row"><span class="lab">'+lb+'</span><input type="search" inputmode="numeric" data-pset="'+k+'" value="'+p[k]+'" style="width:74px;flex:none"><span class="sub">'+(unit||"")+"</span></div>";
 return phead("经期",'<button class="ibtn" data-act="period-set" title="设置">'+ico("dotsLine")+'</button>')+
 periodHeroHtml()+
 '<div class="card">'+
  '<div class="btnrow"><button class="btn pri" data-act="period-start" style="flex:1">标记今天开始</button><button class="btn" data-act="period-end" style="flex:1">标记今天结束</button></div>'+
 "</div>"+
 '<div class="card pcal">'+periodCalHtml()+"</div>"
 +'<div class="sect">统计</div><div class="card">'+periodStatsHtml()+"</div>"},
 init(){try{periodCareCheck()}catch(e){}}};
/* 经期设置（右上角 ⋯）：周期参数 / 提醒 / 数据管理 */
function periodSetSheetHtml(){const p=periodSet(),c=pcCfg();
 const adv=[3,1,0].map(function(d){return '<button class="chip'+(c.adv.indexOf(d)>=0?" on":"")+'" data-act="period-adv" data-v="'+d+'">'+(d===0?"当天":"前 "+d+" 天")+"</button>"}).join("");
 return '<div class="sect" style="margin:2px 2px 6px">周期参数</div>'+
  '<div class="card">'+
  '<div class="row"><span class="lab">周期长度 <span class="sub">天</span></span><input type="search" inputmode="numeric" data-pset="cycle" value="'+p.cycle+'" style="width:78px;flex:none"></div>'+
  '<div class="row"><span class="lab">经期天数 <span class="sub">天</span></span><input type="search" inputmode="numeric" data-pset="dur" value="'+p.dur+'" style="width:78px;flex:none"></div>'+
  '<div class="row"><span class="lab">黄体期 <span class="sub">天（算排卵用）</span></span><input type="search" inputmode="numeric" data-pset="luteal" value="'+p.luteal+'" style="width:78px;flex:none"></div>'+
  '<div class="muted" style="padding:4px 0 10px">记录 3 次后会按你最近几次的中位数自动校正周期长度。</div>'+
 "</div>"+
 '<div class="sect" style="margin:12px 2px 6px">提醒</div>'+
 '<div class="card">'+
  '<div class="row"><span class="lab">开启提醒<br><span class="sub">'+esc(S.settings.taName||"TA")+' 会在经期和快来时在聊天里关心你</span></span><label class="sw"><input type="checkbox" data-pcr="en" '+(c.en?"checked":"")+'><i></i></label></div>'+
  '<div class="row"><span class="lab">提前几天提醒</span><span class="chips">'+adv+"</span></div>"+
  '<div class="row"><span class="lab">提醒时间 <span class="sub">点</span></span><input type="number" data-pch="1" value="'+c.hour+'" style="width:78px;flex:none"></div>'+
  '<div class="row"><span class="lab">提醒概率 <span class="sub">%</span></span><span class="stepper"><button class="stbtn" data-pcp="-1">−</button><input class="stepnum" data-pcpnum value="'+c.prob+'" readonly><button class="stbtn" data-pcp="1">＋</button></span></div>'+
  '<div class="muted" style="padding:4px 0 10px">23:00~06:00 不打扰；同一件事一天最多提醒一次；概率调到 0 就不再主动关心。</div>'+
 "</div>"+
 '<div class="btnrow" style="margin-top:10px"><button class="btn" data-act="period-caregodo" style="flex:1">立即关心一次</button></div>'+
 periodDataHtml()}
/* 经期设置：改成整页（和聊天设置一样的形态，不再是弹窗卡片） */
PAGES.periodset={html(){return phead("经期设置")+'<div id="psbody">'+periodSetSheetHtml()+"</div>"},
 init(){const w=document.getElementById("psbody");if(!w)return;
  w.onchange=function(e){const el=e.target.closest("[data-pcr]");if(!el)return;const c=pcCfg();c[el.dataset.pcr]=!!el.checked;save("misc");toast("已保存")};
  w.onclick=function(e){const b=e.target.closest("[data-pcp]");if(!b)return;const c=pcCfg();
   c.prob=Math.max(0,Math.min(100,Math.round((+c.prob||0)+(+b.dataset.pcp)*5)));save("misc");
   const n=w.querySelector("[data-pcpnum]");if(n)n.value=c.prob;toast("提醒概率 "+c.prob+"%")}}};
ACT["period-set"]=()=>go("periodset");
function renderPeriod(){if(cur==="period")render()}
function periodPredict(){try{const i=periodInfo(),p=periodSet(),out=[];if(!i||!i.last)return out;const base=i.next||(pcMid(i.last.start)+i.cl*864e5);for(let k=0;k<12;k++){const s=base+k*i.cl*864e5;for(let d=0;d<p.dur;d++)out.push(s+d*864e5)}return out}catch(e){return []}}
/* 经期记录规范化：旧版按 UTC 存时间，早上 8 点前会被算成"昨天"，也容易重复点出多条。
   统一改成本地日期（YYYY-MM-DD），并把同一天的重复记录合并为一条。 */
function periodNormalize(){try{
 if(!Array.isArray(S.periods))return;
 let changed=false;
 const dayOf=function(x){try{if(!x)return "";return pcDay(new Date(x))}catch(e){return String(x).slice(0,10)}};
 S.periods.forEach(function(r){if(!r)return;
  const s=dayOf(r.start);if(s&&String(r.start)!==s){r.start=s;changed=true}
  if(r.end){const e=dayOf(r.end);if(e&&String(r.end)!==e){r.end=e;changed=true}}});
 const seen={},out=[];
 S.periods.forEach(function(r){if(!r||!r.start)return;
  const k=String(r.start);
  if(seen[k]!=null){const prev=out[seen[k]];if(prev){if(!prev.end&&r.end)prev.end=r.end;if(r.end&&prev.end&&String(r.end)>String(prev.end))prev.end=r.end}changed=true;return}
  seen[k]=out.length;out.push(r)});
 if(out.length!==S.periods.length){S.periods=out;changed=true}
 if(changed)save("periods")}catch(e){}}
function periodCareCheck(force){try{const c=pcCfg();if(!c.en&&!force)return;
 const h=new Date().getHours();if(h>=23||h<6)return;
 const info=periodInfo();if(!info)return;
 const nm=S.settings.taName||"TA",today=pcDay();
 let ctx="",text="";
 if(info.inPeriod){ctx="in";
  /* 提醒概率可在「经期设置」里用步进器调；手动「立即关心一次」不受概率限制 */
  if(!force&&!chance(c.prob))return;
  text=info.day<=2?("经期第 "+info.day+" 天了，记得多喝热水、注意保暖"):pick(PC_IN)}
 else{const d=info.toNext;
  if(c.adv.indexOf(d)<0)return;ctx="adv"+d;
  if(!force&&!chance(c.prob))return;
  text=(d===0&&info.delay>=5)?pick(PC_LATE):pick(PC_SOON)}
 if(!text)return;
 const key=today+"_"+ctx;if(!force&&c.fired[key])return;
 c.fired[key]=1;const ks=Object.keys(c.fired);if(ks.length>60)ks.slice(0,30).forEach(k=>{delete c.fired[k]});
 save("misc");
 pushChat({from:"ta",type:"text",text:text,tag:(ctx==="in"?"经期关心":"经期预警")})}catch(e){}}
function listStore(key){return S.misc[key]||(S.misc[key]=[])}
/* ================= 收藏（对齐 mochi：我的/联系人 · 分类 · 批量删除 · 数据管理 · 自动收藏；已去掉互动） ================= */
const FAV_KINDS=[["msg","聊天"],["mail","信件"],["feed","朋友圈"]];
const FAV_KIND_LABEL={msg:"聊天",mail:"信件",feed:"朋友圈"};
const FAV_EMPTY={msg:"聊天消息",mail:"信件",feed:"朋友圈"};
function favList(){const l=listStore("favs");let ch=false;
 l.forEach(f=>{if(!f.by){f.by=(f.who==="TA"?"ta":"me");ch=true}if(!f.kind){f.kind="msg";ch=true}if(f.who!==undefined){delete f.who;ch=true}});
 if(ch)save("misc");return l}
function favCfg(){const s=S.settings;s.fav=deepMerge({msg:30,mail:30,feed:30},s.fav||{});return s.fav}
function favTab(){return S.misc.favTab==="ta"?"ta":"mine"}
function favKind(){const k=S.misc.favKind;return FAV_KINDS.some(x=>x[0]===k)?k:""}
function favSel(){if(!Array.isArray(S.misc.favSel))S.misc.favSel=[];return S.misc.favSel}
function favBatchOn(){return !!S.misc.favBatch}
function favVisible(){const tab=favTab(),kind=favKind();
 let l=favList().filter(f=>(f.by||"me")===(tab==="ta"?"ta":"me"));
 if(kind)l=l.filter(f=>(f.kind||"msg")===kind);
 return l.slice().sort((a,b)=>(b.ts||0)-(a.ts||0))}
function favBytes(){try{return new Blob([JSON.stringify(favList())]).size}catch(e){return JSON.stringify(favList()).length}}
function favAdd(o){const l=favList();
 if(l.some(f=>f.by===o.by&&f.kind===o.kind&&f.text===o.text))return false;
 l.unshift(Object.assign({id:uid(),ts:Date.now()},o));save("misc");return true}
function favTabsHtml(){const t=favTab();
 return '<div class="chips favtabs" style="margin:2px 0 8px">'+[["mine","我的收藏"],["ta",(S.settings.taName||"TA")+" 的收藏"]].map(x=>'<button class="chip'+(t===x[0]?" on":"")+'" data-act="fav-tab" data-v="'+x[0]+'">'+x[1]+"</button>").join("")+"</div>"}
function favKindsHtml(){const k=favKind();
 return '<div class="chips favkinds" style="margin-bottom:12px">'+FAV_KINDS.map(x=>'<button class="chip'+(k===x[0]?" on":"")+'" data-act="fav-kind" data-v="'+x[0]+'">'+x[1]+"</button>").join("")+"</div>"}
function favItemHtml(f){const batch=favBatchOn(),on=favSel().indexOf(f.id)>=0;
 const pre=(f.kind==="mail"&&f.title)?'<b>'+esc(f.title)+"</b><br>":"";
 return '<div class="card favitem'+(on?" on":"")+'" data-act="fav-item" data-id="'+f.id+'">'+
  (batch?'<span class="favck">'+(on?ico("check"):"")+"</span>":"")+
  '<div class="favbody"><div class="favtext">'+pre+esc(String(f.text||"").slice(0,400))+"</div>"+
  '<div class="favmeta"><span class="favtag">'+FAV_KIND_LABEL[f.kind||"msg"]+"</span>"+fmtFull(f.ts||0)+"</div></div></div>"}
function favListHtml(){const list=favVisible(),tab=favTab(),kind=favKind();
 const title=tab==="ta"?((S.settings.taName||"TA")+" 的收藏"):"我的收藏";
 const empty=kind?((tab==="ta"?"TA 还没有":"暂无")+FAV_EMPTY[kind]):(tab==="ta"?"TA 还没有收藏":"暂无收藏");
 return '<div class="favhead"><b>'+esc(title)+'</b><span class="favcnt">'+list.length+"</span></div>"+
  (list.length?list.map(favItemHtml).join(""):'<div class="empty" style="padding:28px 0">'+esc(empty)+"</div>")}
function favDataHtml(){const n=favList().length;
 return '<div class="sect">收藏 · 数据管理</div><div class="card">'+
  '<div class="row" style="border:none;padding-bottom:0"><span class="lab"><b>收藏 · 数据管理</b></span><span class="val" data-act="fav-dataall" style="color:var(--muted)">全部功能 ›</span></div>'+
  '<div class="muted" style="padding:4px 0 12px">'+n+" 项 · "+fmtBytes(favBytes())+"</div>"+
  '<div class="btnrow"><button class="btn sm" data-act="fav-export">导出数据</button><button class="btn sm" data-act="fav-import">导入数据</button><button class="btn sm danger" data-act="fav-clear">清空数据</button></div>'+
 "</div>"}
function favBarHtml(){if(!favBatchOn())return "";
 const sel=favSel(),vis=favVisible(),all=vis.length>0&&vis.every(f=>sel.indexOf(f.id)>=0);
 return '<div class="favbar"><button class="btn" data-act="fav-bcancel">取消</button><button class="btn" data-act="fav-ball">'+(all?"取消全选":"全选")+'</button><button class="btn danger" data-act="fav-bdel" '+(sel.length?"":"disabled")+">删除"+(sel.length?"("+sel.length+")":"")+"</button></div>"}
PAGES.fav={html(){return phead("收藏",'<button class="ibtn'+(favBatchOn()?" sel":"")+'" data-act="fav-batch" title="批量管理">'+ico("check")+'</button><button class="ibtn" data-act="fav-set" title="收藏设置">'+ico("dotsLine")+"</button>")+
 favBarHtml()+favTabsHtml()+favKindsHtml()+favListHtml()},
 init(){}};
PAGES.favset={html(){const c=favCfg(),all=favList();
 const total=all.length,mine=all.filter(f=>(f.by||"me")!=="ta").length,ta=total-mine;
 const pct=(a,b)=>b<=0?0:Math.round(a/b*100);
 const rowP=(n,l)=>'<div class="row"><span class="lab">'+l+'</span><span class="val">'+n+' <span class="sub">'+pct(n,total)+'%</span></span></div>';
 const kindRows=FAV_KINDS.map(x=>{const tot=all.filter(f=>(f.kind||"msg")===x[0]).length;
  const t2=all.filter(f=>(f.by||"me")==="ta"&&(f.kind||"msg")===x[0]).length;
  return '<div class="row"><span class="lab">'+(x[0]==="msg"?"聊天消息":x[1])+'</span><span class="val">'+t2+" / "+tot+' <span class="sub">'+pct(t2,tot)+'% 来自 '+(S.settings.taName||"TA")+'</span></span></div>'}).join("");
 return phead("收藏设置")+
 '<div class="sect">收藏统计</div><div class="card">'+
  '<div class="row" style="border:none"><span class="lab"><b>收藏总览</b></span></div>'+
  '<div class="row"><span class="lab">总收藏</span><span class="val">'+total+' <span class="sub">条</span></span></div>'+
  rowP(mine,"我的收藏")+rowP(ta,(S.settings.taName||"TA")+" 收藏")+
  '<div class="row"><span class="lab"><b>分类统计（'+(S.settings.taName||"TA")+' / 总数）</b></span></div>'+kindRows+
 "</div>"+
  '<div class="sect">'+(S.settings.taName||"TA")+' 自动收藏概率</div><div class="card">'+
  setRowStep("收藏聊天消息","fav.msg","%",0,100,5)+
  setRowStep("收藏我的回信","fav.mail","%",0,100,5)+
  setRowStep("收藏朋友圈动态","fav.feed","%",0,100,5)+
  '<div class="muted" style="padding:8px 0 2px">'+(S.settings.taName||"TA")+' 在你发送内容后按概率自动收藏到「'+(S.settings.taName||"TA")+' 的收藏」。概率 0% 表示永不收藏，100% 表示每次都收藏。</div>'+
 "</div>"+favDataHtml()},init(){}};
/* ---- 自动收藏（触发点对齐 mochi：TA 回复我的消息 / 我寄出信 / 我发朋友圈） ---- */
function favLater(t){setTimeout(()=>toast(t),1200)}
function favTaCollectMsg(){try{const c=favCfg();if(Math.random()*100>=c.msg)return;
 const last=[...S.chats].reverse().find(m=>m.from==="me"&&m.type!=="sys");if(!last)return;
 const text=msgPlain(last);if(!text)return;
 if(favAdd({by:"ta",kind:"msg",side:"out",text:text}))favLater("TA 收藏了你的一条消息")}catch(e){}}
function favTaCollectMail(title,text){try{if(!String(text||"").trim())return;const c=favCfg();if(Math.random()*100>=c.mail)return;
 if(favAdd({by:"ta",kind:"mail",title:title||"",text:text}))favLater("TA 收藏了你的回信")}catch(e){}}
function favTaCollectFeed(text,imgs){try{if(!String(text||"").trim())return;const c=favCfg();if(Math.random()*100>=c.feed)return;
 if(favAdd({by:"ta",kind:"feed",text:text,imgs:(imgs||[]).slice(0,3)})){const mp=S.moments.find(function(x){return x.who==="me"&&String(x.content||"")===String(text||"")});if(mp){mp.taFav=true;save("moments")}favLater("TA 收藏了你的朋友圈动态")}}catch(e){}}
/* ---- 单条删除：长按（或右键）---- */
let _favLp=null,_favLpFired=false;
document.addEventListener("pointerdown",e=>{if(favBatchOn())return;
 const it=e.target.closest&&e.target.closest(".favitem");if(!it)return;clearTimeout(_favLp);
 _favLp=setTimeout(()=>{_favLp=null;_favLpFired=true;favDelAsk(it.dataset.id)},600)});
["pointerup","pointercancel","scroll"].forEach(ev=>document.addEventListener(ev,()=>{clearTimeout(_favLp);_favLp=null},true));
document.addEventListener("click",e=>{if(_favLpFired){_favLpFired=false;e.stopPropagation();e.preventDefault()}},true);
document.addEventListener("contextmenu",e=>{const it=e.target.closest&&e.target.closest(".favitem");if(!it)return;e.preventDefault();favDelAsk(it.dataset.id)});
function favDelAsk(id){if(!favList().some(f=>f.id===id))return;
 confirmDlg("删除这条收藏？","删除",true).then(ok=>{if(!ok)return;
  S.misc.favs=favList().filter(f=>f.id!==id);S.misc.favSel=favSel().filter(x=>x!==id);save("misc");render();toast("已删除")})}
ACT["fav-tab"]=el=>{S.misc.favTab=el.dataset.v;S.misc.favSel=[];save("misc");render()};
ACT["fav-kind"]=el=>{const v=el.dataset.v;S.misc.favKind=(favKind()===v?"":v);S.misc.favSel=[];save("misc");render()};
ACT["fav-batch"]=()=>{S.misc.favBatch=!favBatchOn();S.misc.favSel=[];save("misc");render();
 if(favBatchOn())toast("点选要删除的收藏")};
ACT["fav-item"]=el=>{if(!favBatchOn())return;const s=favSel(),i=s.indexOf(el.dataset.id);
 if(i>=0)s.splice(i,1);else s.push(el.dataset.id);save("misc");render()};
ACT["fav-ball"]=()=>{const vis=favVisible(),s=favSel();
 const all=vis.length>0&&vis.every(f=>s.indexOf(f.id)>=0);
 S.misc.favSel=all?[]:vis.map(f=>f.id);save("misc");render()};
ACT["fav-bcancel"]=()=>{S.misc.favBatch=false;S.misc.favSel=[];save("misc");render()};
ACT["fav-bdel"]=()=>{const s=favSel();if(!s.length)return;
 confirmDlg("删除选中的 "+s.length+" 条收藏？","删除",true).then(ok=>{if(!ok)return;
  S.misc.favs=favList().filter(f=>s.indexOf(f.id)<0);S.misc.favBatch=false;S.misc.favSel=[];save("misc");render();toast("已删除 "+s.length+" 条收藏")})};
ACT["fav-set"]=()=>go("favset");
ACT["fav-dataall"]=()=>{closeModal();go("setstore")};
ACT["fav-export"]=()=>{try{download("星笺收藏_"+dayKey(Date.now())+".json",JSON.stringify({app:"xingjian",ver:1,data:{favs:favList()}}));toast("已导出")}catch(e){toast("导出失败")}};
ACT["fav-import"]=()=>pickFile("application/json,.json",false,fs=>{readAsText(fs[0]).then(t=>{
 let o=null;try{o=JSON.parse(t)}catch(e){}
 if(!o||!o.data||!Array.isArray(o.data.favs))return toast("文件里没有收藏数据");
 actionSheet("导入方式",["合并到现有收藏","清空后导入"]).then(i=>{if(i==null)return;
  if(i===1)S.misc.favs=[];
  const l=favList(),inc=o.data.favs;let n=0;
  inc.forEach(f=>{const g=Object.assign({id:uid(),by:"me",kind:"msg"},f);if(!l.some(x=>x.by===g.by&&x.kind===g.kind&&x.text===g.text)){l.push(g);n++}});
  save("misc");render();toast("已导入 "+n+" 条收藏")})})});
ACT["fav-clear"]=()=>{confirmDlg("清空全部收藏数据？删除后无法恢复","清空",true).then(ok=>{if(!ok)return;
 S.misc.favs=[];S.misc.favSel=[];S.misc.favBatch=false;save("misc");render();toast("已清空收藏")})};
/* ================= 备忘录（对齐 mochi：置顶/截止/提醒渠道/清已完成/TA 催办） ================= */
const MEMO_ADDED=["记下来啦，我盯着你完成","嗯，我记着了","好的，一件一件来"];
const MEMO_ASK=["记好啦：「{m}」，打算什么时候做呀？","「{m}」收到了，我先盯着，做完跟我说一声？","又记下一件：「{m}」，什么时候开始？","「{m}」，可别让我催你哦"];
const MEMO_DONE=["又完成一件，好棒","进度 +1，继续呀","完成啦"];
const MEMO_ALLDONE=["都做完啦，真棒","全部完成，说到做到","清零啦，奖励一个抱抱"];
const MEMO_REMIND=["{m}——还躺在备忘录里哦，什么时候做呀？","翻到你的备忘：「{m}」，别忘了它","「{m}」还没完成呢，我先帮你记着","叮——备忘提醒：「{m}」，要开始了吗？"];
const MEMO_REMIND_DUE=["「{m}」今天到期啦，别忘了","提醒你：「{m}」就是今天哦","「{m}」今天截止，来得及，快去吧"];
const MEMO_REMIND_OVER=["「{m}」已经过期 {n} 天了哦，今天补上吧","「{m}」过期 {n} 天啦，要不清掉或改个日子？","{n} 天前记的「{m}」，还打算做吗？"];
function memoClip(x,n){x=String(x||"");return x.length>n?x.slice(0,n)+"…":x}
function memos(){const l=listStore("memos");let ch=false;
 l.forEach(m=>{if(!m.text&&m.t){m.text=m.t;delete m.t;ch=true}
  if(typeof m.done!=="boolean"){m.done=false;ch=true}
  if(typeof m.pin!=="boolean"){m.pin=false;ch=true}
  if(m.due===undefined)m.due=null;
  if(!m.remind||typeof m.remind!=="object"){m.remind={chat:1,sysDue:0,contact:0};ch=true}
  else{if(m.remind.chat===undefined)m.remind.chat=1;if(m.remind.sysDue===undefined)m.remind.sysDue=0;if(m.remind.contact===undefined)m.remind.contact=0}});
 if(ch)save("misc");return l}
function memoSendOn(){return S.misc.memoSend===true}
function memoCfg(){const m=S.misc;m.memoRemind=(m.memoRemind&&typeof m.memoRemind==="object")?m.memoRemind:{};
 const c=m.memoRemind;if(c.en===undefined)c.en=true;if(typeof c.prob!=="number")c.prob=2;if(typeof c.last!=="number")c.last=0;
 m.memoNewRemind=Object.assign({chat:1,sysDue:0,contact:0},m.memoNewRemind||{});return c}
function MEMO_D(ts){const d=new Date(ts||Date.now());return (d.getMonth()+1)+"月"+d.getDate()+"日 "+fmtTime(ts||Date.now())}
function MEMO_TODAY(){const d=new Date();return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate())}
function memoTs(str){const d=new Date(String(str)+"T00:00:00");return isNaN(d)?0:d.getTime()}
function memoUrgent(m){if(!m.due||m.done)return "";const a=memoTs(m.due),t=memoTs(MEMO_TODAY());
 if(a<t)return "overdue";if(a===t)return "today";return ""}
function memoOverDays(m){const a=memoTs(m.due),t=memoTs(MEMO_TODAY());return Math.max(1,Math.round((t-a)/864e5))}
function memoRank(m){return (m.pin?8:0)+((memoUrgent(m))?4:0)+(m.done?0:2)}
function memoSorted(){return memos().slice().sort((a,b)=>memoRank(b)-memoRank(a))}
function memoShowMsg(t){S.misc.memoMsg=t;save("misc");const el=document.getElementById("memomsg");if(el){el.textContent=t;el.classList.add("on")}}
function memoAdd(text){text=String(text||"").trim().slice(0,500);if(!text)return null;
 const m={id:uid(),text:text,done:false,pin:false,due:null,ts:Date.now(),
  remind:Object.assign({chat:1,sysDue:0,contact:0},S.misc.memoNewRemind||{})};
 memos().unshift(m);save("misc");
 pushChat({from:"ta",type:"text",text:pick(MEMO_ASK).replace("{m}",memoClip(text,16)),tag:"备忘"});
 if(Math.random()<.25)memoShowMsg(pick(MEMO_ADDED));
 if(cur==="memo")render();return m}
function memoGreet(){const list=memos(),undone=list.filter(m=>!m.done),nm=S.settings.taName||"TA";
 if(!list.length){memoShowMsg("把想做的事记下来，我帮你记着");return}
 if(undone.length>=2&&Math.random()<.12){
  const oldest=undone.slice().sort((a,b)=>(a.ts||0)-(b.ts||0))[0];oldest.done=true;save("misc");
  if(memoSendOn())pushChat({from:"ta",type:"text",text:"✓ "+nm+" 帮你完成：「"+memoClip(oldest.text,16)+"」"});
  memoShowMsg("帮你把「"+memoClip(oldest.text,12)+"」打勾啦，剩下的加油");
  return}
 const ur=undone.filter(m=>memoUrgent(m));
 if(ur.length&&Math.random()<.45){const m=ur[0];
  memoShowMsg(memoUrgent(m)==="overdue"?("「"+memoClip(m.text,12)+"」已经过期了哦，今天补上吧"):("「"+memoClip(m.text,12)+"」今天到期，别忘了"));return}
 const stale=undone.filter(m=>(Date.now()-(m.ts||0))>2*864e5);
 if(stale.length&&Math.random()<.3){memoShowMsg("有 "+stale.length+" 件事放了很久啦，先挑一件做掉？");return}
 memoShowMsg(undone.length?(Math.random()<.5?("还有 "+undone.length+" 件没做完呢，慢慢来"):pick(MEMO_ALLDONE)):pick(MEMO_ALLDONE))}
function memoToggle(id){const m=memos().find(x=>x.id===id);if(!m)return;m.done=!m.done;save("misc");
 if(m.done){const left=memos().filter(x=>!x.done).length;
  if(!left)memoShowMsg(pick(MEMO_ALLDONE));else if(Math.random()<.35)memoShowMsg(pick(MEMO_DONE));
  if(memoSendOn())pushChat({from:"ta",type:"text",text:"✓ 完成啦：「"+memoClip(m.text,16)+"」"})}
 if(cur==="memo")render()}
function memoSetDue(id,key){const m=memos().find(x=>x.id===id);if(!m)return;
 if(key==="clear"){m.due=null;toast("已清除截止")}
 else{const d=new Date();
  if(key==="tomorrow")d.setDate(d.getDate()+1);
  else if(key==="day2")d.setDate(d.getDate()+2);
  else if(key==="weekend"){const w=(6-d.getDay()+7)%7;d.setDate(d.getDate()+(w||7))}
  m.due=d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate());m.sysDueShown="";toast("已设置截止")}
 save("misc");if(cur==="memo")render()}
function memoShare(id){const m=memos().find(x=>x.id===id);if(!m)return;
 pushChat({from:"ta",type:"text",text:"备忘 · "+m.text+(m.due?"（"+m.due+" 截止）":"")});toast("已发送")}
function memoRowHtml(m){const ug=memoUrgent(m);
 const due=ug?(ug==="overdue"?'<span class="duebad">已过期 '+memoOverDays(m)+" 天</span>":'<span class="duebad">今天截止</span>'):(m.due?m.due+" 截止":"");
 const marks=["chat","sysDue","contact"].filter(k=>m.remind[k]).map(k=>'<span class="mmrm">'+ico(k==="chat"?"chat":k==="sysDue"?"bell":"users")+"</span>").join("");
 return '<div class="memoitem'+(m.done?" done":"")+(m.pin?" pinned":"")+(ug?" urgent":"")+'">'+
  '<button class="mmck" data-act="memo-done" data-id="'+m.id+'">'+(m.done?ico("check"):"")+"</button>"+
  '<div class="mmbody"><div class="mmtext" data-act="memo-edit" data-id="'+m.id+'">'+esc(m.text)+"</div>"+
  '<div class="mmtime">'+(due?due+" · ":"")+MEMO_D(m.ts)+"</div>"+
  (marks?'<div class="mmmarks" data-act="memo-remindset" data-id="'+m.id+'">'+marks+"</div>":"")+
  "</div>"+
  '<div class="mmactions">'+
   '<button class="ibtn" data-act="memo-due" data-id="'+m.id+'" title="截止日期">'+ico("cal")+"</button>"+
   '<button class="ibtn" data-act="memo-share" data-id="'+m.id+'" title="发给TA">'+ico("send")+"</button>"+
   '<button class="ibtn" data-act="memo-pin" data-id="'+m.id+'" title="置顶">'+ico("star")+"</button>"+
   '<button class="ibtn" data-act="memo-del" data-id="'+m.id+'" title="删除">'+ico("trash")+"</button>"+
  "</div></div>"}
function memoDataHtml(){const l=memos();let bytes=0;try{bytes=new Blob([JSON.stringify(l)]).size}catch(e){bytes=JSON.stringify(l).length}
 return '<div class="sect">备忘录 · 数据管理</div><div class="card">'+
  '<div class="row" style="border:none;padding-bottom:0"><span class="lab"><b>备忘录 · 数据管理</b></span><span class="val" data-act="memo-dataall" style="color:var(--muted)">全部功能 ›</span></div>'+
  '<div class="muted" style="padding:4px 0 12px">'+l.length+" 项 · "+fmtBytes(bytes)+"</div>"+
  '<div class="btnrow even3"><button class="btn sm" data-act="memo-export">导出数据</button><button class="btn sm" data-act="memo-import">导入数据</button><button class="btn sm danger" data-act="memo-clearall">清空数据</button></div></div>'}
PAGES.memo={html(){const list=memos(),un=list.filter(m=>!m.done),c=memoCfg(),nr=S.misc.memoNewRemind,rows=memoSorted();
 return phead("备忘录",'<button class="ibtn" data-act="memo-set" title="设置">'+ico("dotsLine")+'</button>')+
 '<div class="card">'+
  '<div class="memoinput"><input id="memo-inp" maxlength="200" placeholder="记一件想做的事…"><button class="btn pri" data-act="memo-addbtn">添加</button></div>'+
'<div class="chips memorchips">'+[["chat","聊天概率"],["sysDue","到点弹窗"],["contact",(S.settings.taName||"TA")+" 弹窗"]].map(x=>'<button class="chip'+(nr[x[0]]?" on":"")+'" data-act="memo-nr" data-v="'+x[0]+'">'+x[1]+"</button>").join("")+"</div>"+
  '<div class="memoMsg'+(S.misc.memoMsg?" on":"")+'" id="memomsg">'+esc(S.misc.memoMsg||"")+"</div>"+
  '<div class="memotools"><span class="muted">共 '+list.length+" 条 · 待办 "+un.length+'</span><button class="btn sm" data-act="memo-clear">清已完成</button></div>'+
  (rows.length?rows.map(memoRowHtml).join(""):'<div class="empty" style="padding:22px 0">还没有备忘<br>想做的事、要买的东西、突然的念头<br>都可以写在这里<br><button class="btn sm" style="margin-top:10px" data-act="memo-focus">↓ 在上面输入框写第一条</button></div>')+
 "</div>"},
 init(){memoGreet();const i=$("#memo-inp");if(i)i.addEventListener("keydown",function(e){if(e.key==="Enter"){e.preventDefault();ACT["memo-addbtn"]()}})}};
ACT["memo-focus"]=()=>{const el=$("#memo-inp");if(el)el.focus()};
ACT["memo-addbtn"]=()=>{const el=$("#memo-inp");if(!el)return;const t=el.value.trim();if(!t)return toast("先写点内容吧");el.value="";memoAdd(t)};
ACT["memo-nr"]=el=>{const k=el.dataset.v,nr=S.misc.memoNewRemind;nr[k]=nr[k]?0:1;save("misc");render()};
ACT["memo-done"]=el=>memoToggle(el.dataset.id);
ACT["memo-pin"]=el=>{const m=memos().find(x=>x.id===el.dataset.id);if(!m)return;m.pin=!m.pin;save("misc");render()};
ACT["memo-del"]=el=>{const m=memos().find(x=>x.id===el.dataset.id);if(!m)return;
 confirmDlg("删除这条备忘？删除后无法恢复","删除",true).then(ok=>{if(!ok)return;
  S.misc.memos=memos().filter(x=>x.id!==m.id);save("misc");render();toast("已删除")})};
ACT["memo-edit"]=async el=>{const m=memos().find(x=>x.id===el.dataset.id);if(!m)return;
 const t=await promptDlg("编辑备忘",m.text,true);if(t==null)return;const v=String(t).trim();if(!v)return;
 m.text=v.slice(0,500);m.ts=Date.now();save("misc");render()};
ACT["memo-due"]=el=>{const m=memos().find(x=>x.id===el.dataset.id);if(!m)return;
 const sh=openSheet('<div class="mtitle">设置截止日期<button class="ibtn" data-r="x">'+ico("close")+'</button></div><div class="muted" style="margin-bottom:8px">「'+esc(memoClip(m.text,14))+'」当前截止：'+esc(m.due||"未设置")+'</div>'+
  '<div class="chips">'+[["today","今天"],["tomorrow","明天"],["day2","后天"],["weekend","周末"],["clear","清除"]].map(x=>'<button class="chip" data-md="'+x[0]+'">'+x[1]+"</button>").join("")+"</div>",true);
 sh.onclick=e=>{const b=e.target.closest("[data-md]");if(b){closeModal();memoSetDue(m.id,b.dataset.md);return}
  if(e.target.closest("[data-r]"))closeModal()}};
ACT["memo-share"]=el=>memoShare(el.dataset.id);
ACT["memo-remindset"]=el=>{const m=memos().find(x=>x.id===el.dataset.id);if(!m)return;
 const paint=()=>openSheet('<div class="mtitle">提醒方式<button class="ibtn" data-r="x">'+ico("close")+'</button></div><div class="muted" style="margin-bottom:8px">「'+esc(memoClip(m.text,18))+'」点一项切换开关</div>'+
  '<div class="chips">'+[["chat","聊天概率提醒"],["sysDue","到点弹窗提醒"],["contact",(S.settings.taName||"TA")+" 弹窗提醒"]].map(x=>'<button class="chip'+(m.remind[x[0]]?" on":"")+'" data-mr="'+x[0]+'">'+x[1]+"</button>").join("")+"</div>",true);
 paint();
 $("#modal .sheet").onclick=e=>{const b=e.target.closest("[data-mr]");
  if(b){m.remind[b.dataset.mr]=m.remind[b.dataset.mr]?0:1;save("misc");paint();return}
  if(e.target.closest("[data-r]")){closeModal();if(cur==="memo")render()}}};
ACT["memo-clear"]=()=>{const d=memos().filter(m=>m.done);if(!d.length)return toast("没有已完成的");
 confirmDlg("清掉已完成的？将清除 "+d.length+" 条，无法恢复","清除",true).then(ok=>{if(!ok)return;
  S.misc.memos=memos().filter(m=>!m.done);save("misc");render();toast("已清理 "+d.length+" 条")})};
ACT["memo-send"]=()=>{S.misc.memoSend=!memoSendOn();save("misc");render();toast(memoSendOn()?"已开启：完成的备忘会发到聊天":"已关闭：完成的备忘不再发到聊天")};
ACT["memo-remind"]=()=>{const c=memoCfg();c.en=!c.en;save("misc");render();toast(c.en?"已开启：TA 会偶尔在聊天里提醒你的备忘":"已关闭：TA 不再提醒备忘")};
ACT["memo-prob"]=async()=>{const c=memoCfg();const v=await promptDlg("提醒触发概率（%）",String(c.prob),false);if(v==null)return;
 const n=Math.round(+v);if(!isFinite(n)||n<0||n>100)return toast("请输入 0-100 的整数");
 c.prob=n;save("misc");render();toast(n<=0?"已设置：基本不会触发":"已设置：每 4 分钟掷一次，命中后至少隔 2 天")};
ACT["memo-dataall"]=()=>{closeModal();go("setstore")};
/* 备忘录设置（右上角 ⋯）：完成发到聊天 / 备忘提醒 / 提醒概率（步进器）/ 数据管理 */
function memoSetHtml(){const c=memoCfg();
 return '<div class="card" style="padding:0 12px">'+
  '<div class="row"><span class="lab">完成发到聊天<br><span class="sub">勾选完成时，把这条发进聊天</span></span><label class="sw"><input type="checkbox" data-mset="send" '+(memoSendOn()?"checked":"")+'><i></i></label></div>'+
  '<div class="row"><span class="lab">备忘提醒<br><span class="sub">到点按概率提醒你</span></span><label class="sw"><input type="checkbox" data-mset="remind" '+(c.en?"checked":"")+'><i></i></label></div>'+
  '<div class="row"><span class="lab">提醒概率 <span class="sub">%</span></span><span class="stepper"><button class="stbtn" data-mprob="-1">−</button><input class="stepnum" data-mprobnum value="'+c.prob+'" readonly><button class="stbtn" data-mprob="1">＋</button></span></div>'+
  '<div class="muted" style="padding:4px 0 10px">提醒概率 0% = 从不提醒，100% = 每次都提醒。</div>'+
 "</div>"+memoDataHtml()}
/* 备忘录设置：改成整页 */
PAGES.memoset={html(){return phead("备忘录设置")+'<div id="msbody">'+memoSetHtml()+"</div>"},
 init(){const w=document.getElementById("msbody");if(!w)return;
  w.onchange=function(e){const el=e.target.closest("[data-mset]");if(!el)return;
   if(el.dataset.mset==="send"){if(!!el.checked!==!!memoSendOn())ACT["memo-send"]()}
   else if(!!el.checked!==!!memoCfg().en)ACT["memo-remind"]()};
  w.onclick=function(e){const b=e.target.closest("[data-mprob]");if(!b)return;const c=memoCfg();
   c.prob=Math.max(0,Math.min(100,Math.round((+c.prob||0)+(+b.dataset.mprob))));save("misc");
   const n=w.querySelector("[data-mprobnum]");if(n)n.value=c.prob}}};
ACT["memo-set"]=()=>go("memoset");
ACT["memo-export"]=()=>{try{download("星笺备忘录_"+dayKey(Date.now())+".json",JSON.stringify({app:"xingjian",ver:1,data:{memos:memos()}}));toast("已导出")}catch(e){toast("导出失败")}};
ACT["memo-import"]=()=>pickFile("application/json,.json",false,fs=>{readAsText(fs[0]).then(t=>{
 let o=null;try{o=JSON.parse(t)}catch(e){}
 if(!o||!o.data||!Array.isArray(o.data.memos))return toast("文件里没有备忘数据");
 actionSheet("导入方式",["合并到现有备忘","清空后导入"]).then(i=>{if(i==null)return;
  if(i===1)S.misc.memos=[];
  const l=memos();let n=0;
  o.data.memos.forEach(m=>{const g=Object.assign({id:uid(),done:false,pin:false,due:null,ts:Date.now()},m);
   if(!l.some(x=>x.text===g.text)){l.push(g);n++}});
  save("misc");render();toast("已导入 "+n+" 条备忘")})})});
ACT["memo-clearall"]=()=>{confirmDlg("清空全部备忘数据？删除后无法恢复","清空",true).then(ok=>{if(!ok)return;
 S.misc.memos=[];save("misc");render();toast("已清空备忘")})};
/* ---- 催办：每 4 分钟掷一次（06:00~23:00、命中后至少隔 2 天）---- */
function memoRemindFire(){const c=memoCfg();if(!c.en||!(c.prob>0))return;
 const h=new Date().getHours();if(h<6||h>=23)return;
 if(Date.now()-c.last<2*864e5)return;
 if(Math.random()*100>=c.prob)return;
 const cand=memos().filter(m=>!m.done&&(m.remind.chat||m.remind.contact));
 if(!cand.length)return;
 const over=cand.filter(m=>memoUrgent(m)==="overdue"),today=cand.filter(m=>memoUrgent(m)==="today");
 const stale=cand.filter(m=>(Date.now()-(m.ts||0))>2*864e5);
 const pool=over.length?over:(today.length?today:(stale.length?stale:cand));
 const m=pick(pool);let text;
 if(memoUrgent(m)==="overdue")text=pick(MEMO_REMIND_OVER).replace("{m}",memoClip(m.text,16)).replace("{n}",String(memoOverDays(m)));
 else if(memoUrgent(m)==="today")text=pick(MEMO_REMIND_DUE).replace("{m}",memoClip(m.text,16));
 else text=pick(MEMO_REMIND).replace("{m}",memoClip(m.text,16));
 const useContact=m.remind.contact&&(!m.remind.chat||Math.random()<.5);
 if(useContact)toast((S.settings.taName||"TA")+"："+text);
 else pushChat({from:"ta",type:"text",text:text,tag:"备忘提醒"});
 c.last=Date.now();save("misc");if(cur==="memo")render()}
