 const hit=memos().filter(m=>!m.done&&m.due===t&&m.remind.sysDue&&m.sysDueShown!==t).sort((a,b)=>(a.ts||0)-(b.ts||0))[0];
 if(!hit)return;hit.sysDueShown=t;save("misc");
