function mallCfg(){S.misc.mall=S.misc.mall||{};const m=S.misc.mall;
 m.wallet=m.wallet||{me:52000,ta:52000};if(typeof m.goods!=="undefined"&&!Array.isArray(m.goods))m.goods=[];
 if(!Array.isArray(m.goods))m.goods=[];
 if(!Array.isArray(m.wish))m.wish=[];if(!Array.isArray(m.wishTa))m.wishTa=[];if(!Array.isArray(m.box))m.box=[];
 if(!Array.isArray(m.wishTa))m.wishTa=[];
 if(!m.wishTa.length)m.wishTa=[{id:"w1",emoji:"🎧",name:"耳机",cat:"数码",wish:"想和你一起听歌",want:"gift"},{id:"w2",emoji:"🍰",name:"小蛋糕",cat:"甜点",wish:"想和你一起切一块",want:"me"}];
 if(!Array.isArray(m.cartTa))m.cartTa=[];
 return m}
function mallMoney(v){const n=+v||0;return String(Math.round(n*100)/100)}
function mallGoods(){const m=mallCfg();const def=MALL_DEF.map(function(g,i){return {id:"d"+i,emoji:g[0],name:g[1],price:g[2],cat:g[3],wish:g[4],def:true}}).filter(function(g){return (m.hideDef||[]).indexOf(g.id)<0});
 return def.map(function(g){return Object.assign({},g,{img:mallImgs()[g.id]||""})}).concat(m.goods.map(function(g){return {id:g.id,emoji:g.emoji||"🎁",img:mallImgs()[g.id]||g.img||"",name:g.name,price:+g.price||0,cat:g.cat||"礼物",wish:g.wish||"",custom:true}}))}
function mallFind(id){return mallGoods().find(function(g){return g.id===id})}
function mallWished(id){return mallCfg().wish.indexOf(id)>=0}
function mallWishToggle(id){const m=mallCfg();const i=m.wish.indexOf(id);
 if(i>=0){m.wish.splice(i,1);toast("已移出我的心愿")}else{m.wish.push(id);toast("已加入我的心愿")}
 save("misc");if(cur==="mall")render()}
function mallAddBox(dir,g,note){const m=mallCfg();m.box.unshift({dir:dir,emoji:g.emoji,name:g.name,price:g.price,note:note||"",ts:Date.now()});m.box=m.box.slice(0,200);save("misc")}
function mallTaReply(g){const s=S.settings.reply.mall=S.settings.reply.mall||{};const c=Object.assign({replyOn:true,replyPct:60},s);
 if(!c.replyOn)return;if(Math.random()*100>=(c.replyPct==null?60:c.replyPct))return;
 const inWish=mallCfg().wishTa.some(function(w){return w.name===g.name});
 
 const pool=inWish?["我的心愿被你实现啦！","真的买下啦…说好不让你乱花钱的","许愿时没想过真能收到，谢谢～","心愿单少了一件，开心值满格","你记得我的心愿，这个最戳我"]
  :["哇，谢谢亲爱的～","你怎么知道我想要这个！","收到啦，超喜欢❤","破费啦，我好好收着","嘿嘿，被你宠到了","这份我喜欢，收下啦"];
 const d=rnd(900,2400);showTyping(true,d);
 setTimeout(function(){showTyping(false);pushChat({from:"ta",type:"text",text:pick(pool)});playBlock("ta")},d)}
function mallSelfBuy(id,n){const g=mallFind(id);if(!g)return 0;const m=mallCfg();n=Math.max(1,+n||1);
 if(m.wallet.me<g.price*n)return -1;
 m.wallet.me-=g.price*n;let i;for(i=0;i<n;i++){mallAddBox("in",g,"自己买的")}
 save("misc");toast("已购买 "+g.name+(n>1?(" ×"+n):"")+"，记入购买记录");
 if(cur==="chat")0;return n}
function mallCartSheet(){const m=mallCfg();
 if(!Array.isArray(m.cart))m.cart=[];
 const rows=m.cart.map(function(it,i){const g=mallFind(it.gid);
  if(!g)return "";
  return '<div class="listitem"><div class="mico">'+esc(g.emoji||"🎁")+'</div><div class="main"><div class="t1">'+esc(g.name)+'</div><div class="t2">¥'+mallMoney(g.price)+"</div></div>"+
   '<span class="stepper" style="flex:none"><button class="stbtn" data-mcq="-1" data-i="'+i+'">−</button><input class="stepnum" value="'+it.n+'" readonly style="width:44px"><button class="stbtn" data-mcq="1" data-i="'+i+'">＋</button></span>'+
   '<button class="ibtn" data-mcdel="'+i+'" title="删除">'+ico("trash")+"</button></div>"}).join("");
 let total=0;m.cart.forEach(function(it){const g=mallFind(it.gid);if(g)total+=g.price*it.n});
 openSheet('<div class="mtitle">购物车<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  (rows?'<div class="card" style="padding:0 12px">'+rows+"</div>"+'<div class="row" style="border:none"><span class="lab">合计</span><span class="val"><b>¥'+mallMoney(total)+'</b> <span class="sub">余额 ¥'+mallMoney(m.wallet.me)+"</span></span></div>"+'<div class="btnrow" style="margin-top:10px"><button class="btn" data-mc="clr" style="flex:1">清空</button><button class="btn pri" data-mc="pay" style="flex:1">结算</button></div>':'<div class="empty" style="padding:26px 0">购物车是空的<br>在商品详情里点「加入购物车」</div>'),true);
 const sh=$("#modal .sheet");
 sh.onclick=function(e){
  const q=e.target.closest("[data-mcq]");
  if(q){const i=+q.dataset.i,it=m.cart[i];if(!it)return;it.n=Math.max(1,Math.min(99,it.n+(+q.dataset.mcq)));if(it.n<1)it.n=1;save("misc");closeModal();mallCartSheet();return}
  const d=e.target.closest("[data-mcdel]");
  if(d){m.cart.splice(+d.dataset.mcdel,1);save("misc");closeModal();mallCartSheet();if(cur==="mall")render();return}
  const b=e.target.closest("[data-mc]");
  if(b){if(b.dataset.mc==="clr"){m.cart=[];save("misc");closeModal();toast("已清空购物车");if(cur==="mall")render();return}
   let i,okAll=true;for(i=0;i<m.cart.length;i++){const it=m.cart[i];if(mallSelfBuy(it.gid,it.n)<0){okAll=false;break}}
   m.cart=okAll?[]:m.cart;save("misc");closeModal();if(cur==="mall")render();
   if(!okAll)toast("星币不够，部分商品没买到");return}
  if(e.target.closest("[data-r]"))closeModal()}}
ACT["mall-cart"]=()=>mallCartSheet();
function mallCfgProbs(){const s=S.settings.reply.mall=Object.assign({giftInOn:true,giftInPct:5,replyOn:true,replyPct:60,dailyMax:3,selfPct:25,cartSelf:55,cartMe:45,wantSelf:34,wantMe:33,wantGift:33},S.settings.reply.mall||{});return s}
function mallWantPick(){const c=mallCfgProbs();const a=Math.max(0,+c.wantSelf||0),b=Math.max(0,+c.wantMe||0),d=Math.max(0,+c.wantGift||0);
 const t=a+b+d;const r=Math.random()*(t>0?t:1);if(r<a)return "self";if(r<a+b)return "me";return "gift"}
function mallCartTA(){const m=mallCfg();if(!Array.isArray(m.cartTa))m.cartTa=[];return m.cartTa}
function mallTaPushCart(){
 const m=mallCfg();const nm=S.settings.taName||"TA";
 const all=mallGoods();if(!all.length)return;
 const g=pick(all);
 const want=(Math.random()*((+mallCfgProbs().cartSelf||0)+(+mallCfgProbs().cartMe||0)||1))<(+mallCfgProbs().cartSelf||0)?"self":"me";
 const ex=mallCartTA().filter(function(it){return it.gid===g.id&&it.want===want})[0];
 if(ex){ex.n=Math.max(1,Math.min(9,ex.n+1))}else{mallCartTA().push({gid:g.id,n:1,want:want})}
 save("misc");
 if(Math.random()<0.5){try{pushChat({from:"ta",type:"text",text:(want==="me"?("我把 "+g.emoji+" "+g.name+" 先放购物车了，等会儿给你"):("我把 "+g.emoji+" "+g.name+" 加购物车了，给自己买的")),tag:"商城"})}catch(e){}}
 if(cur==="mall")render()}
function mallCartAdd(id){const g=mallFind(id);if(!g)return;const m=mallCfg();if(!Array.isArray(m.cart))m.cart=[];
 const ex=m.cart.filter(function(it){return it.gid===id})[0];
 if(ex){ex.n=Math.max(1,Math.min(99,ex.n+1))}else{m.cart.push({gid:id,n:1})}
 save("misc");toast("已加入购物车：" + g.name)}
function mallCartSheet(){const m=mallCfg();if(!Array.isArray(m.cart))m.cart=[];
 const nm=S.settings.taName||"TA";
 let mine="",totalN=0,totalP=0;
 m.cart.forEach(function(it,i){const g=mallFind(it.gid);if(!g)return;totalN+=it.n;if(+g.price>0)totalP+=(+g.price)*it.n;
  mine+='<div class="listitem"><div class="mico">'+esc(g.emoji||"礼物")+'</div><div class="main"><div class="t1">'+esc(g.name)+'</div><div class="t2">'+((+g.price>0)?("¥"+mallMoney(g.price)):"心意")+"</div></div>"+
   '<span class="stepper" style="flex:none"><button class="stbtn" data-mcq="-1" data-i="'+i+'">−</button><input class="stepnum" value="'+it.n+'" readonly style="width:42px"><button class="stbtn" data-mcq="1" data-i="'+i+'">＋</button></span>'+
   '<button class="ibtn" data-mcdel="'+i+'" title="移除">'+ico("trash")+"</button></div>"});
 let ta="";
 mallCartTA().forEach(function(it,i){const g=mallFind(it.gid);if(!g)return;
  ta+='<div class="listitem"><div class="mico">'+esc(g.emoji||"礼物")+'</div><div class="main"><div class="t1">'+esc(g.name)+' <span class="muted">×'+it.n+'</span></div><div class="t2">'+esc(nm)+" "+(it.want==="me"?"要送给你的":"给自己买的")+"</div></div></div>"});
 openSheet('<div class="mtitle">购物车<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  '<div class="sect" style="margin:2px 2px 6px">我的购物车</div>'+
  (mine?('<div class="card" style="padding:0 12px">'+mine+"</div>"+'<div class="muted" style="padding:6px 2px 0">共 '+totalN+" 件"+(totalP?(" · 合计 ¥"+mallMoney(totalP)):"")+"</div>"):'<div class="card"><div class="empty" style="padding:18px 0">我还什么都没挑，去商品详情点「加入购物车」</div></div>')+
  '<div class="btnrow" style="margin-top:10px"><button class="btn" data-mc="clr" style="flex:1">清空</button><button class="btn pri" data-mc="send" style="flex:1">一起送给 TA</button></div>'+
  '<div class="sect" style="margin:16px 2px 6px">'+esc(nm)+' 的购物车</div>'+
  (ta?('<div class="card" style="padding:0 12px">'+ta+"</div>"):'<div class="card"><div class="empty" style="padding:18px 0">'+esc(nm)+" 还没往购物车里放东西</div></div>"),true);
 const sh=$("#modal .sheet");
 sh.onclick=function(e){
  const q=e.target.closest("[data-mcq]");
  if(q){const i=+q.dataset.i,it=m.cart[i];if(!it)return;it.n=Math.max(1,Math.min(99,it.n+(+q.dataset.mcq)));save("misc");closeModal();mallCartSheet();return}
  const d=e.target.closest("[data-mcdel]");
  if(d){m.cart.splice(+d.dataset.mcdel,1);save("misc");closeModal();mallCartSheet();return}
  const b=e.target.closest("[data-mc]");
  if(b){if(b.dataset.mc==="clr"){m.cart=[];save("misc");closeModal();toast("已清空我的购物车");if(cur==="mall")render();return}
   if(!m.cart.length){toast("购物车是空的");return}
   const list=m.cart.slice();m.cart=[];save("misc");closeModal();
   let i;for(i=0;i<list.length;i++){const g=mallFind(list[i].gid);if(!g)continue;
    pushChat({from:"me",type:"text",text:"[礼物] "+g.emoji+" "+g.name+(list[i].n>1?(" ×"+list[i].n):"")+(g.wish?("｜"+g.wish):""),tag:"商城"});
    mallAddBox("out",g,"");}
   try{playBlock("me")}catch(x){};toast("已一起送给 TA");if(cur==="mall")render();return}
  if(e.target.closest("[data-r]"))closeModal()}}
