function mallBuy(idOrG){const g=(idOrG&&typeof idOrG==="object")?idOrG:mallFind(idOrG);if(!g)return;const m=mallCfg();
 const sh=openSheet('<div class="mtitle">送给 TA<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  '<div style="text-align:center;font-size:15px;padding:2px 0 4px">'+esc(g.emoji+" "+g.name)+"</div>"+
  (g.wish?'<div class="muted" style="text-align:center;padding-bottom:6px">'+esc(g.wish)+"</div>":"")+
  '<textarea id="mg-note" maxlength="60" style="min-height:70px" placeholder="写给 TA 的话（可空）"></textarea>'+
  '<div class="btnrow" style="margin-top:12px"><button class="btn pri" data-mg="send" style="flex:1">送给 TA</button></div>',true);
 let sent=false;
 sh.onclick=function(e){const b=e.target.closest("[data-mg]");if(!b){if(e.target.closest("[data-r]"))closeModal();return}
  if(b.dataset.mg==="wish"){mallWishToggle(id);closeModal();return}
  if(sent)return;sent=true;
  const note=($("#mg-note")||{}).value||"";closeModal();
  pushChat({from:"me",type:"text",text:"[礼物] "+g.emoji+" "+g.name+(note?("｜"+note.trim()):""),tag:"商城"});
  playBlock("me");mallAddBox("out",g,note.trim());
  const w=mallCfg().wishTa.findIndex(function(x){return x.name===g.name});if(w>=0){mallCfg().wishTa.splice(w,1);save("misc")}
  toast("已送出");mallTaReply(g)}
}
function mallAuto(){try{const s=S.settings.reply.mall=S.settings.reply.mall||{};
 const c=Object.assign({giftInOn:true,giftInPct:5,buyWishPct:20,selfPct:10,chatOn:true,dailyMax:3},s);
 const m=mallCfg();const today=pcDay();if(m.dayKey!==today){m.dayKey=today;m.dayN=0;save("misc")}
 if(m.dayN>=(c.dailyMax==null?3:c.dailyMax))return;
 if(!c.giftInOn)return;
 const nm=S.settings.taName||"TA";
 if(Math.random()*100<(c.giftInPct==null?5:c.giftInPct)){
  const all=mallGoods().filter(function(g){return g.price>0});const g=pick(all);m.dayN++;save("misc");
  pushChat({from:"ta",type:"text",text:"[礼物] "+g.emoji+" "+g.name+(g.wish?("｜"+g.wish):""),tag:"商城"});
   mallAddBox("in",g,"");toast(nm+" 送了你一份礼物")}
  else if(Math.random()*100<(c.selfPct==null?25:c.selfPct)){mallTaPushCart()}}
 catch(e){}}
