/* ================= system loops ================= */
let wakeLock=null,silentNode=null;
/* 静音音频：设置里开了「后台保活」→ 一直保持；否则只要在通话，就临时保持音频会话 */
function silentWanted(){return !!((S.settings.system&&S.settings.system.keepalive)||callState)}
function silentSync(){
 if(silentWanted()){const a=ac();if(a&&!silentNode){try{const b=a.createBuffer(1,a.sampleRate,a.sampleRate);silentNode=a.createBufferSource();silentNode.buffer=b;silentNode.loop=true;const g=a.createGain();g.gain.value=.0001;silentNode.connect(g);g.connect(a.destination);silentNode.start()}catch(e){silentNode=null}}}
 else if(silentNode){try{silentNode.stop()}catch(e){}silentNode=null}}
function applySystem(){const s=S.settings.system;
 silentSync();
 if(!s.keepalive&&wakeLock){try{wakeLock.release()}catch(e){}wakeLock=null}
 if(s.notify&&("Notification" in window)&&Notification.permission==="default")Notification.requestPermission();
 bgStart()}
/* ================= 后台保活：Worker 心跳 + 回到前台自动补课 ================= */
let bgWorker=null,bgHiddenAt=0,bgLastTick=0;
function bgRunAll(){
 if(Date.now()-bgLastTick<3000)return;
 bgLastTick=Date.now();
 try{callTickRun()}catch(e){}
 try{trCheck()}catch(e){} try{locCheck()}catch(e){} try{locHintTick()}catch(e){}
 try{memoTick()}catch(e){} try{memoSysDue()}catch(e){}
 try{taMomentCheck()}catch(e){} try{taLetterCheck()}catch(e){}
 try{quizSetTickAll()}catch(e){} try{catchUpAsks()}catch(e){}
 try{mallAuto()}catch(e){} try{periodCareCheck()}catch(e){} try{avTick()}catch(e){}
}
/* 后台时用 Worker 心跳继续跑：Worker 不会被浏览器的「密集节流」压到 1 分钟一次
   通话期间强制启用（不看「后台保活」开关），这样通话计时与挂断判定不会被冻住 */
function bgStart(){const s=S.settings.system;const want=!!s.keepalive||!!callState;
 if(want&&!bgWorker){
  try{const url=URL.createObjectURL(new Blob(["let n=0;setInterval(function(){n++;postMessage(n)},12000)"],{type:"text/javascript"}));
   bgWorker=new Worker(url);bgWorker.onmessage=function(){if(document.hidden)bgRunAll()};
  }catch(e){bgWorker=null}}
 else if(!want&&bgWorker){try{bgWorker.terminate()}catch(e){}bgWorker=null}}
/* 回到前台：把离开期间该发生的事一次补上 */
function bgCatchUp(){const away=bgHiddenAt?Date.now()-bgHiddenAt:0;bgHiddenAt=0;
 if(away<60000)return;
 bgRunAll();
 try{offlineCheck(true)}catch(e){}
 try{toast("后台保活：已补上你离开的 "+Math.max(1,Math.round(away/60000))+" 分钟")}catch(e){}}
/* 全局省电：页面在后台、且没开「后台保活」时，所有周期检查直接跳过，避免无谓唤醒 */
function whenAwake(fn){return function(){if(document.hidden&&!(S.settings.system&&S.settings.system.keepalive))return;try{fn()}catch(e){}}}
let _muBeat=0;
document.addEventListener("visibilitychange",function(){
 try{
  if(document.hidden)document.documentElement.dataset.idle="1";
  else delete document.documentElement.dataset.idle;
 }catch(e){}
 if(document.hidden)bgHiddenAt=Date.now();
 else{bgCatchUp();try{callResync()}catch(e){}}});
window.addEventListener("focus",function(){if(!document.hidden&&bgHiddenAt)bgCatchUp()});
/* Page Lifecycle：标签页被系统冻结 / 解冻（安卓后台常见）→ 冻结前落盘，解冻后立刻同步 */
document.addEventListener("freeze",function(){try{callSaveState()}catch(e){};try{uiStateSave()}catch(e){}});
document.addEventListener("resume",function(){try{if(callState)callResync()}catch(e){};try{uiStateRestore()}catch(e){}});
/* ================= 前后台切换：保存 / 恢复界面状态 =================
   * 通话保持切后台前的形态（迷你半框 / 全屏）＋小窗位置；
   * 页面滚动位置（#app 与聊天消息列表）切回来停在原处，不跳到底；
   * 路由与通话状态一起存进 sessionStorage，被系统回收重开也能接着来。 */
const UI_STATE_KEY="xjUiState";
let suppressChatBottom=false;
function callMiniShown(){try{const m=$("#callMini");return !!(m&&m.style.display&&m.style.display!=="none")}catch(e){return false}}
function uiStateSave(){
 try{
  const sc=document.getElementById("chatscroll"),app=document.getElementById("app");
  sessionStorage.setItem(UI_STATE_KEY,JSON.stringify({
   route:cur,param:curParam||"",at:Date.now(),
   appTop:app?app.scrollTop:0,chatTop:sc?sc.scrollTop:0,
   call:callState?{mode:callState.mode,mini:callMiniShown(),miniPos:miniPos()}:null}))
 }catch(e){}}
function uiStateLoad(){try{const s=sessionStorage.getItem(UI_STATE_KEY);return s?JSON.parse(s):null}catch(e){return null}}
/* 只负责「通话形态」：没恢复出通话就返回 false，让调用方稍后重试（重开页面时通话是异步恢复的） */
function uiStateApplyCall(){
 const st=uiStateLoad();if(!st||!st.call)return true;
 if(!callState)return false;
 if(Date.now()-(st.at||0)>=6*3600000)return true;
 suppressChatBottom=true;setTimeout(function(){suppressChatBottom=false},900);
 try{
  const wantMini=!!st.call.mini,isMini=callMiniShown();
  if(wantMini){if(!isMini)callMinimize();applyMiniPos(st.call.miniPos)}
  else if(isMini)callRestore();
  setTimeout(function(){try{miniClamp()}catch(e){}},60)}catch(e){}
 /* 把"最终落定的形态"再写回盘里：这样连续被回收两次也能一直保持小窗＋原位置 */
 suppressChatBottom=false;
 try{callSaveState(true)}catch(e){}
 return true}
function uiStateRestore(){
 const st=uiStateLoad();if(!st)return;
 /* 路由：被回收重开后回到离开时那一页 */
 if(st.route&&st.route!==cur){try{go(st.param?st.route:st.route,st.param||undefined)}catch(e){}}
 /* 滚动位置：立刻放一次，再在布局稳定后补两次（键盘收起 / 补发离线消息都会改高度） */
 const put=function(){
  try{
   const app=document.getElementById("app"),sc=document.getElementById("chatscroll");
   if(app&&st.appTop)app.scrollTop=st.appTop;
   if(sc&&st.chatTop)sc.scrollTop=st.chatTop}catch(e){}};
 put();setTimeout(put,120);setTimeout(put,420);
 /* 通话形态：还原成离开前的样子（迷你就还是迷你＋原位置，全屏就还是全屏） */
 if(!uiStateApplyCall()){let n=0;const t=setInterval(function(){if(uiStateApplyCall()||++n>8){clearInterval(t)}},500)}}
document.addEventListener("visibilitychange",function(){
 if(document.hidden){try{uiStateSave()}catch(e){};return}
 try{uiStateRestore()}catch(e){}});
/* 离线消息提醒：离开 ≥10 分钟，回来按离开时长补 1~4 条 TA 的消息并提示 */
function offlineCheck(force){
 const s=S.settings;if(!s.system.offline)return;
 const now=Date.now(),last=S.misc.lastSeen||now;
 const el=now-last,mins=Math.floor(el/60000);
 S.misc.lastSeen=now;
 if(!force&&el<10*60000)return;
 if(mins<1)return;
 const n=Math.min(4,Math.max(1,Math.round(mins/20)));
 for(let i=0;i<n;i++){S.chats.push({id:uid(),from:"ta",type:"text",text:taTextContent(),ts:now-rnd(1,Math.max(2,mins))*60000})}
 save("chats");S.misc.unread=true;save("misc");renderTabbar();
 if(cur==="chat")renderMsgs();
 msgPop("你离开的 "+mins+" 分钟里，TA 给你留了 "+n+" 条消息");
}
setTimeout(function(){try{mediaRepairFlags()}catch(e){}},3200);
setTimeout(function(){try{periodNormalize()}catch(e){}},2600);
setInterval(()=>{if(!document.hidden){S.misc.lastSeen=Date.now();save("misc")}},60000);
document.addEventListener("visibilitychange",()=>{
 if(document.hidden){S.misc.lastSeen=Date.now();save("misc")}
 else{try{offlineCheck()}catch(e){}}});
window.addEventListener("pagehide",()=>{S.misc.lastSeen=Date.now();kvSet("misc",S.misc)});
/* ================= media helpers ================= */
/* ★ 图片 / 语音也从大数组里拆出来单独存：一条媒体一条记录（xjMedia:<宿主>:<id>:<槽位>），
   宿主对象只留 media / dataBytes 标记；需要显示或播放时按需读出来、放回原来的字段（老渲染代码不用改）。
   这样即使攒了几千张表情包、几百条语音，开机也只是读一份"清单"。 */
const MEDIA_PREFIX="xjMedia:";
const MEDIA_MIN=4096;                 /* 小于 4KB 的小图（图标之类）不折腾，留在原地 */
function mediaKey(owner,id,slot){return MEDIA_PREFIX+owner+":"+id+":"+(slot||"a")}
function mediaPut(owner,id,slot,blob){return kvSet(mediaKey(owner,id,slot),blob)}
function mediaGet(owner,id,slot){return kvGet(mediaKey(owner,id,slot))}
function mediaDel(owner,id,slot){return kvDel(mediaKey(owner,id,slot))}
function mediaHas(obj,field){return !!(obj&&(obj.media||obj[field]))}
function mediaUrlOf(obj,field){const v=obj&&obj[field];
 return (typeof v==="string"&&(v.indexOf("blob:")===0||v.indexOf("data:")===0))?v:""}
function dataUrlToBlobSync(u){try{
 const i=String(u).indexOf(",");if(i<0)return null;
 const head=String(u).slice(0,i),body=String(u).slice(i+1);
 const m=(head.match(/data:([^;]+)/)||[])[1]||"application/octet-stream";
 if(head.indexOf("base64")<0)return new Blob([decodeURIComponent(body)],{type:m});
 const bin=atob(body),n=bin.length,a=new Uint8Array(n);
 for(let k=0;k<n;k++)a[k]=bin.charCodeAt(k);
 return new Blob([a],{type:m})}catch(e){return null}}
function mediaSaveOwner(owner){try{if(owner==="c")save("cards");else if(owner==="m")save("chats");else save("moments")}catch(e){}}
/* 取出一条媒体并放回宿主对象的字段里（返回可直接用的 URL；读不到返回空串） */
/* 修复：个别消息的「已收纳」标记曾被误删（媒体记录其实还在）——按记录把标记/图片补回来。
   这样即使上一版把标记删掉了，刷新后图片、语音也会自动重新出现。 */
function mediaRepairFlags(){try{
 const list=(S.chats||[]).filter(function(m,i,arr){return m&&!m.data&&!m.media&&(m.type==="img"||m.type==="voice"||i>=arr.length-800)});
 if(!list.length)return;
 let i=0,n=0;
 const step=function(){
  if(i>=list.length){
   if(n){try{save("chats")}catch(e){};try{if(cur==="chat")renderMsgs("bottom")}catch(e){};try{toast("已恢复 "+n+" 条聊天图片/语音")}catch(e){}}
   return}
  const m=list[i++];
  mediaGet("m",m.id,"d").then(function(b){
   if(b){try{m.media=true;let u="";try{u=URL.createObjectURL(b)}catch(e){};if(u)m.data=u}catch(e){};n++}
   setTimeout(step,0)}).catch(function(){setTimeout(step,0)})};
 setTimeout(step,120)}catch(e){}}
function mediaLoad(owner,id,slot,obj,field){return new Promise(function(res){
 if(!obj)return res("");
 const v=obj[field];
 if(typeof v==="string"&&v&&v.indexOf("blob:")!==0)return res(v);
 if(v&&typeof v==="object"&&typeof v.size==="number"){try{return res(URL.createObjectURL(v))}catch(e){}}
 if(!obj.media)return res("");
 mediaGet(owner,id,slot).then(function(b){
  if(b===KV_ERR)return res("");if(!b){delete obj.media;return res("")}
  let u="";try{u=URL.createObjectURL(b)}catch(e){}
  try{if(u)obj[field]=u}catch(e){}
  res(u)}).catch(function(){res("")})})}
/* 把还留在数组里的媒体搬进独立记录（分片，不卡界面） */
function mFieldOf(f,item){return (typeof f==="function")?f(item):f}
function mSlotOf(s,item){return (typeof s==="function")?s(item):s}
function mediaShelve(owner,list,slotOf,fieldOf,onDone){try{
 const need=(list||[]).filter(function(x){
  if(!x||x.media)return false;
  const v=x[mFieldOf(fieldOf,x)];
  if(typeof v==="string")return v.indexOf("data:")===0&&v.length>=MEDIA_MIN;
  return !!(v&&typeof v==="object"&&typeof v.size==="number"&&v.size>=MEDIA_MIN)});
 if(!need.length)return;
 let i=0;
 const step=function(){
  if(i>=need.length){if(onDone)onDone();return}
  const x=need[i++],u=x[mFieldOf(fieldOf,x)];
  const blob=(typeof u==="string")?dataUrlToBlobSync(u):u;
  const put=(blob&&blob.size)?mediaPut(owner,x.id,mSlotOf(slotOf,x),blob):Promise.resolve();
  Promise.resolve(put).then(function(ok){if(ok===false)return;
   try{x.dataBytes=(blob&&blob.size)||x.dataBytes||0;x.media=true;delete x[mFieldOf(fieldOf,x)];mediaSaveOwner(owner)}catch(e){}
  }).catch(function(){}).then(function(){setTimeout(step,0)})};
 setTimeout(step,0)}catch(e){}}
/* 上次会话里留下的 objectURL 已经失效，开机清掉，让页面按需重新读 */
function mediaResetUrls(){try{
 const clr=function(list,field){(list||[]).forEach(function(x){if(!x)return;
  if(typeof x[field]==="string"&&x[field].indexOf("blob:")===0){try{delete x[field]}catch(e){};try{x.media=true}catch(e){}}})};
 clr(S.cards,"data");clr(S.chats,"data");clr(S.moments,"voiceData");
 (S.moments||[]).forEach(function(p){try{(p.imgs||[]).forEach(function(u,ix){
  if(p.imgMedia&&p.imgMedia[ix]&&typeof u==="string"&&u.indexOf("blob:")===0)p.imgs[ix]=""})}catch(e){}});
}catch(e){}}
/* 开机后统一整理：老数据里塞在数组里的图片/语音搬进独立记录 */
function mediaShelveAll(){try{
 mediaResetUrls();
 mediaShelve("c",S.cards,"d","data");
 mediaShelve("m",S.chats,"d","data");
 mediaShelve("f",S.moments,"v","voiceData");
 let n=0;
 (S.moments||[]).forEach(function(p){try{
  if(!p.imgMedia)p.imgMedia={};
  (p.imgs||[]).forEach(function(u,ix){
   if(p.imgMedia[ix])return;
   if(typeof u!=="string"||u.indexOf("data:")!==0||u.length<MEDIA_MIN)return;
   const b=dataUrlToBlobSync(u);if(!b)return;
   n++;mediaPut("f",p.id,"i"+ix,b).then(function(ok){if(ok===false)return;try{p.imgMedia[ix]=1;p.imgs[ix]=""}catch(e){}}).catch(function(){try{delete p.imgMedia[ix]}catch(e){}})});
  (p.cmts||[]).forEach(function(c){try{
   if(c&&!c.imgMedia&&typeof c.img==="string"&&c.img.indexOf("data:")===0&&c.img.length>=MEDIA_MIN){
    const b0=dataUrlToBlobSync(c.img);if(b0){n++;mediaPut("mc",c.id,"i",b0).then(function(ok){if(ok===false)return;try{c.imgMedia=1;c.img=""}catch(e){}}).catch(function(){try{delete c.imgMedia}catch(e){}})}}
   if(c&&!c.imgMedia&&c.img&&typeof c.img==="object"&&c.img.size>=MEDIA_MIN){mediaPut("mc",c.id,"i",c.img).then(function(){try{c.imgMedia=1;delete c.img}catch(e){}}).catch(function(){})}
   if(!c||c.media)return;
   const v=c.voiceData;if(!v)return;
   const b=(typeof v==="string")?dataUrlToBlobSync(v):v;
   if(!b||!b.size||b.size<MEDIA_MIN)return;
   n++;mediaPut("mc",c.id,"v",b).then(function(ok){if(ok===false)return;try{c.dataBytes=b.size;c.media=true;delete c.voiceData}catch(e){}}).catch(function(){})}catch(e){}});
 }catch(e){}});
 if(n)save("moments");
 if(n)try{toast("已整理 "+n+" 张图片/语音，之后开机更快")}catch(e){}
}catch(e){}}
/* 打开某个页面时，按需把该页面要显示/播放的媒体读出来 */
/* 从卡片取媒体塞进目标字段：拿到 Blob 或 dataURL 都行（开机整理会把它搬进独立记录） */
function mediaFromCardInto(card,obj,field,cb){
 try{
  if(!card){if(cb)cb();return}
  if(!card.media){try{if(card.data)obj[field]=card.data}catch(e){};if(cb)cb();return}
  mediaGet("c",card.id,"d").then(function(b){
   try{if(b&&b.size)obj[field]=b}catch(e){}
   if(cb)cb()}).catch(function(){if(cb)cb()})}catch(e){if(cb)cb()}}function mediaOnPage(){try{loadCardImgsIn(document);
 if(cur==="libcat")libLoadMedia(curParam);
 else if(cur==="chat")chatLoadMedia();
 else if(cur==="moments")feedLoadMedia();
}catch(e){}}
function libLoadMedia(cat){try{
 const items=(typeof cardsOf==="function"?cardsOf(cat):[]).filter(function(c){return c&&c.media&&!mediaUrlOf(c,"data")}).slice(0,libShowLimit);
 if(!items.length)return;
 let i=0,painted=0;
 const step=function(){
  if(i>=items.length){if(painted&&cur==="libcat")try{libRefresh(cat)}catch(e){};return}
  const c=items[i++];
  mediaLoad("c",c.id,"d",c,"data").then(function(){painted++;
   if(i%4===0&&cur==="libcat")try{libRefresh(cat)}catch(e){}
   setTimeout(step,0)}).catch(function(){setTimeout(step,0)})};
 setTimeout(step,60)}catch(e){}}
function chatLoadMedia(){try{
 const start=Math.max(0,(S.chats||[]).length-chatShowLimit);
  const items=(S.chats||[]).slice(start).filter(function(m){return m&&(m.type==="img"||m.data||m.media)&&!mediaUrlOf(m,"data")});
 if(!items.length)return;
 let i=0;
 const step=function(){
  if(i>=items.length)return;
  const m=items[i++];
  mediaLoad("m",m.id,"d",m,"data").then(function(u){
   try{const box=document.querySelector('.msg[data-id="'+m.id+'"] .bub');const im=box?box.querySelector(':scope > img'):null;if(im){if(u){im.src=u}else{im.remove();const sp=document.createElement("span");sp.className="muted msglost";sp.textContent="图片已丢失";box.appendChild(sp)}}}catch(e){}
   setTimeout(step,0)}).catch(function(){setTimeout(step,0)})};
 setTimeout(step,60)}catch(e){}}
/* 启动自愈：朋友圈/评论的图片、表情包只认长期数据（独立记录 / dataURL / 卡片 cid）；
   临时地址 blob: 一律尝试转存，绝不删除任何还能用的图片。 */
let _momSaveT=0;
function saveMomentsSoon(){if(_momSaveT)clearTimeout(_momSaveT);_momSaveT=setTimeout(function(){_momSaveT=0;try{save("moments")}catch(e){}},350)}
function feedMediaRepair(){try{
 const jobs=[];
 (S.moments||[]).forEach(function(p){
  (p.cmts||[]).forEach(function(c){
   if(!c)return;const v=c.img;
   if(typeof v==="string"&&v.indexOf("data:")===0&&v.length>=MEDIA_MIN){const b=dataUrlToBlobSync(v);if(b)mediaPut("mc",c.id,"i",b).then(function(ok){if(ok===false)return;c.imgMedia=1;c.img="";saveMomentsSoon()});return}
   if(!v||typeof v!=="string"||v.indexOf("blob:")===0)jobs.push({own:"mc",id:c.id,slot:"i",obj:c,idx:-1,cid:c.stkCid});
  });
  (p.imgs||[]).forEach(function(u,ix){
   if(typeof u==="string"&&u.indexOf("data:")===0&&u.length>=MEDIA_MIN){const b=dataUrlToBlobSync(u);if(b)mediaPut("f",p.id,"i"+ix,b).then(function(ok){if(ok===false)return;p.imgMedia=p.imgMedia||{};p.imgMedia[ix]=1;p.imgs[ix]="";saveMomentsSoon()});return}
   if(!u||typeof u!=="string"||u.indexOf("blob:")===0)jobs.push({own:"f",id:p.id,slot:"i"+ix,obj:p,idx:ix,cid:(p.imgCids&&p.imgCids[ix])||(ix===0?p.stkCid:"")});
  });
  if(p.stkCid&&(!p.imgs||p.imgs.length===0))jobs.push({own:"f",id:p.id,slot:"i0",obj:p,idx:0,cid:p.stkCid});
 });
 let i=0;
 const apply=function(j){
  if(j.own==="mc"){j.obj.imgMedia=1;j.obj.img=""}
  else{j.obj.imgMedia=j.obj.imgMedia||{};j.obj.imgMedia[j.idx]=1;j.obj.imgs[j.idx]=""}
  saveMomentsSoon();
 };
 const step=function(){
  if(i>=jobs.length){if(jobs.length)setTimeout(function(){try{feedLoadMedia();if(cur==="moments")renderMoments()}catch(e){}},400);return}
  const j=jobs[i++];
  mediaGet(j.own,j.id,j.slot).then(function(b){
   if(b&&b.size){apply(j);step();return}
   if(!j.cid){step();return}
   mediaGet("c",j.cid,"d").then(function(cb){if(cb&&cb.size)mediaPut(j.own,j.id,j.slot,cb).then(function(ok){if(ok!==false)apply(j);step()});else step()}).catch(function(){step()});
  }).catch(function(){step()});
 };
 step();
}catch(e){}}
function feedLoadMedia(){try{
 const list=(S.moments||[]),jobs=[];
 (S.moments||[]).forEach(function(p){try{(p.cmts||[]).forEach(function(c){
  if(c&&c.imgMedia&&!c.img)jobs.push([null,0,c]);})}catch(e){}});
 list.forEach(function(p){if(!p||!p.imgMedia)return;
  (p.imgs||[]).forEach(function(u,ix){if(p.imgMedia[ix]&&!u)jobs.push([p,ix])})});
 if(!jobs.length)return;
 let i=0;
 const step=function(){
  if(i>=jobs.length)return;
  const pr=jobs[i++],p=pr[0],ix=pr[1],cc=pr[2];
  if(cc){mediaGet("mc",cc.id,"i").then(function(b){if(!b)return;let u="";try{u=URL.createObjectURL(b)}catch(e){}
   if(u){try{cc.img=u}catch(e){};try{const im=document.querySelector('[data-mid="'+cc.id+'"]');if(im)im.src=u}catch(e){}}}).catch(function(){}).then(function(){setTimeout(step,0)});return}
  mediaGet("f",p.id,"i"+ix).then(function(b){if(!b)return;
   let u="";try{u=URL.createObjectURL(b)}catch(e){}
   if(u){try{p.imgs[ix]=u}catch(e){}
    try{const im=document.querySelector('img[data-mid="'+p.id+'"][data-mi="'+ix+'"]');if(im)im.src=u}catch(e){}}}).catch(function(){}).then(function(){setTimeout(step,0)})};
 setTimeout(step,60)}catch(e){}}
/* 新发的消息里带图片/语音：立刻存成独立记录（内存里保留 objectURL，界面即时可见） */
function mediaShelveMsg(m){try{
 if(!m||!m.data||m.media)return;
 const v=m.data;
 if(typeof v==="string"&&v.indexOf("data:")!==0)return;
 const blob=(typeof v==="string")?dataUrlToBlobSync(v):v;
 if(!blob||!blob.size||blob.size<MEDIA_MIN)return;
 /* 写成功后才标记，失败则保持内嵌数据 */
 const u=URL.createObjectURL(blob);
 mediaPut("m",m.id,"d",blob).then(function(ok){if(ok===false)return;try{m.dataBytes=blob.size;m.media=true;m.data=u;save("chats")}catch(e){}}).catch(function(){try{delete m.media;delete m.dataBytes;m.data=(typeof v==="string")?v:u;save("chats")}catch(e){}})
}catch(e){}}
/* 聊天图片加载失败（例如刷新后临时地址 blob: 失效）：自动去独立记录里重取一次；
   再取不到才显示「图片已丢失」。这样历史表情包不会变成破图。 */
document.addEventListener("error",function(e){try{
 var im=e.target;
 if(!im||im.tagName!=="IMG"||!im.getAttribute("data-mid"))return;if(!im.closest||!im.closest("#msgs"))return;
 var id=im.getAttribute("data-mid");
 mediaGet("m",id,"d").then(function(b){
  if(!b){
   try{var box=im.parentNode;im.remove();if(box&&box.querySelectorAll("img").length===0){var sp=document.createElement("span");sp.className="muted msglost";sp.textContent="图片已丢失";box.appendChild(sp)}}catch(x){}
   return;
  }
  var u="";try{u=URL.createObjectURL(b)}catch(x){}
  if(u){try{im.src=u}catch(x){}}
 }).catch(function(){});
}catch(err){}},true);
/* 朋友圈：评论里的表情包/图片、动态里的图片，加载失败时自动从独立记录重取一次
   （评论图片存 mc 记录；动态图片存 f + "i索引" 记录） */
document.addEventListener("error",function(e){try{
 var im=e.target;
 if(!im||im.tagName!=="IMG")return;
 var mid=im.getAttribute("data-mid");if(!mid)return;
 var mi=im.getAttribute("data-mi");
 if(mi===null){
  if(!im.closest||!im.closest(".fcmt"))return;
  mediaGet("mc",mid,"i").then(function(b){
   if(!b)return;
   var u="";try{u=URL.createObjectURL(b)}catch(x){}
   if(u){try{im.src=u}catch(x){}}
  }).catch(function(){});
  return;
 }
 mediaGet("f",mid,"i"+mi).then(function(b){
  if(!b)return;
  var u="";try{u=URL.createObjectURL(b)}catch(x){}
  if(u){try{im.src=u}catch(x){}}
 }).catch(function(){});
}catch(err){}},true);
function mediaUrl(data,key){if(!data)return "";if(typeof data==="string")return data;if(!(data instanceof Blob)&&!(data&&typeof data.size==="number"&&data.size>0))return "";if(customUrlCache[key])return customUrlCache[key];const u=URL.createObjectURL(data);customUrlCache[key]=u;return u}
function blobToDataUrl(b){return new Promise(res=>{const r=new FileReader();r.onload=()=>res(r.result);r.readAsDataURL(b)})}
function dataUrlToBlob(u){return fetch(u).then(r=>r.blob())}
/* bubble with proactive tag image */
function msgBubble(m){if(m.type==="sys")return '<div class="sysmsg">'+(m.nickKeep?esc(m.text):esc(nickFill(m.pat?m.pat:m.text)))+(m.img?'<img src="'+m.img+'" alt="">':"")+"</div>";
 const me=m.from==="me";const s=S.settings;const c=s.chat||{};let inner="";
 /* 引用预览：图片/表情包/语音气泡也要显示引用（否则「引用后发图片」会看不到引用了谁） */
 const qh=m.quote?('<span class="q"'+(m.quoteId?' data-act="locate-quote" data-qid="'+m.quoteId+'"':"")+'>'+quoteHtml(m.quote,m.quoteId)+"</span>"):"";
  if(m.type==="img")inner=qh+((!m.data&&!m.media)?'<span class="muted msglost">图片已丢失</span>':'<img data-mid="'+m.id+'" src="'+mediaUrl(m.data,"m"+m.id)+'" class="'+(m.stk?"stk":"")+(msgMulti?"":" zoomable")+'"'+(msgMulti?"":' data-act="img-view"')+">"+(m.text?'<span class="vtext">'+esc(m.text)+"</span>":""));
 else if(m.type==="voice")inner=qh+((!m.data&&!m.media)?'<span class="muted msglost">语音已丢失</span>':'<span class="voice" data-act="play-voice" data-id="'+m.id+'"><span class="vico">'+ico("voicewave")+"</span><span class=\"vdur\">"+(m.dur||2)+'″</span></span>')+(m.text?'<span class="vtext">'+esc(m.text)+"</span>":"");
  else if(m.type==="transfer"||m.type==="redpacket")inner=txBubbleHtml(m,me);
 else if(m.type==="ask")inner=askBubbleHtml(m)
else if(m.type==="quizset")inner=quizSetBubbleHtml(m)
else if(m.type==="quiz")inner=quizBubbleHtml(m);
  else inner=(m.tag?'<span class="msgtag">'+tagHtml(m.tag)+"</span>":"")+(m.quote?'<span class="q"'+(m.quoteId?' data-act="locate-quote" data-qid="'+m.quoteId+'"':"")+'>'+quoteHtml(m.quote,m.quoteId)+"</span>":"")+(m.tagImg?'<img src="'+m.tagImg+'" style="max-width:80px;margin-bottom:4px">':"")+esc(m.text||"")+((m.data||m.media)?'<img class="bubimg'+(m.stk?" stk":"")+(msgMulti?"":" zoomable")+'" data-mid="'+m.id+'"'+(msgMulti?"":' data-act="img-view"')+' src="'+mediaUrl(m.data,"m"+m.id)+'">':"");
 /* 撤回：默认只显示提示文字；点一下 → 就地还原成原本那条消息，再点一下收回 */
 if(m.retracted){
  inner=m.showRet
   ? '<span class="retback" data-act="view-retract" data-id="'+m.id+'" title="点击收回">'+inner+"</span>"
   : '<span class="retline" data-act="view-retract" data-id="'+m.id+'" title="点击查看原文"><i class="muted">'+(me?"我":"对方")+"撤回了一条消息</i></span>";
 }
 const avaImg=avatarSrc(me?"me":"ta");
 const ava=avatarHtml({src:avaImg,size:c.avaSize,shape:c.avaShape,name:me?s.myName:s.taName,me:me});
 const rd=(me&&c.read&&m.read)?'<span class="rd">已读</span>':"";
 const meta='<span class="meta"><span class="tm">'+fmtMsgTime(m.timestamp||m.ts)+'</span>'+rd+'</span>';
 const selc=(msgMulti&&msgSel.has(m.id))?" selected":"";
 return '<div class="msg '+(me?"me":"")+selc+'" data-id="'+m.id+'"><button class="ava-hit">'+ava+'</button><div class="msgcol"><div class="bub message '+(me?"message-sent":"message-received")+(m.type==="ask"||m.type==="quizset"||m.type==="quiz"||m.type==="transfer"||m.type==="redpacket"?" wfix":"")+(m.tag?" hastag":"")+'" data-act="msg-tap" data-id="'+m.id+'">'+inner+'</div>'+(me?"":(m.mood||m.mood2?'<span class="bubmoods">'+(m.mood?'<span class="bubmood" data-act="mood-tap" data-id="'+m.id+'">'+esc(m.mood)+"</span>":"")+(m.mood2?'<span class="bubmood2">'+esc(m.mood2)+"</span>":"")+"</span>":""))+meta+"</div>"+(msgMulti?'<span class="selbox" data-act="msg-tap" data-id="'+m.id+'"></span>':"")+"</div>"}
/* 全站头像唯一数据源：聊天 / 朋友圈 / 通话 / 媒体会话 / 设置预览一律实时读这两个字段，
   业务数据（朋友圈、消息、信件…）里绝不存头像快照，避免「换了头像别处还是旧的」 */
function avatarSrc(who){return who==="me"?(S.assets.ava_me||""):(S.assets.ava_ta||"")}
/* 可复用头像组件：参数 src / size / shape / name（不传 size 时使用全局 --ava-size/--ava-radius，便于实时预览） */
function avatarHtml(o){o=o||{};const src=o.src;let st="";if(o.size){const s=o.size,r=(o.shape==="circle")?"50%":"10px";st=' style="width:'+s+"px;height:"+s+"px;border-radius:"+r+'"'}return '<span class="ava'+(o.me?" me":"")+'"'+st+">"+(src?'<img src="'+src+'">':esc((o.name||"").slice(0,1)))+"</span>"}
/* ================= LIBRARY L1 ================= */
/* 「灵感拾取」作为分类卡展示（与其它分类一致）；点击进入「TA的拾取」页统一管理 */
PAGES.lib={html(){
 const lb=c=>CATTYPE(c)==="img"?"图片":CATTYPE(c)==="voice"?"语音":"文本";
 return '<div class="phead"><div class="t" style="margin-left:4px">字卡库</div><button class="ibtn" data-act="lib-more" title="数据管理">'+ico("dotsLine")+'</button></div>'+
 '<div class="libstat"><span class="muted">共 '+S.cards.length+' 条字卡 · '+CATS.length+' 个分类</span></div>'+
 '<div class="libgrid">'+CATS.map(c=>{const pk=c===PICKUP_CAT;const n=pk?pkState().items.length:cardsOf(c).length;return '<button class="libtile" data-act="'+(pk?"pickup-open":"lib-open")+'" data-cat="'+c+'"><span class="ltico">'+catIco(c)+'</span><b>'+c+'</b><span class="ltmeta">'+n+' 条 · '+lb(c)+'</span></button>'}).join("")+'</div>';
},
 init(){}};
/* ================= LIBRARY · 数据管理（L1 下级独立页面）================= */
PAGES.libmanage={html(){
 return phead("数据管理")+
 '<div class="sect" style="margin-top:6px">字卡总览</div><div class="card" style="padding:0 12px">'+
  CATS.map(c=>'<div class="row"><span class="lab" style="display:flex;align-items:center;gap:8px"><span style="color:var(--icon,var(--primary));width:18px;display:inline-flex">'+catIco(c)+'</span>'+c+'</span><span class="val">'+cardsOf(c).length+' 条</span></div>').join("")+
  '<div class="row"><span class="lab"><b>合计</b></span><span class="val"><b>'+S.cards.length+'</b> 条</span></div>'+
 '</div>'+
 '<div class="sect">导出 / 导入</div><div class="card" style="padding:0 12px">'+
  actionRow("down","导出全部字卡",'data-act="lib-export-all"')+
  actionRow("up","导入字卡数据",'data-act="lib-import-all"')+
 '</div>'+
 '<div class="sect">危险操作</div><div class="card" style="padding:0 12px">'+
  actionRow("trash","清除全部字卡库数据",'data-act="lib-clear"',true)+
  '<div class="muted" style="padding:6px 0 12px">将删除全部字卡，不可恢复</div>'+
 '</div>';
},
 init(){}};
/* ================= LIBRARY L2 ================= */
/* 分类页功能行：置于搜索框下方 */
function libTools(cat){return '<div class="toolbar libtools">'+
 '<button class="chip" data-act="lib-group-mgr">分组管理</button>'+
 '<button class="chip" data-act="lib-bulk">批量导入</button>'+
 '<button class="chip" data-act="lib-multi">多选管理</button>'+
 '<button class="chip" data-act="lib-dedup">去除重复</button>'+
 (CATTYPE(cat)!=="img"?'<button class="chip" data-act="lib-block-menu">屏蔽功能</button>':"")+
 '<button class="chip" data-act="lib-export-cat">导出数据</button>'+
 '<button class="chip" data-act="lib-import-cat">导入数据</button>'+
 '<button class="chip danger" data-act="lib-cat-clear">清除'+esc(cat)+'</button>'+
 '</div>'}
PAGES.libcat={html(cat){S.misc.gf=S.misc.gf||{};S.misc.q=S.misc.q||{};const gf=S.misc.gf[cat]||"";const groups=S.misc.groups[cat]||[];const multi=(S.misc.multi||{})[cat];
 return phead(cat)+
 '<div class="searchbox"><input placeholder="搜索…" data-search="'+cat+'" value="'+esc(S.misc.q[cat]||"")+'"></div>'+
 libTools(cat)+
 '<div class="chiprow"><button class="chip'+(gf===""?" on":"")+'" data-act="lib-gf" data-cat="'+cat+'" data-g="">全部</button>'+groups.map(g=>'<button class="chip'+(gf===g?" on":"")+'" data-act="lib-gf" data-cat="'+cat+'" data-g="'+esc(g)+'">'+esc(g)+'</button>').join("")+'</div>'+
 '<div id="liblist">'+libListHtml(cat)+'</div>'+
 (multi?'<div style="height:74px"></div><div class="multibar2"><button class="btn sm" data-act="lib-selall">全选</button><button class="btn sm" data-act="lib-multimove">'+ico("move")+' 移动</button><button class="btn sm danger" data-act="lib-multidel">'+ico("trash")+' 删除</button><button class="btn sm" data-act="lib-multi">取消</button></div>':'');
},
 init(){}};
function libGridHtml(cat,items,multi,sel){
 return items.length?('<div class="stkgrid">'+items.map(function(c){
  const blk=isBlocked(c)?" blocked":"";
  if(multi)return '<button type="button" class="cell'+blk+(sel.includes(c.id)?" on":"")+'" data-act="lib-seltile" data-id="'+c.id+'"><img src="'+mediaUrl(c.data,"c"+c.id)+'">'+(sel.includes(c.id)?'<span class="cellck">'+ico("check")+"</span>":"")+"</button>";
  return '<div class="cell'+blk+'"><img src="'+mediaUrl(c.data,"c"+c.id)+'" data-act="lib-edit" data-id="'+c.id+'">'+

   '<button type="button" class="del" data-act="lib-del" data-id="'+c.id+'" title="删除">'+ico("close")+"</button></div>"}).join("")+"</div>"):'<div class="empty">'+(((S.misc.q||{})[cat])?"没有匹配的内容":"这个分类还没有内容")+"</div>"}
function libListHtml(cat){const q=(S.misc.q||{})[cat]||"";const gf=(S.misc.gf||{})[cat]||"";const multi=(S.misc.multi||{})[cat];const sel=(S.misc.sel||{})[cat]||[];
 const items=cardsOf(cat).filter(c=>(gf===""||c.group===gf)&&(!q||(c.type==="text"?c.content.includes(q):(c.name||"").includes(q))));
 /* 字卡一多，一次性畫几千条 DOM 就会「点进去要等一会」：只画前 LIB_STEP 条，往下滑自动续。 */
 const key=cat+"|"+gf+"|"+q;
 if(_libWinKey!==key){_libWinKey=key;libShowLimit=LIB_STEP}
 const total=items.length;
 const shown=(total>libShowLimit)?items.slice(0,libShowLimit):items;
 const more=(total>libShowLimit)?'<div class="moremsg" data-act="lib-win">↓ 还有 '+(total-libShowLimit)+' 条 · 点这里继续</div>':"";
 if(CATTYPE(cat)==="img")return libGridHtml(cat,shown,multi,sel)+more;
 return (shown.length?shown.map(c=>'<div class="listitem'+(isBlocked(c)?" blocked":"")+'">'+(multi?'<input type="checkbox" class="ck" data-act="lib-sel" data-id="'+c.id+'" '+(sel.includes(c.id)?"checked":"")+">":"")+
 (c.type==="img"?'<img class="th" src="'+mediaUrl(c.data,"c"+c.id)+'">':c.type==="voice"?'<button class="playbtn" data-act="lib-play" data-id="'+c.id+'">'+ico("play")+"</button>":"")+
 '<div class="main" data-act="lib-edit" data-id="'+c.id+'"><div class="t1">'+(c.type==="text"?esc(c.content):c.type==="img"?"[图片]":"[语音] "+esc(c.name||""))+"</div></div>"+
 (multi?"":'<button class="ibtn" data-act="lib-block" data-id="'+c.id+'" title="屏蔽">'+ico("block")+'</button><button class="ibtn" data-act="lib-del" data-id="'+c.id+'">'+ico("trash")+"</button>")+"</div>").join(""):'<div class="empty">'+(q?"没有匹配的内容":"这个分类还没有内容")+'</div>')+more}
function libRefresh(cat){const box=$("#liblist");if(box){box.innerHTML=libListHtml(cat);return}if(cur==="libcatmanage"||cur==="libmanage")render()}
/* ================= LIBRARY · 分类管理（L2 下级独立页面）================= */
/* 大列表分屏：先进页面只渲染 LIB_STEP 条（秒进），滑到底或点按钮再续下一批 */
const LIB_STEP=80;let libShowLimit=LIB_STEP,_libWinKey=null;
ACT["lib-win"]=()=>{libShowLimit+=LIB_STEP;if(cur==="pickup"){try{render()}catch(e){}}else{try{libRefresh(curParam)}catch(e){};try{libLoadMedia(curParam)}catch(e){}}};
/* 聊天页「回到底部」悬浮按钮：往上翻过一屏才出现，点了平滑回到底并隐藏 */
function updateChatBottom(){try{
 let b=document.getElementById("chatbottom");
 if(cur!=="chat"){if(b)b.remove();return}
 const sc=document.getElementById("chatscroll");if(!sc){if(b)b.remove();return}
 if(!b){b=document.createElement("button");b.id="chatbottom";b.className="chatbottom";b.type="button";
  b.innerHTML=ico("chevdown");b.title="回到最新消息";
  b.addEventListener("click",function(){try{sc.scrollTo({top:sc.scrollHeight,behavior:"smooth"})}catch(e){sc.scrollTop=sc.scrollHeight}updateChatBottom()});
  document.body.appendChild(b)}
 const d=sc.scrollHeight-sc.scrollTop-sc.clientHeight;
 b.style.display=d>240?"flex":"none";
}catch(e){}}
/* 字卡池的「一键回顶部」悬浮按钮（只在字卡分类 / 拾取页出现，滚动超过一屏才显示） */
function updateLibTop(){try{
 let b=document.getElementById("libtop");
 const show=(cur==="libcat"||cur==="pickup"||cur==="divinecards");
 if(!show){if(b)b.remove();return}
 if(!b){b=document.createElement("button");b.id="libtop";b.className="libtop";b.type="button";
  b.innerHTML=ico("chevup");b.title="回到顶部";
  b.addEventListener("click",function(){const a=document.getElementById("app");if(a){try{a.scrollTo({top:0,behavior:"smooth"})}catch(e){a.scrollTop=0}}});
  document.body.appendChild(b)}
 const a=document.getElementById("app");
 b.style.display=(a&&a.scrollTop>160)?"flex":"none";
}catch(e){}}
function bindLibMoreScroll(){try{const app=$("#app");if(!app||app.dataset.libBound)return;app.dataset.libBound="1";
 app.addEventListener("scroll",function(){try{
    try{updateLibTop()}catch(e){}
    if(cur!=="libcat"&&cur!=="pickup")return;
    const box=$("#app");if(!box||!box.querySelector('[data-act="lib-win"]'))return;
    if(app.scrollTop+app.clientHeight<app.scrollHeight-320)return;
    libShowLimit+=LIB_STEP;
    if(cur==="pickup"){render()}else{libRefresh(curParam);try{libLoadMedia(curParam)}catch(e){}}
  libShowLimit+=LIB_STEP;libRefresh(curParam);try{libLoadMedia(curParam)}catch(e){}}catch(e){}},{passive:true})}catch(e){}}
PAGES.libcatmanage={html(cat){
 const n=cardsOf(cat).length;const t=CATTYPE(cat)==="img"?"图片":CATTYPE(cat)==="voice"?"语音":"文本";
 return phead("管理 · "+cat)+
 '<div class="libstat"><span class="muted">'+esc(cat)+' · '+t+' · 共 '+n+' 条</span></div>'+
 '<div class="sect" style="margin-top:6px">新增内容</div><div class="card" style="padding:0 12px">'+
  actionRow("plus","新增字卡",'data-act="lib-add"')+
  actionRow("up","批量导入",'data-act="lib-bulk"')+
  actionRow("up","从文件导入",'data-act="lib-import-cat"')+
 '</div>'+
 '<div class="sect">整理与导出</div><div class="card" style="padding:0 12px">'+
  actionRow("set","分组管理",'data-act="lib-group-mgr"')+
  actionRow("multi","多选管理",'data-act="lib-multi"')+
  actionRow("copy","去除重复",'data-act="lib-dedup"')+
  actionRow("down","导出本分类",'data-act="lib-export-cat"')+
 '</div>'+
 '<div class="sect">危险操作</div><div class="card" style="padding:0 12px">'+
  actionRow("trash","清空本分类",'data-act="lib-cat-clear"',true)+
  '<div class="muted" style="padding:6px 0 12px">将删除「'+esc(cat)+'」下全部 '+n+' 条内容，不可恢复</div>'+
 '</div>';
},
 init(){}};
/* ================= LIBRARY L3 ================= */
PAGES.libedit={html(p){const cat=p.cat;const c=p.id==="new"?{id:"new",cat,type:CATTYPE(cat),content:"",group:(S.misc.gf||{})[cat]||"",name:""}:S.cards.find(x=>x.id===p.id);if(!c)return phead("不存在");
 const groups=S.misc.groups[cat]||[];
 let body="";
 if(c.type==="text")body='<textarea id="ec" style="min-height:120px" placeholder="内容">'+esc(c.content)+"</textarea>";
 else if(c.type==="img")body=(c.data?'<img src="'+c.data+'" style="max-height:180px;border-radius:10px;margin-bottom:8px">':'<div class="muted">暂无图片</div>')+'<div class="btnrow"><button class="btn sm" data-act="libedit-replace">'+ico("img")+' 更换图片</button></div>';
 else body='<div class="btnrow" style="margin-bottom:8px"><button class="btn sm" data-act="lib-play" data-id="'+c.id+'">'+ico("play")+' 试听</button><button class="btn sm" data-act="libedit-replace">'+ico("mic")+' 更换语音</button>'+(c.data?'<button class="btn sm" data-act="libedit-export" data-id="'+c.id+'">'+ico("down")+' 导出 mp3</button>':"")+'</div>';
 return phead(c.id==="new"?"新增 · "+cat:"编辑 · "+cat)+
 '<div class="card">'+body+'<div class="row" style="margin-top:10px"><span class="lab">分组</span><select id="eg" style="flex:none;width:140px"><option value="">未分组</option>'+groups.map(g=>'<option '+(c.group===g?"selected":"")+' value="'+esc(g)+'">'+esc(g)+"</option>").join("")+"</select></div></div>"+
 '<div class="btnrow"><button class="btn pri" data-act="libedit-save" data-id="'+c.id+'" data-cat="'+cat+'">保存</button>'+(c.id!=="new"?'<button class="btn danger" data-act="lib-del" data-id="'+c.id+'">删除</button>':"")+"</div>"},
 init(){}};
PAGES.libgroups={html(cat){const groups=S.misc.groups[cat]||[];
 return phead("分组管理",'<button class="ibtn" data-act="lib-groups-new" data-cat="'+cat+'" title="新增分组">'+ico("plus")+'</button>')+
 '<div class="muted" style="margin:2px 2px 8px">'+esc(cat)+' · 共 '+groups.length+' 个分组</div>'+
 '<div class="card" style="padding:0 12px">'+(groups.length?groups.map(g=>'<div class="row" style="padding:12px 2px"><span class="lab">'+esc(g)+'<span class="sub"> '+cardsOf(cat).filter(c=>c.group===g).length+' 条</span></span><button class="btn sm" data-act="lib-group-rename" data-cat="'+cat+'" data-g="'+esc(g)+'">改名</button><button class="ibtn" data-act="lib-group-del" data-cat="'+cat+'" data-g="'+esc(g)+'">'+ico("trash")+'</button></div>').join(""):'<div class="empty">暂无分组，点右上「+」新增</div>')+'</div>'},
 init(){}};
/* ================= TA的拾取（拾取内容详情）================= */
function pkItemHtml(it){const who=it.from==="me"?((S.settings&&S.settings.myName)||"我"):((S.settings&&S.settings.taName)||"TA");const on=pkState().on;
  return '<div class="row pkitem"><span class="lab"><span class="pktxt">'+esc(it.text)+'</span><br><span class="sub">'+esc(who)+' 拾取 · '+ago(it.ts)+(on?"":' · <span class="danger-t">未入库</span>')+'</span></span><span class="btnrow"><button class="ibtn" data-act="pk-say" data-id="'+it.id+'" title="发到聊天">'+ico("send")+'</button><button class="ibtn" data-act="pk-voice" data-id="'+it.id+'" title="合成语音发送">'+ico("mic")+'</button><button class="ibtn" data-act="pickup-del" data-id="'+it.id+'" title="删除">'+ico("trash")+'</button></span></div>'}
/* 触发概率：步进器（− 数值 +），写入 S.pickup.prob */
/* 把某条拾取内容发到聊天：发文字，或用 MiniMax 合成语音再发（合成失败自动退回文字） */
function pkFind(id){try{return pkState().items.find(function(x){return x.id===id})||null}catch(e){return null}}
function pkSendText(id){const it=pkFind(id);if(!it)return;pushChat({from:"ta",type:"text",text:it.text});playBlock("ta");toast("已发送到聊天")}
async function pkSendVoice(id){const it=pkFind(id);if(!it)return;const t=String(it.text||"").trim();if(!t)return;
 try{toast("正在合成语音…");const blob=await minimaxTTS(t);pushChat({from:"ta",type:"voice",data:blob,dur:voiceDur(blob)});playBlock("ta")}
 catch(e){pushChat({from:"ta",type:"text",text:t});playBlock("ta");toast("语音合成失败，已用文字发出")}}
ACT["pk-say"]=el=>pkSendText(el.dataset.id);
ACT["pk-voice"]=el=>pkSendVoice(el.dataset.id);
function pkStepRow(label){const p=pkState();const a='data-act="pkstep" data-step="1" data-min="0" data-max="100"';
 return '<div class="row"><span class="lab">'+(label||"触发概率")+' <span class="sub">%</span></span><span class="stepper"><button class="stbtn" '+a+' data-dir="down">−</button><input class="stepnum" type="number" data-pknum value="'+p.prob+'" min="0" max="100"><button class="stbtn" '+a+' data-dir="up">＋</button></span></div>'}
PAGES.pickup={html(){
 const p=pkState();const items=p.items.slice().sort((a,b)=>(b.ts||0)-(a.ts||0));const tn=(S.settings&&S.settings.taName)||"TA";
 /* 拾取条数多了也不一次性全画（和字卡池一样分屏）：先画前 LIB_STEP 条，往下滑自动续 */
 _libWinKey="pickup";
 const shown=(items.length>libShowLimit)?items.slice(0,libShowLimit):items;
 const more=(items.length>libShowLimit)?'<div class="moremsg" data-act="lib-win">↓ 还有 '+(items.length-libShowLimit)+' 条 · 点这里继续</div>':"";
 const head=phead("TA的拾取",items.length?'<button class="ibtn" data-act="pickup-clear" title="清空拾取">'+ico("trash")+'</button>':"");
 const cfg='<div class="card pkmod">'+
  '<div class="row" style="border:none;padding-top:4px">'+
      '<span class="lab"><b>灵感拾取</b> <span class="stpill'+(p.on?" on":"")+'">'+(p.on?"拾取中":"已关闭")+'</span><br><span class="sub">开启后，'+esc(tn)+'会从<b>你发的消息</b>里随机拾取（它自己的消息不拾取），归入 TA 的卡池；回复时它会像挑字卡一样随机用这些内容回你，也可以点每条右侧的按钮让它直接发文字或用 MiniMax 语音说出这条内容</span></span>'+
   '<label class="sw"><input type="checkbox" data-pk="on" '+(p.on?"checked":"")+'><i></i></label>'+
  '</div>'+
 '</div>';
 const stat='<div class="libstat"><span class="muted">共 '+items.length+' 条 · '+(p.on?"拾取中":"已停止")+'</span><span class="muted">触发 '+p.prob+'% · 卡池 '+cardsOf(PICKUP_CAT).length+' 条</span></div>';
  if(!items.length)return head+cfg+stat+'<div class="empty">还没有拾取内容<div class="muted" style="margin-top:8px;line-height:1.7">开启后，TA 会从你发的消息里随机拾取，按来源显示在这里</div></div>';
 const order=[],map={};
 shown.forEach(it=>{const k=it.name||tn;if(!map[k]){map[k]=[];order.push(k)}map[k].push(it)});
 return head+cfg+stat+order.map(name=>'<div class="sect">'+esc(name)+' · '+map[name].length+' 条</div><div class="card" style="padding:0 12px">'+map[name].map(pkItemHtml).join("")+'</div>').join("")+more;
},
 init(){}};
/* ================= SETTINGS L1 ================= */
PAGES.set={html(){return '<div class="phead"><div class="t" style="margin-left:4px">设置</div></div>'+
 [["setapp","外观"," moon"],["setreply","回复","cmt"],["setsys","系统","set"],["setai","AI","ai"],["setstore","存储","down"]].map(r=>'<div class="card" style="padding:0"><div class="row" style="padding:14px 12px;cursor:pointer" data-act="set-open" data-page="'+r[0]+'"><span class="lab" style="display:flex;align-items:center;gap:10px"><span style="color:var(--icon,var(--primary));width:20px">'+ico(r[2].trim())+"</span>"+r[1]+'</span></div></div>').join("")},
 init(){}};
/* ---- L2 外观 ---- */
const THEMES=[["ink","素墨"],["bw","黑白","#000000","#ffffff"],["star","紫黛","#DCCDF2","#E7DDEA"],["sakura","樱粉"],["mint","薄荷"],["orange","暖橙"],["sky","天空","#6FA8DC","#F2F7FC"]];
PAGES.setapp={html(){const s=S.settings;
 return phead("外观")+
 '<div class="sect">内置预设主题</div><div class="card"><div class="chips">'+THEMES.map(t=>'<button class="chip'+(s.theme===t[0]?" on":"")+'" data-act="theme-pick" data-t="'+t[0]+'">'+t[1]+"</button>").join("")+"</div>"+
 '<div class="row" style="margin-top:10px"><span class="lab">自定义主色</span><input type="color" data-custom="primary" value="'+(s.custom.primary||"#DCCDF2")+'"></div>'+
 '<div class="row"><span class="lab">自定义背景色</span><input type="color" data-custom="bg" value="'+(s.custom.bg||"#E7DDEA")+'"></div>'+
 '<div class="row"><span class="lab">颜色跟随主题</span><button class="btn sm" data-act="custom-follow">恢复跟随</button></div>'+
 '<div class="row"><span class="lab">深色模式</span><label class="sw"><input type="checkbox" data-set="dark" '+(s.dark?"checked":"")+"><i></i></label></div></div>"+
 '<div class="sect">底栏导航</div><div class="card">'+setRowRange("底栏胶囊透明度","navOp","%",0,100)+'<div class="muted" style="padding:2px 0 6px">调低后底栏胶囊变透，露出的是桌面壁纸，不会透出下面滚动的内容与图标。</div></div>'+
 '<div class="sect">花卉图标（主页 / 底栏）</div><div class="card"><div class="chips">'+APPS.map(a=>'<button class="chip'+((s.flowerApps&&s.flowerApps[a[0]])?" on":"")+'" data-act="flower-app" data-id="'+a[0]+'">'+a[1]+"</button>").join("")+[["nav_home","底栏·首页"],["nav_lib","底栏·字卡库"],["nav_set","底栏·设置"]].map(a=>'<button class="chip'+((s.flowerApps&&s.flowerApps[a[0]])?" on":"")+'" data-act="flower-app" data-id="'+a[0]+'">'+a[1]+"</button>").join("")+'</div><div class="muted" style="margin-top:8px">点亮某个图标，其主页 / 底栏图标即换成花卉图标（颜色随主题与自定义主色变化）</div></div>'+
 '<div class="sect">手机桌面背景图</div><div class="card">'+(S.assets.bg_home?'<img src="'+S.assets.bg_home+'" style="max-height:120px;border-radius:10px;margin-bottom:8px">':'<div class="muted" style="margin-bottom:8px">未设置背景图</div>')+'<div class="btnrow"><button class="btn sm" data-act="asset-up" data-k="bg_home">'+ico("up")+' 上传</button><button class="btn sm danger" data-act="asset-clr" data-k="bg_home" '+(S.assets.bg_home?"":"disabled")+">清除</button></div></div>"+
 '<div class="sect">桌面图标与底栏图标</div><div class="card">'+APPS.map(a=>iconRow("icon_"+a[0],a[1])).join("")+iconRow("nav_home","底栏·首页")+iconRow("nav_lib","底栏·字卡库")+iconRow("nav_set","底栏·设置")+"</div>"},
 init(){}};
function iconRow(k,label){const v=S.assets[k];const isFlower=S.settings.flowerApps&&S.settings.flowerApps[k];const inner=v?'<img src="'+v+'" style="width:100%;height:100%;object-fit:cover">':(isFlower?flowerIcon(k):(k.startsWith("nav_")?ico(k.slice(4)):appIcon((APPS.find(a=>"icon_"+a[0]===k)||["chat"])[0])));return '<div class="row"><span class="lab" style="display:flex;align-items:center;gap:8px"><span class="iconprev" style="width:30px;height:30px;border-radius:8px;background:var(--bg);display:flex;align-items:center;justify-content:center;overflow:hidden;color:var(--icon,var(--primary))">'+inner+"</span>"+label+'</span><span class="btnrow"><button class="btn sm" data-act="asset-up" data-k="'+k+'">上传</button><button class="btn sm danger" data-act="asset-clr" data-k="'+k+'" '+(v?"":"disabled")+">清除</button></span></div>"}
/* ---- L2 回复 ---- */
function setRowRange(label,path,unit,min,max){const v=getPath(S.settings,path);unit=unit==null?"%":unit;min=min==null?0:min;max=max==null?100:max;
 /* 概率类一律改用步进器（− 数字 +），非概率（透明度/字号/头像大小等）仍用滑块 */
 const isProb=(unit==="%"&&(/概率/.test(label)||/Prob$/.test(path)||path==="reply.chat.noreply"));
 if(isProb)return setRowStep(label,path,unit,min,max,1);
 return '<div class="row sliderrow"><span class="lab">'+label+'</span><div class="ctl"><input type="range" data-set="'+path+'" min="'+min+'" max="'+max+'" value="'+v+'"><span class="val" data-labfor="'+path+'" data-unit="'+unit+'">'+v+unit+"</span></div></div>"}
/* 列表式操作行（左图标 / 中文字 / 右箭头，纵向堆叠） */
function actionRow(iconName,label,attrs,danger,plain){return '<button class="row listbtn'+(danger?" danger":"")+'" '+attrs+'><span class="li">'+ico(iconName)+'</span><span class="lt">'+label+"</span>"+(plain?"":'<span class="lv">›</span>')+"</button>"}
function setRowNum(label,path,unit){const v=getPath(S.settings,path);return '<div class="row"><span class="lab">'+label+(unit?' <span class="sub">'+unit+"</span>":"")+'</span><input type="number" data-set="'+path+'" value="'+v+'" style="width:84px;flex:none"></div>'}
function setRowStep(label,path,unit,min,max,step){const v=getPath(S.settings,path);min=min==null?0:min;max=max==null?9999:max;step=step||1;
 const isProb=(unit==="%"&&/概率/.test(label));
 const a='data-act="step" data-path="'+path+'" data-step="'+step+'" data-min="'+min+'" data-max="'+max+'"';
 return '<div class="row"><span class="lab">'+label+(unit?' <span class="sub">'+unit+"</span>":"")+(isProb?' <span class="probnote" data-probnote="'+path+'" style="'+((+v===0)?"":"display:none")+'">不触发</span>':"")+'</span><span class="stepper"><button class="stbtn" '+a+' data-dir="down">−</button><input class="stepnum" type="number" data-set="'+path+'" value="'+v+'" min="'+min+'" max="'+max+'"><button class="stbtn" '+a+' data-dir="up">＋</button></span></div>'}
function sndBlock(key,title,opts){const s=S.settings.sound,st=s[key];return '<div class="card'+(s.on?"":" sfxoff")+'"><div class="row" style="border:none;padding-top:2px"><span class="lab"><b>'+title+'</b></span></div>'+
 '<div class="chips" style="margin-top:4px">'+opts.map(o=>'<button class="chip'+(st.sel===o?" on":"")+'" data-snd="'+key+'" data-name="'+o+'">'+o+"</button>").join("")+(st.custom?'<button class="chip'+(st.sel==="自定义"?" on":"")+'" data-snd="'+key+'" data-name="自定义">自定义</button>':"")+"</div>"+
 '<div class="btnrow" style="margin-top:10px"><button class="btn sm" data-sndup="'+key+'">'+ico("up")+' 上传自定义音频</button><button class="btn sm danger" data-sndclr="'+key+'" style="'+(st.custom?"":"display:none")+'">清除自定义音频</button></div></div>'}
PAGES.setreply={html(){S.misc.replyMod=S.misc.replyMod||"chat";const mods=[["chat","聊天"],["letter","信箱"],["moments","朋友圈"],["call","通话"],["sound","音效"]];
 return phead("回复")+
 '<div class="chips" style="margin-bottom:10px">'+mods.map(m=>'<button class="chip'+(S.misc.replyMod===m[0]?" on":"")+'" data-act="reply-mod" data-m="'+m[0]+'">'+m[1]+"</button>").join("")+"</div>"+
 ({chat:modChat,letter:modLetter,moments:modMoments,call:modCall,sound:modSound})[S.misc.replyMod]()},
 init(){}};
/* 可收起的设置分组：标题行点一下向下展开 / 收起（状态记在 S.misc.replyFold） */
function foldCard(key,title,body){const open=!!(S.misc.replyFold&&S.misc.replyFold[key]);
 return '<div class="card foldcard">'+
  '<button class="row foldrow'+(open?" on":"")+'" data-act="reply-fold" data-k="'+key+'" style="width:100%;background:none;padding:14px 2px;text-align:left">'+
   '<span class="lab"><b>'+title+'</b></span><span class="lv">'+ico("chevdown")+'</span></button>'+
  '<div class="foldbody" data-fold="'+key+'" style="'+(open?"":"display:none")+'">'+body+'</div></div>'}
ACT["reply-fold"]=el=>{const k=el.dataset.k;const body=el.parentNode.querySelector('[data-fold="'+k+'"]');if(!body)return;
 const open=body.style.display!=="none";body.style.display=open?"none":"";el.classList.toggle("on",!open);
 S.misc.replyFold=S.misc.replyFold||{};S.misc.replyFold[k]=!open;save("misc")}
function modActive(){const r=S.settings.reply.chat;const picked=r.tagPicked||[];const tags=r.tags||[];
 const sendBody=
  '<div class="row"><span class="lab">主动发送</span><label class="sw"><input type="checkbox" data-set="reply.chat.activeOn" '+(r.activeOn?"checked":"")+'><i></i></label></div>'+
  '<div class="muted" style="padding:2px 0 8px">关闭后忽略下方全部配置，TA 不会主动发起会话；该功能独立于自动回复。</div>'+
  setRowStep("主动发送概率","reply.chat.active","%",0,100,1)+
  setRowStep("发送间隔最短","reply.chat.activeMin","分钟",1,1440,1)+setRowStep("发送间隔最长","reply.chat.activeMax","分钟",1,1440,1)+
  setRowStep("发送条数最少","reply.chat.activeCountMin","条",1,20,1)+setRowStep("发送条数最多","reply.chat.activeCountMax","条",1,20,1)+
  '<div class="muted" style="padding:8px 0 0">到达间隔后按概率决定是否发出；概率为 0 时不主动发送（等于关闭本功能）。连发条数只由本节控制，不计入自动回复的字卡条数。</div>';
 const tagBody=
  '<div class="row"><span class="lab">显示标识</span><label class="sw"><input type="checkbox" data-set="reply.chat.tagOn" '+(r.tagOn?"checked":"")+'><i></i></label></div>'+
  '<div class="muted" style="padding:2px 0 8px">开启后，主动消息气泡左上角显示标识；关闭则不显示任何标识。</div>'+
  '<div class="chips">'+ACTIVE_TAGS.map(t=>'<button class="chip tagchip'+(picked.indexOf(t)>=0?" on":"")+'" data-act="active-tag" data-t="'+t+'">'+ico(t)+'</button>').join("")+
   tags.map(t=>'<span class="tagwrap"><button class="chip'+(picked.indexOf(t)>=0?" on":"")+'" data-act="active-tag" data-t="'+esc(t)+'">'+esc(t)+'</button><button class="tagx" data-act="active-tag-del" data-t="'+esc(t)+'">×</button></span>').join("")+
   '<button class="chip" data-act="active-tag-add">＋ 自定义</button></div>'+
  '<div class="muted" style="padding:8px 0 0">点标识本体选中/取消（可多选）；自定义标识点 × 删除，最多 8 个、单个最长 4 个字符。当前自定义 '+tags.length+'/8。</div>'+
  '<div class="row" style="margin-top:8px"><span class="lab">抽取方式</span><span class="chips">'+[["random","随机"],["cycle","轮换"]].map(m=>'<button class="chip'+(r.tagMode===m[0]?" on":"")+'" data-act="active-tag-mode" data-v="'+m[0]+'">'+m[1]+"</button>").join("")+'</span></div>'+
  '<div class="muted" style="padding:2px 0 0">只点亮 1 枚时固定使用该枚；点亮多枚时按此方式取用：「随机」每条消息随机抽一枚，「轮换」按点亮顺序依次使用。关闭「显示标识」则以上均不生效。</div>';
 return foldCard("active","主动发送（对方找你）",sendBody)+foldCard("tags","主动发送标识",tagBody)}
function modChat(){const r=S.settings.reply.chat;const body=
 setRowNum("对方回复最短时间","reply.chat.speedMin","秒")+setRowNum("对方回复最长时间","reply.chat.speedMax","秒")+
 '<div class="sect" style="margin:12px 0 2px">拼字卡模式（随机组合多张）</div>'+
 setRowStep("触发概率","reply.chat.pinProb","%",0,100,5)+
 setRowNum("最少字卡数","reply.chat.pinMin","张")+setRowNum("最多字卡数","reply.chat.pinMax","张")+
 '<div class="muted" style="padding:2px 0 8px">触发时从「主字卡」随机抽取若干张，用「，」拼成一句话；概率为 0 时只发单张字卡，不触发拼接。</div>'+
'<div class="row"><span class="lab">情绪字卡分组 <span class="sub">整组启用 / 停用</span></span><button class="btn sm" data-act="mood-groups">管理</button></div>'+'<div class="muted" style="padding:2px 0 8px">情绪字卡与心意字卡各自独立判定：可以只出情绪、只出心意、两张一起出，或者都不出。</div>'+setRowStep("已读不回概率","reply.chat.noreply","%",0,100,5)+setRowStep("情绪字卡概率","reply.chat.mood","%",0,100,5)+setRowStep("心意字卡概率","reply.chat.heart","%",0,100,5)+setRowStep("拍一拍概率","reply.chat.pat","%",0,100,5)+setRowStep("表情包概率","reply.chat.sticker","%",0,100,5)+setRowStep("Emoji 概率","reply.chat.emoji","%",0,100,5)+setRowStep("语音字卡概率","reply.chat.voice","%",0,100,5)+setRowStep("颜文字概率","reply.chat.kaomoji","%",0,100,5)+setRowStep("引用概率","reply.chat.quote","%",0,100,5)+setRowStep("撤回概率","reply.chat.retract","%",0,100,5)+
 '<div class="muted" style="padding:2px 0 8px">「拍一拍」文案取自字卡库「拍一拍」，支持 {ta} / {me} 占位符，并把「你 / 我」按当前昵称替换；在聊天里双击头像也能拍一拍；发送后对方会回复一条。</div>'+
 '<div class="sect" style="margin:12px 0 2px">灵感拾取（对方从对话中拾取）</div>'+
 pkStepRow()+
 '<div class="muted" style="padding:2px 0 8px">对方每条消息按此概率拾取内容，归入字卡库「灵感拾取」；开启 / 关闭与拾取记录在字卡库「灵感拾取」入口内。</div>'+
 '<div class="sect" style="margin:12px 0 2px">寻踪 · TA 的日常</div>'+
 '<div class="row"><span class="lab">开启寻踪日常</span><label class="sw"><input type="checkbox" data-set="reply.trace.on" '+((S.settings.reply.trace||{}).on?"checked":"")+'><i></i></label></div>'+
 setRowStep("推送到聊天概率","reply.trace.prob","%",0,100,5)+
 '<div class="muted" style="padding:2px 0 8px">更新时向聊天推「更新了一条日常」+ 日常内容；关闭总开关则停止生成与推送。内容在字卡库「寻踪·在哪里 / 寻踪·在做什么 / 寻踪·想对你说」维护。</div>';
 return foldCard("chat","聊天回复",body)+modActive()}
function modLetter(){return '<div class="card"><h3>信箱</h3>'+
 setRowNum("信的内容最少字卡","reply.letter.minCards","条")+setRowNum("信的内容最多字卡","reply.letter.maxCards","条")+
 setRowStep("主动写信概率","reply.letter.activeProb","%",0,100,5)+setRowNum("主动写信条数","reply.letter.activeCount","封")+
 setRowNum("主动写信最短间隔","reply.letter.activeTimeMin","小时")+setRowNum("主动写信最长间隔","reply.letter.activeTimeMax","小时")+
 setRowStep("我回信后对方回信概率","reply.letter.replyProb","%",0,100,5)+setRowNum("回信最短时间","reply.letter.replyTimeMin","分钟")+setRowNum("回信最长时间","reply.letter.replyTimeMax","分钟")+setRowNum("回信条数","reply.letter.replyCount","封")+
 setRowStep("写信用颜文字概率","reply.letter.kaomoji","%",0,100,5)+setRowStep("写信用 Emoji 概率","reply.letter.emoji","%",0,100,5)+setRowStep("写信用表情包概率","reply.letter.sticker","%",0,100,5)+"</div>"}
function modMoments(){return '<div class="card"><h3>朋友圈</h3>'+
 setRowStep("对方主动发朋友圈概率","reply.moments.activeProb","%",0,100,5)+setRowNum("字卡条数","reply.moments.cards","条")+setRowNum("间隔时间","reply.moments.intervalH","小时")+
 setRowStep("对方用颜文字概率","reply.moments.kaomoji","%",0,100,5)+setRowStep("对方用 Emoji 概率","reply.moments.emoji","%",0,100,5)+setRowStep("对方用表情包概率","reply.moments.sticker","%",0,100,5)+setRowStep("对方用语音字卡概率","reply.moments.voice","%",0,100,5)+
 setRowStep("我发布后对方点赞概率","reply.moments.likeProb","%",0,100,5)+setRowStep("我发布后对方回复概率","reply.moments.cmtProb","%",0,100,5)+
 setRowStep("回复用颜文字概率","reply.moments.cmtKaomoji","%",0,100,5)+setRowStep("回复用 Emoji 概率","reply.moments.cmtEmoji","%",0,100,5)+setRowStep("回复用表情包概率","reply.moments.cmtSticker","%",0,100,5)+setRowStep("回复用语音字卡概率","reply.moments.cmtVoice","%",0,100,5)+setRowStep("TA 收藏我的动态概率","fav.feed","%",0,100,5)+setRowStep("我点赞后 TA 回赞概率","reply.moments.likeback","%",0,100,5)+setRowNum("每天最多发布","reply.moments.dailyMax","条")+setRowNum("发布后冷却","reply.moments.cool","分钟")+"</div>"}
function modCall(){return '<div class="card"><h3>通话</h3>'+
 setRowStep("来电概率","reply.call.prob","%",0,100,1)+
 setRowStep("接听概率","reply.call.pickup","%",0,100,1)+
 setRowStep("忙线概率","reply.call.busy","%",0,100,1)+
 setRowStep("拒接概率","reply.call.reject","%",0,100,1)+
 setRowStep("通话中挂断概率","reply.call.hangup","%",0,100,1)+
  '<div class="row"><span class="lab">禁止'+(S.settings.taName||"TA")+' 挂断电话</span><label class="sw"><input type="checkbox" data-set="reply.call.nohangup" '+(S.settings.reply.call.nohangup?"checked":"")+'><i></i></label></div>'+
 '<div class="row"><span class="lab">通话背景图（面板）</span><span class="btnrow"><button class="btn sm" data-act="asset-up" data-k="callbg">上传</button><button class="btn sm danger" data-act="asset-clr" data-k="callbg" '+(S.assets.callbg?"":"disabled")+">清除</button></span></div>"+
 '<div class="row"><span class="lab">通话半框背景图（小框）</span><span class="btnrow"><button class="btn sm" data-act="asset-up" data-k="callmini">上传</button><button class="btn sm danger" data-act="asset-clr" data-k="callmini" '+(S.assets.callmini?"":"disabled")+">清除</button></span></div>"+
 '<div class="muted" style="padding:4px 0 2px">来电概率＝每轮检查触发来电的几率（约每 1–2 分钟检查一次，5 分钟内不重复来电）。</div>'+
 "</div>"}
function modSound(){const s=S.settings.sound;
 return '<div class="card"><div class="row" style="border:none;padding-top:2px"><span class="lab"><b>音效总开关</b><br><span class="sub">关闭后，收到消息与来电都不再自动播放音效</span></span><label class="sw"><input type="checkbox" data-sndmaster '+(s.on?"checked":"")+"><i></i></label></div></div>"+
 sndBlock("ta","TA 发送消息",SND_MSG)+sndBlock("me","我发送消息",SND_MSG)+sndBlock("ring","TA 来电铃声",SND_RING)+
 '<div class="card muted">点选音效会立即试听（不受总开关影响）；总开关只决定收到消息 / 来电时是否自动播放。上传自定义音频后会新增「自定义」选项并自动选中。</div>'}
/* ---- L2 系统 ---- */
PAGES.setsys={html(){const s=S.settings.system;const rows=[["keepalive","后台保活","保持后台运行，减少被系统回收"],["notify","后台通知","TA 来消息时发送系统通知"],["popup","桌面消息弹窗","应用内弹出消息提示"],["offline","离线消息提醒","重新打开时补发离线期间消息"]];
 return phead("系统")+'<div class="card">'+rows.map(r=>'<div class="row"><span class="lab">'+r[1]+'<br><span class="sub">'+r[2]+'</span></span><label class="sw"><input type="checkbox" data-set="system.'+r[0]+'" '+(s[r[0]]?"checked":"")+"><i></i></label></div>").join("")+"</div>"},
 init(){}};
/* ---- L2 AI ---- */
function aiField(label,path,ph){const v=getPath(S.settings,path);return '<div class="row sliderrow"><span class="lab">'+label+'</span><input type="text" data-set="'+path+'" value="'+esc(v==null?"":v)+'" placeholder="'+esc(ph||"")+'" autocomplete="off" autocapitalize="off" spellcheck="false"></div>'}
/* ================= AI 模块：模型管理 / 世界书 / 语音 / 调用记录 ================= */
const AI_PROVIDERS=[
 ["deepseek","DeepSeek","https://api.deepseek.com/v1","deepseek-chat"],
 ["kimi","Kimi","https://api.moonshot.cn/v1","moonshot-v1-8k"],
 ["glm","智谱 GLM","https://open.bigmodel.cn/api/paas/v4","glm-4-flash"],
 ["qwen","通义千问","https://dashscope.aliyuncs.com/compatible-mode/v1","qwen-plus"],
 ["minimax","MiniMax","https://api.minimax.chat/v1","abab6.5s-chat"],
 ["openrouter","OpenRouter","https://openrouter.ai/api/v1","openai/gpt-4o-mini"],
 ["custom","自定义","",""],
];
const aiPreset=k=>AI_PROVIDERS.find(p=>p[0]===k)||AI_PROVIDERS[6];
function aiActive(){S.aiModels=S.aiModels||[];return S.aiModels.find(m=>m.id===S.aiCurrent)||S.aiModels[0]||null}
function aiHeaders(cfg){const h={"Content-Type":"application/json"};if(cfg&&cfg.apiKey)h["Authorization"]="Bearer "+cfg.apiKey;return h}
function safeJson(s){try{return JSON.parse(s)}catch(e){return null}}
function aiErrMsg(status,raw){let m="";try{const o=JSON.parse(raw);m=(o&&o.error&&(o.error.message||o.error))||(o&&(o.message||o.msg))||""}catch(e){m=String(raw||"").slice(0,120)}return "接口错误 "+(status||"")+(m?("："+m):"")}
function aiCtxLen(messages){return (messages||[]).reduce((n,m)=>n+String((m&&m.content)||"").length,0)}
function aiLog(cfg,info){info=info||{};S.aiLogs=S.aiLogs||[];S.aiLogs.unshift({id:uid(),ts:Date.now(),name:(cfg&&cfg.name)||"",provider:(cfg&&cfg.provider)||"",model:(cfg&&cfg.model)||"",ms:info.ms||0,reqBytes:info.reqBytes||0,ctxLen:aiCtxLen(info.messages),ok:!!info.ok,status:info.status||0,err:info.err||"",prompt:info.messages||[],response:info.response||"",raw:info.raw||""});S.aiLogs=S.aiLogs.slice(0,120);save("aiLogs")}
function choiceText(data){return (data&&data.choices&&data.choices[0]&&((data.choices[0].message&&data.choices[0].message.content)||data.choices[0].text))||""}
async function aiRequest(cfg,messages,opt){opt=opt||{};
 if(!cfg||!cfg.baseUrl)throw new Error("请先配置接口地址");
 if(!cfg.model)throw new Error("请先填写模型名");
 const url=cfg.baseUrl.replace(/\/+$/,"")+"/chat/completions";
 const body={model:opt.model||cfg.model,messages,temperature:opt.temperature==null?0.8:opt.temperature,stream:false};
 if(opt.max_tokens)body.max_tokens=opt.max_tokens;
 const bodyStr=JSON.stringify(body);const reqBytes=new TextEncoder().encode(bodyStr).length;const t0=Date.now();
 let res;
 try{res=await fetch(url,{method:"POST",headers:aiHeaders(cfg),body:bodyStr})}
 catch(e){aiLog(cfg,{ok:false,ms:Date.now()-t0,reqBytes,messages,err:"网络请求失败："+(e&&e.message||e)});throw new Error("网络请求失败，请检查接口地址与网络连接")}
 if(!res.ok){let raw="";try{raw=await res.text()}catch(e){}const msg=aiErrMsg(res.status,raw);aiLog(cfg,{ok:false,status:res.status,ms:Date.now()-t0,reqBytes,messages,raw,err:msg});throw new Error(msg)}
 const raw=await res.text();const data=safeJson(raw);const out=choiceText(data)||raw;
 aiLog(cfg,{ok:true,status:res.status,ms:Date.now()-t0,reqBytes,messages,response:out,raw});return out}
async function aiTestCfg(cfg){await aiRequest(Object.assign({},cfg,{stream:false}),[{role:"user",content:"ping"}],{max_tokens:1,stream:false});return true}
async function aiListModels(cfg){if(!cfg||!cfg.baseUrl)throw new Error("请先配置接口地址");const url=cfg.baseUrl.replace(/\/+$/,"")+"/models";
 let res;try{res=await fetch(url,{headers:aiHeaders(cfg)})}catch(e){throw new Error("网络请求失败，请检查接口地址")}
 const raw=await res.text();if(!res.ok)throw new Error(aiErrMsg(res.status,raw));
 const data=safeJson(raw);const ids=((data&&data.data)||[]).map(x=>x&&x.id).filter(Boolean);
 if(!ids.length)throw new Error("接口未返回模型列表");return ids}
/* ---- 世界书 ---- */
function wbChar(){return S.settings.taName||"TA"}
/* 世界书统一存成扁平结构（bg / person / relation 三个分类）。
   旧版本是按「角色名」分层存的（S.worldbook[角色名].bg…）：一旦改名或换角色，
   之前导入的条目就被"藏在别的名字下"，看起来就是刷新后消失。这里做一次性迁移，把
   旧结构里的条目合并到顶层，之后所有读写都只认这一份，和角色名无关。 */
function wbFlatten(){const w=S.worldbook;
 if(!w||typeof w!=="object"||Array.isArray(w)){S.worldbook={bg:[],person:[],relation:[]};return S.worldbook}
 if(Array.isArray(w.bg)||Array.isArray(w.person)||Array.isArray(w.relation))return w;
 const out={bg:[],person:[],relation:[]};let moved=0;
 Object.keys(w).forEach(function(k){const o=w[k];if(!o||typeof o!=="object"||Array.isArray(o))return;
  ["bg","person","relation"].forEach(function(c){if(Array.isArray(o[c])&&o[c].length){out[c]=out[c].concat(o[c]);moved+=o[c].length}})});
 S.worldbook=out;
 if(moved)try{wbSave()}catch(e){}
 return out}
function wbList(){const o=wbFlatten();["bg","person","relation"].forEach(function(c){if(!Array.isArray(o[c]))o[c]=[]});return o}
/* 世界书的改动立刻落盘（不走 250ms 防抖，刷新再快也不会丢） */
function wbSave(){try{save("worldbook")}catch(e){}
 try{saveFlush()}catch(e){}}
const WB_CATS=[["bg","背景设定"],["person","人物设定"],["relation","关系网"]];
function wbActiveText(){const o=wbList();const out=[];WB_CATS.forEach(c=>{const items=o[c[0]].filter(e=>e.on!==false&&String(e.content||"").trim());if(items.length)out.push("【"+c[1]+"】\n"+items.map(e=>(e.title?("# "+e.title+"\n"):"")+e.content).join("\n"))});return out.join("\n\n")}
function buildAISystemPrompt(tab){const ar=S.settings.aiReply,s=S.settings;const parts=[];
 if(ar.tabs&&ar.tabs[tab])parts.push(ar.tabs[tab]);
 const wb=wbActiveText();if(wb)parts.push("【世界书】\n"+wb);
 parts.push("角色名："+(s.taName||"TA")+"；用户："+(s.myName||"我")+"。");
 return parts.join("\n\n")}
/* ---- 语音 ---- */
function voiceById(id){return (S.voiceLib||[]).find(v=>v.id===id)||null}
const MINIMAX_VOICES=[["female-shaonv","女声 · 少女"],["male-qn-qingse","男声 · 青涩"],["female-yujie","女声 · 御姐"],["male-qn-jingying","男声 · 精英"]];
/* 语音供应商预设（与 AI 供应商同样的口径） */
const VOICE_PROVIDERS=[
 ["minimax","MiniMax（T2A）","https://api.minimax.chat/v1","speech-2.8-hd"],
 ["openai","OpenAI 兼容（/audio/speech）","https://api.openai.com/v1","tts-1"],
 ["custom","自定义","",""],
];
const voicePreset=k=>VOICE_PROVIDERS.find(p=>p[0]===k)||VOICE_PROVIDERS[0];
function voiceFor(text){const v=S.settings.voice;S.voiceLib=S.voiceLib||[];
 if(v.voiceId)return {id:"__set",name:"自定义音色",voiceId:v.voiceId};
 let id=v.langMode==="en"?v.enId:v.langMode==="zh"?v.zhId:(/[A-Za-z]{3,}/.test(text||"")?v.enId:v.zhId);id=id||v.zhId||v.enId;
 const got=voiceById(id);if(got&&got.voiceId)return got;const first=S.voiceLib.find(x=>x&&x.voiceId);if(first)return first;
 return {id:"__default",name:"默认女声",voiceId:MINIMAX_VOICES[0][0]}}
function hexToBlob(hex,type){const m=String(hex).replace(/[^0-9a-fA-F]/g,"");const len=m.length>>1;const u8=new Uint8Array(len);for(let i=0;i<len;i++)u8[i]=parseInt(m.substr(i*2,2),16);return new Blob([u8],{type:type||"audio/mpeg"})}
async function minimaxTTS(text,opts){const v=S.settings.voice;if(!v.apiKey)throw new Error("请先填写 API Key");/* 供应商分支：OpenAI 兼容（POST /audio/speech → mp3） */
 if((v.provider||"minimax")==="openai"){const _vv=voiceFor(text);const _vid=(_vv&&_vv.voiceId)||"alloy";const _b=(v.baseUrl||"https://api.openai.com/v1").replace(/\/+$/,"");
  let _r;try{_r=await fetch(_b+"/audio/speech",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+v.apiKey},body:JSON.stringify({model:v.model||"tts-1",input:String(text||""),voice:_vid,response_format:"mp3",speed:+(v.rate||1)})})}catch(e){throw new Error("语音请求失败，请检查网络与接口地址")}
  if(!_r.ok){let _raw="";try{_raw=await _r.text()}catch(e){}throw new Error("接口错误 "+_r.status+(_raw?("："+_raw.slice(0,120)):""))}
  return await _r.blob()}
 const voice=voiceFor(text);if(!voice||!voice.voiceId)throw new Error("请先添加并绑定音色");
 let base=(v.baseUrl||"https://api.minimax.chat/v1").replace(/\/+$/,"");if(!/\/v\d+$/.test(base))base+="/v1";
 const useGroup=false;const qs=useGroup?("?GroupId="+encodeURIComponent(v.groupId)):"";
 const body={model:v.model||"speech-01-turbo",text:String(text||""),stream:false,voice_setting:{voice_id:voice.voiceId,speed:+(v.rate||1),vol:1,pitch:0},audio_setting:{sample_rate:32000,bitrate:128000,format:"mp3"}};
 let res;try{res=await fetch(base+"/t2a_v2"+qs,{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+v.apiKey},body:JSON.stringify(body)})}catch(e){throw new Error("语音请求失败，请检查网络与接口地址")}
 const raw=await res.text();const data=safeJson(raw);const br=data&&data.base_resp;
 if(br&&br.status_code!=null&&+br.status_code!==0){let hint="";if(+br.status_code===1004)hint="（请检查 API Key 是否正确）";if(+br.status_code===1002||/voice/i.test(br.status_msg||""))hint="（请检查音色 ID 是否有效）";if(useGroup&&/group|组/i.test(br.status_msg||""))hint="（Group ID 可能有误，可尝试留空）";throw new Error("MiniMax("+br.status_code+")："+(br.status_msg||"请求失败")+hint)}
 if(!res.ok){const msg=(br&&br.status_msg)||(data&&(data.message||data.msg))||("HTTP "+res.status);throw new Error(msg)}
 const dd=data&&data.data;let audio=dd&&(dd.audio||dd.audio_file||dd.audio_url);
 if(!audio&&Array.isArray(dd))audio=dd.join("");
 if(!audio&&typeof data==="string")audio=data;
 if(!audio)throw new Error("接口未返回音频数据"+(br&&br.status_msg?("（"+br.status_msg+"）"):""));
 if(typeof audio==="string"&&/^https?:/i.test(audio)){const r2=await fetch(audio);return await r2.blob()}
 if(typeof audio!=="string")throw new Error("音频数据格式无法识别");
 return hexToBlob(audio,"audio/mpeg")}
function voiceDur(blob){return Math.max(1,Math.round((blob&&blob.size||0)/16000))}
function storeVoiceCard(blob,name){const card={id:uid(),cat:"语音字卡",type:"voice",data:blob,name:name||("AI语音 "+new Date().toTimeString().slice(0,5)),dur:voiceDur(blob),group:""};S.cards.push(card);save("cards");return card}
async function ttsSpeak(text){try{toast("正在生成语音…");const blob=await minimaxTTS(text);try{new Audio(URL.createObjectURL(blob)).play()}catch(e){}toast("已生成并播放")}catch(e){toast("语音生成失败："+(e&&e.message||e))}}
async function ttsProactive(text){try{const blob=await minimaxTTS(text);pushChat({from:"ta",type:"voice",data:blob,dur:voiceDur(blob)});playBlock("ta")}catch(e){}}
function tryProactiveVoice(){const v=S.settings.voice;if(!v.on||!v.proactive)return;const p=v.freq==="总是"?70:v.freq==="经常"?40:15;if(!chance(p))return;if(!v.apiKey||!(S.voiceLib||[]).length)return;const pool=cardTexts("主字卡").concat(cardTexts(PICKUP_CAT));if(!pool.length)return;setTimeout(()=>ttsProactive(pick(pool)),rnd(1500,4500))}
/* ---- AI 设置入口 ---- */
PAGES.setai={html(){
 return phead("AI")+
 '<div class="sect" style="margin-top:6px">AI 能力</div><div class="card" style="padding:0 12px">'+
  actionRow("ai","AI 模型配置",'data-act="ai-go" data-page="setaimodels"',false,true)+
  actionRow("tune","AI 回复逻辑",'data-act="ai-go" data-page="setaireply"',false,true)+
  actionRow("book","世界书",'data-act="ai-go" data-page="setaibook"',false,true)+
  actionRow("speaker","TA的声音",'data-act="ai-go" data-page="setaivoice"',false,true)+
  actionRow("clock","AI 调用记录",'data-act="ai-go" data-page="setailogs"',false,true)+
 '</div>'+
 '<div class="muted" style="padding:8px 2px">API Key 等敏感信息仅保存在本机（IndexedDB），只会发送到你填写的接口地址。</div>';
},init(){}};
/* ---- AI 模型配置（列表 + 页内表单，无需再点右上角加号） ---- */
PAGES.setaimodels={html(){S.aiModels=S.aiModels||[];
 const cur=S.aiModels.find(m=>m.id===S.aiCurrent)||null;
 const isNew=!!S.misc.aiNew||!cur;
 const d=isNew?{name:"",provider:"deepseek",model:"",baseUrl:"",apiKey:"",stream:false}:cur;
 const prov=aiPreset(d.provider);
 return phead("AI 模型")+
 '<div class="sect" style="margin-top:6px">使用设置</div><div class="card">'+
  '<div class="row"><span class="lab">启用当前配置</span><label class="sw"><input type="checkbox" data-set="aiOn" '+(S.settings.aiOn!==false?"checked":"")+'><i></i></label></div>'+
 "</div>"+
 '<div class="sect">当前配置</div><div class="card" style="padding:0 12px">'+
  '<div class="row" style="padding:12px 2px"><span class="lab">'+esc(isNew?"新模型配置":(d.name||"(未命名)"))+'<br><span class="sub">'+esc(prov[1])+" · "+esc(d.model||"未设置模型")+'</span></span><button class="btn sm" data-act="ai-model-new">新建配置</button></div>'+
  '<button class="row listbtn" style="border-top:1px solid var(--line)" data-act="ai-cfg-open"><span class="lt">'+esc(isNew?"(未保存配置)":(d.name||"(未命名)"))+'<br><span class="sub">'+esc(prov[1])+" · "+esc(d.model||"未设置模型")+'</span></span><span class="lv">切换配置</span></button>'+
  '<div class="row" style="border-top:1px solid var(--line)"><span class="lab">删除当前配置</span><button class="btn sm danger" data-act="ai-model-del" '+(cur&&!isNew?"":"disabled")+">删除</button></div>"+
 "</div>"+
 '<div class="sect">配置表单</div><div class="card">'+
  '<div class="row sliderrow"><span class="lab">AI 供应商</span><select id="ams" data-act="ai-model-provider">'+AI_PROVIDERS.map(pr=>'<option value="'+pr[0]+'"'+(d.provider===pr[0]?" selected":"")+">"+pr[1]+"</option>").join("")+"</select></div>"+
  '<div class="row sliderrow"><span class="lab">配置名称</span><input id="amn" value="'+esc(d.name||"")+'" placeholder="例如：DeepSeek 主力"></div>'+
  '<div class="row sliderrow"><span class="lab">模型</span><input id="amm" value="'+esc(d.model||"")+'" placeholder="gpt-4o-mini"></div>'+
  '<div class="row sliderrow"><span class="lab">接口地址</span><input id="amb" value="'+esc(d.baseUrl||"")+'" placeholder="https://…"></div>'+
  '<div class="row sliderrow"><span class="lab">API Key（仅保存在本设备）</span><div class="ctl"><input id="amk" type="password" value="'+esc(d.apiKey||"")+'" placeholder="'+(d.apiKey?"":"粘贴 API Key")+'" autocomplete="off" spellcheck="false" autocapitalize="off"><button class="eyebtn" data-act="pw-eye" data-for="amk" title="显示 / 隐藏">'+ico("eye")+'</button></div></div>'+
  '<div class="btnrow3" style="margin-top:10px"><button class="btn" data-act="ai-model-models">获取模型列表</button><button class="btn" data-act="ai-model-test">测试连接</button><button class="btn pri" data-act="ai-model-save">保存配置</button></div>'+
 "</div>"+
 '<div class="muted" style="padding:8px 2px">测试连接 / 获取模型列表会直接请求上面的接口地址；密钥仅保存在本机。</div>';
},init(){}};
function aiCfgFromForm(id){return {id:id||"tmp",name:(($("#amn")||{}).value||"").trim(),provider:(($("#ams")||{}).value)||"custom",baseUrl:(($("#amb")||{}).value||"").trim(),apiKey:(($("#amk")||{}).value||"").trim(),model:(($("#amm")||{}).value||"").trim(),stream:false}}
ACT["ai-go"]=el=>go(el.dataset.page);
ACT["ai-model-new"]=()=>{S.misc.aiNew=true;S.misc.aimEdit="";save("misc");render();toast("已新建空白配置，填写后点「保存配置」")};
ACT["ai-cfg-switch"]=el=>{if(!el.value)return;S.aiCurrent=el.value;S.misc.aiNew=false;save("aiCurrent");save("misc");render()};
ACT["ai-model-provider"]=()=>{const pr=aiPreset(($("#ams")||{}).value);if(!pr)return;if($("#amb"))$("#amb").value=pr[2];if($("#amm"))$("#amm").value=pr[3];if($("#amn")&&!$("#amn").value)$("#amn").value=pr[1];toast("已套用「"+pr[1]+"」预设")};
ACT["ai-model-save"]=()=>{const c=aiCfgFromForm(S.aiCurrent);if(!c.name)return toast("请填写配置名称");S.aiModels=S.aiModels||[];const cur=S.aiModels.find(m=>m.id===S.aiCurrent);
 if(S.misc.aiNew||!cur){c.id=uid();S.aiModels.push(c);S.aiCurrent=c.id;S.misc.aiNew=false;save("aiCurrent");save("misc");toast("已新建配置")}
 else{Object.assign(cur,c);toast("已保存配置")}
 save("aiModels");render()};
ACT["ai-model-del"]=()=>{const cur=S.aiModels.find(m=>m.id===S.aiCurrent);const id=cur?cur.id:"";if(!id)return toast("没有可删除的配置");
 confirmDlg("删除这个模型配置？","删除",true).then(ok=>{if(!ok)return;S.aiModels=S.aiModels.filter(x=>x.id!==id);if(S.aiCurrent===id)S.aiCurrent=(S.aiModels[0]||{}).id||"";S.misc.aiNew=false;save("aiModels");save("aiCurrent");save("misc");render();toast("已删除")})};
ACT["ai-model-test"]=async()=>{const c=aiCfgFromForm(S.aiCurrent);if(!c.baseUrl)return toast("请先填写接口地址");toast("正在测试连接…");try{await aiTestCfg(c);toast("连接成功 ✓")}catch(e){toast("连接失败："+(e&&e.message||e))}};
ACT["ai-model-models"]=async()=>{const c=aiCfgFromForm(S.aiCurrent);if(!c.baseUrl)return toast("请先填写接口地址");toast("正在获取模型列表…");try{const ids=await aiListModels(c);actionSheet("选择模型",ids.slice(0,60)).then(i=>{if(i<0)return;const el=$("#amm");if(el){el.value=ids[i];toast("已选择 "+ids[i])}})}catch(e){toast("获取失败："+(e&&e.message||e))}};
/* 通用：配置切换弹窗（列表 + 右侧单选圆点），避免原生下拉闪烁 */
function cfgPickSheet(title,items,currentId,onPick){
 openSheet('<div class="mtitle">'+esc(title)+'<button class="ibtn" data-r="x">'+ico("close")+"</button></div>"+
  (items.length?items.map(c=>'<button class="row listbtn" data-pick="'+c.id+'" style="border:none;background:none"><span class="lt">'+esc(c.name||"(未命名)")+(c.sub?'<br><span class="sub">'+esc(c.sub)+"</span>":"")+'</span><span class="lv"><span class="radio'+(c.id===currentId?" on":"")+'"></span></span></button>').join(""):'<div class="empty">暂无配置</div>'),true);
 $("#modal .sheet").onclick=e=>{const b=e.target.closest("[data-pick]");if(b){const id=b.dataset.pick;closeModal();onPick(id);return}if(e.target.closest("[data-r]"))closeModal()};
}
ACT["ai-cfg-open"]=()=>{const items=(S.aiModels||[]).map(m=>({id:m.id,name:m.name||"(未命名)",sub:aiPreset(m.provider)[1]+" · "+(m.model||"未设置模型")}));
 if(!items.length)return toast("还没有配置，点「新建配置」");
 cfgPickSheet("切换配置",items,S.aiCurrent,id=>{S.aiCurrent=id;S.misc.aiNew=false;save("aiCurrent");save("misc");render();toast("已切换配置")})};
/* ---- AI 调用记录 ---- */
PAGES.setailogs={html(){S.aiLogs=S.aiLogs||[];
 return phead("AI 调用记录",S.aiLogs.length?'<button class="ibtn" data-act="ai-log-clear" title="清空">'+ico("trash")+"</button>":"")+
 '<div class="muted" style="margin:2px 2px 8px">共 '+S.aiLogs.length+' 条 · 最近在最上面</div>'+
 '<div class="card" style="padding:0 12px">'+(S.aiLogs.length?S.aiLogs.map(l=>'<button class="row listbtn" data-act="ai-log-open" data-id="'+l.id+'"><span class="li">'+ico(l.ok?"check":"close")+'</span><span class="lt">'+esc(l.name||l.model||"请求")+' <span class="sub">'+esc(fmtFull(l.ts))+" · "+l.ms+"ms · 上下文 "+l.ctxLen+" 字 · "+(l.ok?"成功":("失败 "+(l.status||"")))+'</span></span><span class="lv">›</span></button>').join(""):'<div class="empty">暂无调用记录</div>')+"</div>";
},init(){}};
ACT["ai-log-open"]=el=>{const l=(S.aiLogs||[]).find(x=>x.id===el.dataset.id);if(!l)return;
 const req=(l.prompt||[]).map(m=>"["+(m.role||"")+"]\n"+(m.content||"")).join("\n\n");
 openSheet('<div class="mtitle">调用详情<button class="ibtn" data-r="x">'+ico("close")+"</button></div>"+
  '<div class="muted" style="margin-bottom:6px">'+esc(l.name||"")+" · "+esc(l.model||"")+" · "+l.ms+"ms · 请求体 "+l.reqBytes+"B · 上下文 "+l.ctxLen+" 字</div>"+
  '<div class="sect" style="margin:6px 0 2px">发送内容</div><div style="white-space:pre-wrap;font-size:13px;background:var(--bg);border-radius:10px;padding:10px;max-height:40vh;overflow:auto">'+esc(req)+"</div>"+
  '<div class="sect" style="margin:10px 0 2px">'+(l.ok?"返回内容":"错误")+'</div><div style="white-space:pre-wrap;font-size:13px;background:var(--bg);border-radius:10px;padding:10px;max-height:40vh;overflow:auto">'+esc(l.ok?l.response:(l.err||l.raw||""))+"</div>",true);
 $("#modal .sheet").onclick=e=>{if(e.target.closest("[data-r]"))closeModal()}};
