ACT["wb-del"]=el=>{const f=wbFind(el.dataset.id);if(!f)return;f.o[f.c]=f.o[f.c].filter(x=>x.id!==el.dataset.id);wbSave();render()};
ACT["wb-toggle"]=el=>{const f=wbFind(el.dataset.id);if(!f)return;f.e.on=!!el.checked;wbSave();toast(f.e.on?"已启用":"已停用")};
/* 从文件导入世界书：txt / md / docx 等，按空行拆分为多条，落入当前分类 */
ACT["wb-import"]=()=>pickFile(".txt,.md,.markdown,.doc,.docx,text/plain,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document",false,async fs=>{
 const f=fs&&fs[0];if(!f)return;const name=f.name||"";
 toast("正在读取文件…");
 let text="";
 try{ text=/\.docx$/i.test(name)?await extractDocxText(f):await readAsText(f); }
 catch(e){ toast("读取失败："+(e&&e.message||e));return }
 text=String(text||"").replace(/\r\n?/g,"\n").trim();
 if(!text)return toast("文件内容为空");
 const entries=wbSplitText(text,name);
 const cat=S.misc.wbCat||"bg";const o=wbList();
 entries.forEach(en=>o[cat].push({id:uid(),title:en.title,content:en.content,on:true}));
 wbSave();render();
 toast("已从文件导入 "+entries.length+" 条到「"+((WB_CATS.find(c=>c[0]===cat)||["",""])[1])+"」")});
function wbSplitText(text,fname){
 const blocks=String(text).split(/\n[ \t]*\n+/).map(s=>s.trim()).filter(Boolean);
 if(blocks.length<=1)return [{title:(fname||"导入条目").replace(/\.[^.]+$/,"").slice(0,30)||"导入条目",content:text}];
 return blocks.map((b,i)=>{let title="",content=b;const nl=b.indexOf("\n");const first=(nl>=0?b.slice(0,nl):b).trim();
  if(/^#{1,6}\s+/.test(first)){title=first.replace(/^#{1,6}\s+/,"").trim();content=nl>=0?b.slice(nl+1).trim():""}
  else if(nl>=0&&first.length<=24){title=first.replace(/^#+\s*/,"").trim();content=b.slice(nl+1).trim()}
  if(!content)content=b;if(!title)title="导入 "+(i+1);
  return {title:title.slice(0,40),content:content}})}
async function inflateRaw(bytes){
 if(typeof DecompressionStream==="undefined")throw new Error("当前浏览器不支持解析 docx，请另存为 txt/md 再导入");
 const s=new Blob([bytes]).stream().pipeThrough(new DecompressionStream("deflate-raw"));
 return await new Response(s).text()}
async function extractDocxText(file){
 const buf=new Uint8Array(await file.arrayBuffer());if(buf.length<22)throw new Error("文件太小");
 const dv=new DataView(buf.buffer);let eocd=-1;
 for(let i=buf.length-22;i>=Math.max(0,buf.length-65558);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break}}
 if(eocd<0)throw new Error("不是有效的 docx 文件");
 const total=dv.getUint16(eocd+10,true);let off=dv.getUint32(eocd+16,true);let tgt=null;
 for(let i=0;i<total;i++){
  if(off+46>buf.length||dv.getUint32(off,true)!==0x02014b50)break;
  const method=dv.getUint16(off+10,true),csize=dv.getUint32(off+20,true);
  const nlen=dv.getUint16(off+28,true),elen=dv.getUint16(off+30,true),clen=dv.getUint16(off+32,true);const lho=dv.getUint32(off+42,true);
  const nm=new TextDecoder().decode(buf.subarray(off+46,off+46+nlen));
  if(nm==="word/document.xml"){tgt={method,csize,lho};break}
  off+=46+nlen+elen+clen}
 if(!tgt)throw new Error("docx 内未找到正文");
 const lho=tgt.lho;if(dv.getUint32(lho,true)!==0x04034b50)throw new Error("docx 结构异常");
 const lnl=dv.getUint16(lho+26,true),lel=dv.getUint16(lho+28,true);const start=lho+30+lnl+lel;
 const bytes=buf.subarray(start,start+tgt.csize);let xml;
 if(tgt.method===0)xml=new TextDecoder().decode(bytes);
 else if(tgt.method===8)xml=await inflateRaw(bytes);
 else throw new Error("docx 使用了不支持的压缩方式");
 return docxXmlToText(xml)}
function docxXmlToText(xml){return String(xml).replace(/<w:tab[^>]*\/>/g,"\t").replace(/<w:br[^>]*\/>/g,"\n").replace(/<\/w:p>/g,"\n").replace(/<[^>]+>/g,"").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/&amp;/g,"&").replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/[ \t]+\n/g,"\n").replace(/\n{3,}/g,"\n\n").trim()}
