 if(S.misc.voiceNew||!c){c=Object.assign({id:uid()},f);S.voiceCfgs.push(c);S.voiceCfgCurrent=c.id;S.misc.voiceNew=false;save("misc");toast("已新建配置")}else{Object.assign(c,f);toast("已保存配置")}
