async function doVoiceClone(file){const v=S.settings.voice;toast("正在上传克隆…");
 try{const fd=new FormData();fd.append("file",file);
  const base=(v.baseUrl||"https://api.minimax.chat/v1").replace(/\/+$/,"");const qs=v.groupId?("?GroupId="+encodeURIComponent(v.groupId)):"";
  const res=await fetch(base+"/voice_clone"+qs,{method:"POST",headers:{"Authorization":"Bearer "+v.apiKey},body:fd});
  const raw=await res.text();const data=safeJson(raw);
  const vid=res.ok&&data&&(data.voice_id||(data.data&&data.data.voice_id));
  if(vid){const name=await promptDlg("克隆成功，给音色起个名字",file.name.replace(/\.[^.]+$/,""));S.voiceLib=S.voiceLib||[];S.voiceLib.push({id:uid(),name:name||"克隆音色",voiceId:vid,clone:true});save("voiceLib");if(cur==="setaivoice")render();toast("已保存克隆音色");return}
  const why=(data&&((data.base_resp&&data.base_resp.status_msg)||data.message))||("HTTP "+res.status);
  const manual=await promptDlg("自动克隆未成功（"+why+"）。可手动填入克隆得到的 Voice ID","");
  if(manual){const name=await promptDlg("音色名称",file.name.replace(/\.[^.]+$/,""));S.voiceLib=S.voiceLib||[];S.voiceLib.push({id:uid(),name:name||"克隆音色",voiceId:manual,clone:true});save("voiceLib");if(cur==="setaivoice")render()}
 }catch(e){toast("克隆失败："+(e&&e.message||e))}}
/* ---- 长按 TA 的文字问「什么意思」 ---- */
async function askMeaning(msgId){const m=S.chats.find(x=>x.id===msgId);if(!m||m.type!=="text")return;const cfg=aiActive();if(!cfg||!cfg.apiKey)return toast("请先在「AI 模型配置」里配置可用模型");
 const sys=buildAISystemPrompt("chat");const up="用户不明白角色这句话的意思。请用一句简短旁白解释这句话的含义、语气与潜台词，不要替角色继续对话：\n「"+(m.text||"")+"」"; toast("正在解读…");
 try{const out=await aiRequest(cfg,[{role:"system",content:sys},{role:"user",content:up}],{max_tokens:200});openSheet('<div class="mtitle">什么意思<button class="ibtn" data-r="x">'+ico("close")+'</button></div><div style="white-space:pre-wrap;font-size:14px">'+esc(out)+"</div>",true);$("#modal .sheet").onclick=e=>{if(e.target.closest("[data-r]"))closeModal()}}catch(e){toast("解读失败："+(e&&e.message||e))}}
