let _lpTimer=null,_lpFired=false;
document.addEventListener("pointerdown",e=>{const b=e.target.closest&&e.target.closest("#msgs .bub");if(!b)return;const msgEl=b.closest(".msg");if(!msgEl||msgEl.classList.contains("me"))return;if(!(S.settings.aiReply&&S.settings.aiReply.askMeaning))return;_lpFired=false;clearTimeout(_lpTimer);_lpTimer=setTimeout(()=>{_lpFired=true;try{navigator.vibrate&&navigator.vibrate(10)}catch(e){}askMeaning(b.dataset.id)},520)});
["pointerup","pointercancel","scroll"].forEach(ev=>document.addEventListener(ev,()=>clearTimeout(_lpTimer),true));
