const MISC_APP_FIELDS=["favs","memos","divineHist","periodSet","annivWidget","together","groups"];
function otherMisc(){const o={};for(const k in S.misc)if(MISC_APP_FIELDS.indexOf(k)<0)o[k]=S.misc[k];return o}
const STORE_APPS=[
 {id:"fav",label:"收藏",icon:"fav",parts:[{misc:"favs"}],clear:()=>{delete S.misc.favs}},
 {id:"memo",label:"备忘录",icon:"memo",parts:[{misc:"memos"}],clear:()=>{delete S.misc.memos}},
 {id:"trace",label:"寻踪",icon:"trace",parts:[{misc:"trace"},{misc:"loc"}],clear:()=>{delete S.misc.trace;delete S.misc.loc}},
 {id:"divine",label:"占卜",icon:"divine",parts:[{store:"divine"},{misc:"divineHist"}],clear:()=>{S.divine=[];delete S.misc.divineHist}},
 {id:"chat",label:"聊天",icon:"chat",parts:[{store:"chats"}],clear:()=>{S.chats=[]}},
 {id:"moments",label:"朋友圈",icon:"moments",parts:[{store:"moments"}],clear:()=>{S.moments=[]}},
 {id:"mail",label:"信箱",icon:"mail",parts:[{store:"letters"}],clear:()=>{S.letters=[]}},
 {id:"music",label:"音乐",icon:"music",parts:[{store:"audios"}],clear:()=>{S.audios=[];S.misc.mu=null}},
 
 {id:"period",label:"月经",icon:"period",parts:[{store:"periods"},{misc:"periodSet"}],clear:()=>{S.periods=[];delete S.misc.periodSet}},
 {id:"mall",label:"商城",icon:"mall",parts:[{misc:"mall"}],clear:()=>{delete S.misc.mall}},
 {id:"cards",label:"字卡库",icon:"lib",parts:[{store:"cards"},{misc:"groups"}],clear:()=>{S.cards=[];S.misc.groups={}}},
 {id:"pickup",label:"灵感拾取",icon:"star",parts:[{store:"pickup"}],clear:()=>{S.pickup={on:false,prob:(S.pickup&&S.pickup.prob)||30,items:[]};S.cards=S.cards.filter(c=>c.cat!==PICKUP_CAT)}},
 {id:"anniv",label:"纪念日",icon:"anniv",parts:[{store:"annivs"},{misc:"annivWidget"},{misc:"together"}],clear:()=>{S.annivs=[];delete S.misc.annivWidget;delete S.misc.together}},
 {id:"settings",label:"设置",icon:"set",parts:[{store:"settings"}],clear:()=>{S.settings=JSON.parse(JSON.stringify(DEF_SETTINGS))}},
 {id:"ai",label:"AI",icon:"ai",parts:[{store:"aiModels"},{store:"aiCurrent"},{store:"aiLogs"},{store:"worldbook"},{store:"voiceLib"}],clear:()=>{S.aiModels=[];S.aiCurrent="";S.aiLogs=[];S.worldbook={};S.voiceLib=[]}},
 {id:"assets",label:"图片资源",icon:"img",parts:[{store:"assets"}],clear:()=>{S.assets={}}},
 {id:"misc",label:"其他",icon:"dots",parts:[{miscOther:true}],clear:()=>{for(const k in S.misc)if(MISC_APP_FIELDS.indexOf(k)<0&&k!=="seeded")delete S.misc[k]}},
];
function appSize(g){let n=0;for(const p of g.parts){if(p.store)n+=bytesOf(S[p.store]);else if(p.misc)n+=bytesOf(S.misc[p.misc]);else if(p.miscOther)n+=bytesOf(otherMisc())}return n}
PAGES.setstore={html(){return phead("存储")+
 '<div class="sect">存储空间</div><div class="card">'+
  '<div class="row" style="border:none;padding-top:0;padding-bottom:4px"><span class="lab" style="color:var(--muted);font-size:12px">占用与配额</span><button class="btn sm" data-act="storage-refresh">刷新</button></div>'+
  '<div id="storcard"><div class="muted">统计中…</div></div>'+
 '</div>'+
 '<div class="sect">数据分组</div><div class="card" style="padding:0 12px">'+
  STORE_APPS.map(g=>'<div class="row"><span class="lab" style="display:flex;align-items:center;gap:8px"><span style="color:var(--icon,var(--primary));width:18px;display:inline-flex">'+ico(g.icon)+'</span>'+g.label+'<span class="sub" data-sizefor="'+g.id+'"></span></span>'+(g.parts.length?'<button class="btn sm danger" data-act="storage-cleargroup" data-k="'+g.id+'">清除</button>':'<button class="btn sm" disabled>清除</button>')+'</div>').join("")+
  '<div class="muted" style="padding:6px 0 12px">按软件清除，范围小于「重置全部数据」，同样不可恢复。</div>'+
 '</div>'+
 '<div class="sect">备份与恢复</div><div class="card" style="padding:0 12px">'+
  actionRow("down","全量备份导出",'data-act="storage-backup-export"')+
  actionRow("up","全量备份导入",'data-act="storage-backup-import"')+
  '<div class="muted" style="padding:6px 0 12px">全量备份包含：聊天记录、字卡数据、灵感拾取、设置；导入为覆盖恢复。</div>'+
 '</div>'+
 '<div class="sect">危险操作</div><div class="card" style="padding:0 12px">'+
  actionRow("trash","重置全部数据",'data-act="storage-clear"',true)+
  '<div class="muted" style="padding:6px 0 12px">所有操作均需二次确认，操作完成后不可逆。</div>'+
 '</div>'},
 init(){renderStorageCard()}};
/* ---- 存储占用统计 ---- */
function fmtBytes(n){if(n==null||!isFinite(n))return"—";const u=["B","KB","MB","GB"];let i=0,x=+n;while(x>=1024&&i<u.length-1){x/=1024;i++}return (i===0?Math.round(x):(x<10?x.toFixed(1):Math.round(x)))+" "+u[i]}
function bytesOf(v){try{
 if(v==null)return 0;
 const t=typeof v;
 if(t==="string")return v.length;
 if(t==="number")return 8;
 if(t==="boolean")return 4;
 if(v instanceof Blob)return v.size;
 if(Array.isArray(v)){let n=0;for(const x of v)n+=bytesOf(x);return n}
 if(t==="object"){let n=0;for(const k in v)n+=k.length*2+bytesOf(v[k]);return n}
 return 0}catch(e){return 0}}
async function storageInfo(){
 let usage=null,quota=null,persisted=false;
 try{if(navigator.storage&&navigator.storage.estimate){const e=await navigator.storage.estimate();usage=e.usage;quota=e.quota}}catch(e){}
 try{if(navigator.storage&&navigator.storage.persisted)persisted=await navigator.storage.persisted()}catch(e){}
 return {usage,quota,persisted}}
let _storWarnShown=false;
function showStorWarn(pct,warn){
 const sh=openSheet('<div style="color:#fff;text-align:center"><div style="font-size:16px;font-weight:600;margin-bottom:8px">存储空间提醒</div><div style="font-size:13px;line-height:1.6;opacity:.95">已用空间达到 '+pct+'%，超过提醒阈值 '+warn+'%。<br>建议在「数据分组」中清理不再需要的数据。</div></div><div class="btnrow center" style="margin-top:16px"><button class="btn" data-r="ok" style="background:rgba(255,255,255,.22);border-color:rgba(255,255,255,.5);color:#fff">知道了</button></div>',true);
 sh.style.background="rgba(214,69,69,.9)";sh.style.backdropFilter="blur(2px)";
 sh.onclick=e=>{if(e.target.closest("[data-r]"))closeModal()}}
function persistFail(reason){
 openSheet('<div class="mtitle center">未能启用持久化</div><div class="muted" style="line-height:1.7">'+esc(reason)+'。<br><br>可尝试：<br>1. 确认使用普通窗口（无痕 / 隐私模式下无法持久化）；<br>2. 把本页「添加到主屏幕」后从桌面图标打开，更容易获得授权；<br>3. 检查 Edge / Chrome 设置里未开启「退出时清除浏览数据」，且未禁用本站存储；<br>4. 站点被频繁访问、存储配额充足时，浏览器更可能自动授予。</div><div class="btnrow center" style="margin-top:12px"><button class="btn pri" data-r="ok">知道了</button></div>',true);
 $("#modal .sheet").onclick=e=>{if(e.target.closest("[data-r]"))closeModal()}}
let _sizeCache={};
function appSizeCached(g){const t=Date.now(),c=_sizeCache[g.id];if(c&&(t-c.t)<30000)return c.v;const v=appSize(g);_sizeCache[g.id]={t:t,v:v};return v}
function renderStorageCard(){
 const paint=info=>{const card=$("#storcard");if(card)card.innerHTML=storageHtml(info);
  const _q=STORE_APPS.slice();let _tot=0;
  const _step=()=>{const g=_q.shift();
   if(!g){const tt=document.getElementById("stortotal");if(tt)tt.innerHTML="<b>"+fmtBytes(_tot)+"</b> 估算占用";return}
   const v=appSizeCached(g);_tot+=v;const el=document.querySelector('[data-sizefor="'+g.id+'"]');if(el)el.textContent=" "+fmtBytes(v);
   setTimeout(_step,16)};
  setTimeout(_step,32)};
 paint({usage:null,quota:null,persisted:null});
 (async()=>{
  /* 直接尝试启用持久化，浏览器同意后即长期生效 */
  try{if(navigator.storage&&navigator.storage.persist)await navigator.storage.persist()}catch(e){}
  const info=await storageInfo();
  paint(info);
  const warn=+((S.settings.system||{}).storageWarn)||0;
  if(info.usage!=null&&info.quota&&warn>0){const pct=Math.round(info.usage/info.quota*1000)/10;if(pct>=warn&&!_storWarnShown){_storWarnShown=true;setTimeout(()=>showStorWarn(pct,warn),120)}}
 })().catch(()=>{})}
function storageHtml(info){const {usage,quota,persisted}=info;
 const warn=+((S.settings.system||{}).storageWarn)||0;
 let head="";
 if(usage!=null&&quota){
  const pct=Math.min(100,Math.round(usage/quota*1000)/10);
  const over=warn>0&&pct>=warn;
  if(over)head+='<div class="storwarn">占用已达 '+pct+'%，超过提醒阈值 '+warn+'%，建议清理数据。</div>';
  head+='<div class="storbar'+(over?" danger":"")+'"><i style="width:'+Math.max(1,pct)+'%"></i></div>'+
    '<div class="stortext"><span><b>'+fmtBytes(usage)+'</b> 已用</span><span class="muted">可用 '+fmtBytes(quota)+' · 占用 '+pct+'%</span></div>'+
    '<div class="muted" style="padding:0 0 2px;line-height:1.7">「可用」是浏览器给星笺的额度，跟着手机剩余空间走，和你在星笺里存了多少无关（所以这个数字自己会变）；星笺目前还能再存 '+fmtBytes(Math.max(0,quota-usage))+'。</div>'}
 else{head+='<div class="stortext"><span id="stortotal"><b>计算中</b> 估算占用</span><span class="muted">当前环境不支持配额查询</span></div>'}
 let persist;
 if(persisted==null){persist='<div class="storrow2"><span class="sname2">持久化存储</span><span class="muted">检测中…</span></div>'}
 else if(persisted){persist='<div class="storrow2"><span class="sname2">持久化存储</span><span class="stpill on">已持久化</span></div>'+
  '<div class="muted" style="padding:0 0 2px">已持久化（浏览器承诺不自动清理）：磁盘空间紧张或长期未访问时，也不会删除这里的聊天、字卡与设置。</div>'}
 else{persist='<div class="storrow2"><span class="sname2">持久化存储</span><span class="stpill">未持久化</span><button class="btn sm" data-act="storage-persist">申请持久化存储</button></div>'+
  '<div class="muted" style="padding:0 0 2px">未持久化：空间紧张或长期未访问时，浏览器可能自动清理本应用数据。可点右侧按钮向浏览器申请。</div>'}
 /* 版本号：用来确认手机上跑的到底是哪一版（若这里不是最新版，说明离线缓存还没更新，关掉重开两次即可）*/
 let swState="浏览器标签页";
 try{if(navigator.serviceWorker&&navigator.serviceWorker.controller)swState="离线缓存已接管"}catch(e){}
 const build='<div class="storrow2"><span class="sname2">应用版本</span><span class="stpill">'+esc(APP_BUILD)+' · '+swState+'</span></div>'+
   '<div class="muted" style="padding:0 0 2px;line-height:1.7">版本号没变说明还在用旧缓存。① 先在浏览器里打开一次这个网址，等界面完全出来（会让它后台换缓存）；② 还是没变就等一天再试；③ 想立刻更新：清掉该网站的「站点数据」（会清空应用数据，请先在「设置 → 存储 → 导出备份」里备份）。</div>'+
   '<div class="row" style="border-top:1px solid var(--line)"><span class="lab">本地备份（自动）<br><span class="sub">列表要变空时，自动把原来的内容存一份；这里可以恢复回来</span></span><button class="btn sm" data-act="storage-restore">恢复备份</button></div>';
 return head+persist+build}

/* ================= export / import ================= */
async function prepExport(k){const v=S[k];
 if(k==="cards"){const out=[];for(const c of v){const c2={...c};if(c2.data instanceof Blob)c2.data=await blobToDataUrl(c2.data);out.push(c2)}return out}
 if(k==="chats"){const out=[];for(const m of v){const m2={...m};if(m2.data instanceof Blob)m2.data=await blobToDataUrl(m2.data);out.push(m2)}return out}
 if(k==="audios"){const out=[];let tot=0;for(const a of v)tot+=((a.dlBytes||(a.blob&&a.blob.size))||0);
  for(const a of v){const b={...a};delete b._u;
   if(tot<8*1024*1024&&(a.blob||a.local)&&((a.dlBytes||(a.blob&&a.blob.size))||0)>0){
    const bl=a.blob||await muBlobGet(a.id);if(bl&&bl.size)b.blob=await blobToDataUrl(bl)}else{delete b.blob}
   out.push(b)}return out}
 if(k==="moments"){const out=[];for(const p of v){const p2={...p};if(p2.voiceData instanceof Blob)p2.voiceData=await blobToDataUrl(p2.voiceData);if(Array.isArray(p2.cmts)){p2.cmts=[];for(const c of p.cmts){const c2={...c};if(c2.voiceData instanceof Blob)c2.voiceData=await blobToDataUrl(c2.voiceData);p2.cmts.push(c2)}}out.push(p2)}return out}
 return v}
async function exportKeys(keys,name){const data={app:"xingjian",ver:1,data:{}};for(const k of keys)data.data[k]=await prepExport(k);download(name||("星笺数据_"+dayKey(Date.now())+".json"),JSON.stringify(data));toast("已导出")}
async function restoreVal(k,v){if(k==="cards"){for(const c of v)if(typeof c.data==="string"&&c.data.startsWith("data:"))c.data=await dataUrlToBlob(c.data);return v}
 if(k==="chats"){for(const m of v)if(typeof m.data==="string"&&m.data.startsWith("data:audio"))m.data=await dataUrlToBlob(m.data);return v}
 if(k==="audios"){for(const a of v)if(typeof a.blob==="string"&&a.blob.startsWith("data:"))a.blob=await dataUrlToBlob(a.blob);return v}
 if(k==="moments"){for(const p of v){if(typeof p.voiceData==="string"&&p.voiceData.startsWith("data:audio"))p.voiceData=await dataUrlToBlob(p.voiceData);if(Array.isArray(p.cmts))for(const c of p.cmts){if(typeof c.voiceData==="string"&&c.voiceData.startsWith("data:audio"))c.voiceData=await dataUrlToBlob(c.voiceData)}}return v}
 return v}
async function importData(obj,mode){const d=obj.data||obj;const replace=mode==="replace";
 for(const k of SAVEKEYS){if(!(k in d))continue;const v=await restoreVal(k,JSON.parse(JSON.stringify(d[k])));
  if(k==="settings")S.settings=deepMerge(replace?DEF_SETTINGS:S.settings,v);
  else if(k==="misc"||k==="assets")S[k]=replace?v:{...S[k],...v};
  else if(Array.isArray(v))S[k]=replace?v:S[k].concat(v);
  else S[k]=v;
  save(k)}
  /* 老备份里可能没有 misc（那样分组清单就丢了）：用字卡自带的 group 字段补回来；情绪/心意字卡的分组用预设补回来 */
  try{
   if(!S.misc.groups||typeof S.misc.groups!=="object")S.misc.groups={};
   (S.cards||[]).forEach(function(c){try{if(!c||!c.cat||!c.group)return;
    if(!S.misc.groups[c.cat])S.misc.groups[c.cat]=[];
    if(S.misc.groups[c.cat].indexOf(c.group)<0)S.misc.groups[c.cat].push(c.group)}catch(e){}});
   save("misc");
   try{moodSeedIntoLib()}catch(e){}
  }catch(e){}
 applyTheme();applyChatUI();applyFont();applySystem();try{pkSyncPool();save("cards")}catch(e){};render();toast(replace?"已恢复备份":"导入完成")}
/* ================= 聊天设置 ================= */
