ACT["chat-font-up"]=()=>{const cur=S.settings.appFont||"";
 openSheet('<div class="mtitle">全局字体<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  '<div class="muted" style="margin-bottom:8px">上传本地字体 (ttf / otf / woff / woff2)，应用后本桌面全部页面生效；也可直接粘贴字体链接或字体名（如 Microsoft YaHei）</div>'+
  '<input id="fontin" placeholder="字体链接或字体名" value="'+esc(cur==="__file__"?"本地字体（已上传）":cur)+'">'+
  '<div class="btnrow" style="margin-top:12px"><button class="btn" data-font="up" style="flex:1">上传字体</button><button class="btn" data-font="reset" style="flex:1">恢复默认</button><button class="btn pri" data-font="apply" style="flex:1">应用</button></div>',true);
 $("#modal .sheet").onclick=e=>{const b=e.target.closest("[data-font]");if(!b){if(e.target.closest("[data-r]"))closeModal();return}const op=b.dataset.font;
  if(op==="up"){pickFile(".ttf,.otf,.woff,.woff2,font/*",false,fs=>readAsDataURL(fs[0]).then(u=>{S.assets.app_font=u;S.settings.appFont="__file__";save("assets");save("settings");const inp=$("#fontin");if(inp)inp.value="本地字体（已上传）";applyFont();toast("字体已上传并生效")}));return}
  if(op==="reset"){S.settings.appFont="";delete S.assets.app_font;save("settings");save("assets");applyFont();const inp2=$("#fontin");if(inp2)inp2.value="";toast("已恢复默认字体");return}
  const v=($("#fontin").value||"").trim();if(v==="本地字体（已上传）"){S.settings.appFont="__file__"}else{S.settings.appFont=v}save("settings");applyFont();closeModal();toast("已应用字体")}};
ACT["chat-font-clr"]=()=>{S.settings.appFont="";delete S.assets.app_font;save("settings");save("assets");applyFont();render()};
/* ---- 头像更换（仅支持从相册/文件上传，不提供预设头像；落库口径与 mochi 头像池一致 256px/0.85） ---- */
function changeAvatar(who){who=who||"me";pickFile("image/*",false,fs=>{const f=fs[0];if(!f)return;if(f.size>10*1024*1024){toast("图片过大，请选择更小的图片");return}toast("处理中…");readAsDataURL(f).then(u=>compressImage(u,256,.85)).then(c=>{setAvatar(who,c);toast("头像已更新")}).catch(()=>toast("头像处理失败，请重试"))})}
let avaTapT=null;
/* 聊天里的头像不再「点一下就换头像」（会弹出手机相册），避免误触；
   想换头像去 聊天设置 → 我的头像 / 对方头像。双击头像仍然是原有的「拍一拍」。 */
ACT["ava-tap"]=()=>{};
/* 双击头像 = 拍一拍（参考 mochi：双击 TA 头像拍 TA，双击自己的头像拍自己） */
function patAva(who){const pool=patPool();const card=pool.length?pick(pool):"";sendPat(card,who==="me"?"self":"me")}
/* 头像不再有点击 / 双击行为（以前双击是「拍一拍」，已按需求去掉） */
/* ================= 拍一拍工具弹窗 =================
   一级分类（公用 / 特定人物 / 符号图标）× 二级分类（未分组 / 预设 / 我的新增 / 自定义分组）
   * 列表选取、内联编辑删除、底部「存入 / 发送」 */
const PAT_CATS=["拍一拍","拍一拍·我"];
/* 一级分类：跟随昵称变化 —— 【TA】的拍一拍 /【我】的拍一拍 */
function patPrimaryList(){return [["pub","【"+(S.settings.taName||"TA")+"】","拍一拍"],["who","【"+(S.settings.myName||"我")+"】","拍一拍·我"]]}
let patInput="",patSel=null,patFocus=false;
function patPrimary(){const k=S.misc.patPrimary;return patPrimaryList().some(p=>p[0]===k)?k:"pub"}
function patCat(){return (patPrimaryList().find(p=>p[0]===patPrimary())||patPrimaryList()[0])[2]}
function patPrimaryLabel(){return (patPrimaryList().find(p=>p[0]===patPrimary())||patPrimaryList()[0])[1]}
function patGroups(){S.misc.groups=S.misc.groups||{};const c=patCat();if(!Array.isArray(S.misc.groups[c]))S.misc.groups[c]=[];return S.misc.groups[c]}
function patSec(){const s=S.misc.patSec||"all";const ok=["all"].concat(patGroups().map(g=>"g:"+g));return ok.indexOf(s)>=0?s:"all"}
/* 随机拍一拍（双击头像 / 对方主动拍）用的合并池 */
function patPool(){return PAT_CATS.reduce((a,c)=>a.concat(cardTexts(c)),[])}
function patFiltered(){const s=patSec(),it=cardsOf(patCat()).filter(c=>c.type==="text");
 if(s.indexOf("g:")===0){const g=s.slice(2);return it.filter(c=>c.group===g)}
 return it}
function patSheetHtml(){const sec=patSec(),list=patFiltered(),groups=patGroups();
 return '<div class="pathead"><span class="t">拍一拍 · '+esc(patPrimaryLabel())+'</span><button class="ibtn" data-r="x" title="关闭">'+ico("close")+"</button></div>"+
  '<div class="patlist">'+
   '<div class="patnav">'+patPrimaryList().map(p=>'<button class="chip'+(patPrimary()===p[0]?" on":"")+'" data-pp="'+p[0]+'">'+esc(p[1])+"</button>").join("")+"</div>"+
   '<div class="patnav">'+[["all","全部"]].map(s=>'<button class="chip'+(sec===s[0]?" on":"")+'" data-ps="'+s[0]+'">'+s[1]+"</button>").join("")+
    groups.map(g=>'<button class="chip'+(sec==="g:"+g?" on":"")+'" data-ps="g:'+esc(g)+'">'+esc(g)+"</button>").join("")+
    '<button class="chip" data-gmgr="1">＋ 分组</button></div>'+
   (list.length?list.map(c=>{const ed=!!(c.mine||c.group);
     return '<div class="patitem'+(patSel===c.id?" sel":"")+'" data-pi="'+c.id+'"><span class="txt">'+esc(c.content)+"</span>"+
      (ed?'<span class="ops"><button class="ibtn" data-ped="'+c.id+'" title="编辑">'+ico("edit")+'</button><button class="ibtn" data-pdl="'+c.id+'" title="删除">'+ico("trash")+"</button></span>":"")+
     "</div>"}).join(""):'<div class="empty">这个分类还没有文案</div>')+"</div>"+
  '<div class="patbar"><input id="patin" placeholder="输入拍一拍文案…" value="'+esc(patInput)+'"><button class="btn sm" data-pact="save">存入</button><button class="btn pri sm" data-pact="send">发送</button></div>'}
function patRerender(){const sh=document.querySelector("#modal .sheet");if(!sh)return;sh.innerHTML=patSheetHtml();
 if(patFocus){patFocus=false;const i=document.querySelector("#patin");if(i){try{i.focus();i.setSelectionRange(i.value.length,i.value.length)}catch(e){}}}}
let patGateUntil=0;
function openPatSheet(){patSel=null;patFocus=false;patGateUntil=performance.now()+700;   /* 参考 mochi pokeArmClickGate：拦截打开瞬间的残留点击 */
 const sh=openSheet(patSheetHtml());sh.classList.add("patsheet","panelsheet");
 sh.oninput=e=>{if(e.target&&e.target.id==="patin")patInput=e.target.value};
 sh.onkeydown=e=>{if(e.key==="Enter"&&e.target&&e.target.id==="patin"&&!e.isComposing){e.preventDefault();patGateUntil=0;const b=sh.querySelector('[data-pact="send"]');if(b)b.click()}};
 sh.onclick=e=>{
  if(e.target.closest("[data-r]")){closeModal();return}
  if(performance.now()<patGateUntil)return;
  const pr=e.target.closest("[data-pp]");if(pr){S.misc.patPrimary=pr.dataset.pp;S.misc.patSec="all";patSel=null;save("misc");patRerender();return}
  if(e.target.closest("[data-gmgr]")){openPatGroupSheet();return}
  const sc=e.target.closest("[data-ps]");if(sc){S.misc.patSec=sc.dataset.ps;patSel=null;save("misc");patRerender();return}
  const ed=e.target.closest("[data-ped]");if(ed){const c=S.cards.find(x=>x.id===ed.dataset.ped);if(!c)return;
   promptDlg("编辑拍一拍文案",c.content).then(v=>{if(v==null){openPatSheet();return}const t=String(v).trim();if(!t){toast("不能为空");openPatSheet();return}
    c.content=t;save("cards");patInput=t;openPatSheet();toast("已保存")});return}
  const dl=e.target.closest("[data-pdl]");if(dl){const c=S.cards.find(x=>x.id===dl.dataset.pdl);if(!c)return;
   confirmDlg("删除这条拍一拍文案？","删除",true).then(ok=>{if(ok){S.cards=S.cards.filter(x=>x.id!==c.id);save("cards");toast("已删除")}openPatSheet()});return}
  const it=e.target.closest("[data-pi]");if(it){const c=S.cards.find(x=>x.id===it.dataset.pi);if(!c)return;
   /* 点具体某一条 → 直接发送到聊天 */
   patInput=c.content;if(!patTextOnly(c.content)){toast("这条不是文字拍一拍，已跳过");return}closeModal();sendPat(c.content,"me");return}
  const b=e.target.closest("[data-pact]");if(!b)return;
  const v=((document.querySelector("#patin")||{}).value||"");patInput=v;const t=v.trim();
  if(b.dataset.pact==="save"){if(!t)return toast("先输入文案");
   const s=patSec(),card={id:uid(),cat:patCat(),type:"text",content:t,group:""};
   if(s.indexOf("g:")===0)card.group=s.slice(2);else card.mine=true;
   S.cards.push(card);save("cards");patSel=card.id;save("misc");patRerender();
   toast(card.group?"已存入「"+card.group+"」":"已新增一条");return}
  if(!t)return toast("先输入或选择文案");
  if(!patTextOnly(t))return toast("这条不是文字拍一拍，已跳过");
  closeModal();sendPat(t,"me")}}
/* 点击撤回的消息查看原文（再次点击隐藏） */
let _retT=null;
ACT["view-retract"]=el=>{const m=S.chats.find(x=>x.id===el.dataset.id);if(!m||!m.retracted)return;
 m.showRet=!m.showRet;
 /* 只重绘这一条气泡（不再整列表 renderMsgs），点击才会丝滑 */
 try{
  const bub=el.closest?el.closest(".bub"):null;
  if(bub){
   const tmp=document.createElement("div");tmp.innerHTML=msgBubble(m);
   const nb=tmp.querySelector(".bub");
   if(nb){
    bub.innerHTML=nb.innerHTML;
    bub.classList.remove("swapin");void bub.offsetWidth;
    bub.classList.add("swapin");
    clearTimeout(_retT);_retT=setTimeout(function(){try{bub.classList.remove("swapin")}catch(e){}},280);
   }
  }
 }catch(e){}
 save("chats")};
ACT["pat-open"]=()=>openPatSheet();
/* ---------- 分组管理模块（新建 / 删除分组） ---------- */
function patGroupCount(n){return cardsOf(patCat()).filter(c=>c.group===n).length}
function patGroupSheetHtml(){const g=patGroups();
 return '<div class="pathead"><span class="t">分组管理 · '+esc(patPrimaryLabel())+'</span><button class="ibtn" data-r="x" title="关闭">'+ico("close")+"</button></div>"+
  '<div class="muted" style="padding:0 14px 4px">分类：'+esc(patCat())+'　·　删除分组后，组内文案会保留（变回未分组）</div>'+
  '<div class="patlist">'+(g.length?g.map(n=>'<div class="patitem"><span class="txt">'+esc(n)+'<span style="color:var(--muted);font-size:12px"> · '+patGroupCount(n)+' 条</span></span>'+
    '<span class="ops"><button class="ibtn" data-gdel="'+esc(n)+'" title="删除分组">'+ico("trash")+"</button></span></div>").join(""):'<div class="empty">还没有分组，点下面「新建分组」</div>')+"</div>"+
  '<div class="patbar"><button class="btn sm" style="flex:1" data-gadd="1">＋ 新建分组</button><button class="btn pri sm" style="flex:1" data-gdone="1">完成</button></div>'}
function openPatGroupSheet(){const sh=openSheet(patGroupSheetHtml());sh.classList.add("patsheet","panelsheet");
 sh.onclick=e=>{
  if(e.target.closest("[data-r]")){closeModal();return}
  if(e.target.closest("[data-gdone]")){openPatSheet();return}
  if(e.target.closest("[data-gadd]")){promptDlg("新建分组","").then(n=>{if(n==null){openPatGroupSheet();return}
    const t=String(n).trim();if(!t){toast("请输入分组名");openPatGroupSheet();return}
    const g=patGroups();if(g.indexOf(t)<0){g.push(t);toast("已新建分组「"+t+"」")}else toast("分组已存在");
    S.misc.patSec="g:"+t;save("misc");openPatGroupSheet()});return}
  const del=e.target.closest("[data-gdel]");if(del){const n=del.dataset.gdel;
   confirmDlg("删除分组「"+n+"」？组内文案会保留（变回未分组）","删除",true).then(ok=>{
    if(ok){const g=patGroups(),i=g.indexOf(n);if(i>=0)g.splice(i,1);
     cardsOf(patCat()).forEach(c=>{if(c.group===n){c.group="";c.mine=true}});
     if(patSec()==="g:"+n)S.misc.patSec="all";
     save("misc");save("cards");toast("已删除分组「"+n+"」")}
    openPatGroupSheet()});return}}}
ACT["ava-shape"]=el=>{S.settings.chat.avaShape=el.dataset.v;save("settings");applyChatUI();render()};
/* ---- 头像和昵称互动（参考 mochi avatar-lib 全链：四池 + 两级面板 + 50%/70% 邀请回应 + 四个独立 1-8 小时定时器 + 改名清扫） ---- */
const AV_INVITE_PROB=50,AV_AGREE_PROB=70;
/* 昵称清洗（参考 mochi #616：零宽字符能穿过 trim，入库前剥掉不可见字符，剥完为空即丢弃） */
function cleanNick(s){return String(s==null?"":s).replace(/[\u00AD\u200B-\u200F\u202A-\u202E\u2060-\u2064\u206A-\u206F\uFEFF\u180E]/g,"").trim().slice(0,30)}
function strHash(s){let h=5381;s=String(s||"");for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))|0}return String(h)}
function nickPool(){S.misc.pool=S.misc.pool||{};["meAva","taAva","meName","taName"].forEach(k=>S.misc.pool[k]=S.misc.pool[k]||[]);return S.misc.pool}
function avEn(){S.misc.avEn=S.misc.avEn||{taAva:true,meAva:true,taName:true,meName:true};return S.misc.avEn}
function avTm(k){S.misc.avTm=S.misc.avTm||{};if(!S.misc.avTm[k])S.misc.avTm[k]={last:0,next:0,hash:""};return S.misc.avTm[k]}
function sheetOpen(){const m=$("#modal");return !!m&&m.classList.contains("on")}
/* 系统消息统一入口（img=附带的头像图；keep=昵称事件记录，豁免改名清扫） */
function sysMsg(text,img,keep){return pushChat({type:"sys",text:text,img:img||undefined,nickKeep:keep?true:undefined})}
/* 改名清扫（参考 mochi chatSysNickChanged）：历史系统消息里的旧昵称字面扫成 {ta}/{me} 占位符，渲染期回填当前昵称；
   nickKeep 消息是当时发生的事实、豁免；{me} 侧人称代词「我/你」不扫；legacy 默认称呼「TA」沿同一钩子补扫 */
function sysNickSweep(old,slot){if(!old)return false;if(slot==="me"&&(old==="我"||old==="你"))return false;
 const tok=slot==="me"?"{me}":"{ta}";let ch=false;
 S.chats.forEach(m=>{if(!m||m.type!=="sys"||m.nickKeep||typeof m.text!=="string"||m.text.indexOf(old)<0)return;
  const t=m.text.split(old).join(tok);if(t!==m.text){m.text=t;ch=true}});
 return ch}
function sysNickChanged(old,slot){if(!old)return;
 S.misc.nickHist=S.misc.nickHist||{ta:[],me:[]};const h=S.misc.nickHist[slot]||(S.misc.nickHist[slot]=[]);
 const curN=slot==="me"?(S.settings.myName||"我"):(S.settings.taName||"TA");
 if(h.indexOf(old)<0)h.push(old);if(h.indexOf(curN)<0)h.push(curN);
 let ch=sysNickSweep(old,slot);
 if(slot==="ta"&&old!=="TA"&&h.indexOf("TA")<0){h.push("TA");if(sysNickSweep("TA","ta"))ch=true}
 save("misc");if(ch){save("chats");if(cur==="chat")renderMsgs()}}
/* 昵称应用统一入口（设置输入 / 昵称池点选 / TA 换我的昵称都走这里）：清洗 → 落库 → 清扫 → 顶栏与面板同步 */
function applyTaNick(name){const old=S.settings.taName||"TA";const v=cleanNick(name);const nw=v||"TA";
 S.settings.taName=v;save("settings");try{localStorage.setItem("nickname",v)}catch(e){}
 if(old!==nw)sysNickChanged(old,"ta");
 const cn=$("#ctname");if(cn)cn.textContent=nw;syncAvSheet();if(cur==="chatset")render()}
function applyMyNick(name){const old=S.settings.myName||"我";const v=cleanNick(name);const nw=v||"我";
 S.settings.myName=v;save("settings");
 if(old!==nw)sysNickChanged(old,"me");
 syncAvSheet();if(cur==="chatset")render()}
/* 头像应用统一入口（参考 mochi applyAvatarImg 口径：气泡头像原位改 src、值没变不碰节点，避免整列闪烁）
   * 强制刷新：聊天气泡 + 朋友圈动态 + 朋友圈封面三处的头像节点一起原位改，
     不依赖「退出页面再进来」，也保证永远和全局头像一致 */
function setAvatar(who,dataUrl){const k=who==="me"?"ava_me":"ava_ta";
 if(dataUrl)S.assets[k]=dataUrl;else delete S.assets[k];
 save("assets");
 applyAvatarDom(who,dataUrl||"");
 try{refreshCallVisuals()}catch(e){}
 syncAvSheet();
 /* 正在看朋友圈 / 其它页面时，整页重画一次（朋友圈列表实时读全局头像，重画即最新） */
 try{if(cur==="moments")renderMoments();else if(cur!=="chat")render()}catch(e){}}
function applyAvatarDom(who,url){
 const me=who==="me";
 const sel=me?[".msg.me .ava","#mbox .post .who .ava.me",".fcover .favav .ava"]
            :[".msg:not(.me) .ava","#mbox .post .who .ava:not(.me)"];
 const nodes=document.querySelectorAll(sel.join(","));
 for(let i=0;i<nodes.length;i++){const el=nodes[i];if(el.__avApplied===url)continue;el.__avApplied=url;
  if(url){const img=el.querySelector("img");if(img)img.src=url;else el.innerHTML='<img src="'+url+'">'}
  else{const nm=me?(S.settings.myName||"我"):(S.settings.taName||"TA");el.textContent=nm.slice(0,1)}}}
/* ---- 池内点选立即更换（参考 mochi switchXxxFromLib：TA 侧掷 50% 邀请回应、其中 70% 同意；手动更换重置 1-8 小时计时） ---- */
function switchTaAvatar(src){const p=nickPool();if(!src||p.taAva.indexOf(src)<0)return;
 const before=S.assets.ava_ta||"";
 const inv=Math.random()*100<AV_INVITE_PROB,agree=Math.random()*100<AV_AGREE_PROB;
 const t=avTm("taAva");t.last=Date.now();t.next=String(1+Math.random()*7);t.hash=strHash(src);
 setAvatar("ta",src);save("misc");
 if(!inv){toast("头像已切换");sysMsg((S.settings.myName||"我")+" 更换了 "+(S.settings.taName||"TA")+" 的头像",src);return}
 if(agree){toast("TA 同意了你的换头像邀请");sysMsg((S.settings.taName||"TA")+" 同意了"+(S.settings.myName||"我")+"的换头像邀请",src);return}
 t.hash=strHash(before);setAvatar("ta",before);save("misc");
 sysMsg((S.settings.taName||"TA")+" 拒绝了"+(S.settings.myName||"我")+"的换头像邀请",src)}
function switchMyAvatar(src){const p=nickPool();if(!src||p.meAva.indexOf(src)<0)return;
 avTm("meAva").hash=strHash(src);setAvatar("me",src);save("misc");
 toast("头像已更换");sysMsg((S.settings.myName||"我")+" 更换了头像",src)}
function switchTaName(n){const p=nickPool();if(!n||p.taName.indexOf(n)<0)return;
 const before=S.settings.taName||"";
 const inv=Math.random()*100<AV_INVITE_PROB,agree=Math.random()*100<AV_AGREE_PROB;
 const t=avTm("taName");t.last=Date.now();t.next=String(1+Math.random()*7);
 if(inv&&!agree){t.hash=strHash(before);save("misc");syncAvSheet();sysMsg("TA 拒绝了我的换昵称邀请，昵称保持不变",null,true);return}
 applyTaNick(n);t.hash=strHash(n);save("misc");
 if(inv){toast("TA 同意了你的换昵称邀请");sysMsg("TA 同意了我的换昵称邀请，昵称换成了「"+(S.settings.taName||"TA")+"」",null,true)}
 else{toast("昵称已切换");sysMsg("我把 TA 的聊天昵称换成了「"+n+"」",null,true)}}
function switchMyName(n){const p=nickPool();if(!n||p.meName.indexOf(n)<0)return;
 applyMyNick(n);avTm("meName").hash=strHash(n);save("misc");
 toast("昵称已更换");sysMsg("我把自己的聊天昵称换成了「"+n+"」",null,true)}
/* ---- TA 主动给我换头像 / 昵称：锁定邀请弹窗（附预览，同意才换、拒绝保持原样） ---- */
function avInviteSheet(title,bodyHtml,onOk,onNo){openSheet('<div class="mtitle">'+esc(title)+'</div>'+bodyHtml+'<div class="btnrow center" style="margin-top:14px"><button class="btn" data-r="0">拒绝</button><button class="btn pri" data-r="1">同意</button></div>',true);
 $("#modal .sheet").onclick=e=>{const b=e.target.closest("[data-r]");if(!b)return;closeModal();if(b.dataset.r==="1")onOk();else if(onNo)onNo()}}
function showMeAvatarInvite(data){const ta=S.settings.taName||"TA",myN=S.settings.myName||"我";
 notifyTA(ta+" 想给你换头像");
 const rad=(S.settings.chat.avaShape==="circle")?"50%":"12px";
 avInviteSheet(ta+" 的换头像邀请",'<div class="muted" style="text-align:center">'+esc(ta)+" 邀请你换上这张头像</div>"+'<img src="'+data+'" style="display:block;width:96px;height:96px;object-fit:cover;border-radius:'+rad+';margin:10px auto">',
  ()=>{avTm("meAva").hash=strHash(data);setAvatar("me",data);save("misc");sysMsg(myN+" 同意了"+ta+"的换头像邀请",data)},
  ()=>{sysMsg(myN+" 拒绝了"+ta+"的换头像邀请")})}
function showMeNickInvite(n){n=cleanNick(n);if(!n)return;const ta=S.settings.taName||"TA";
 notifyTA(ta+" 想给你换昵称");
 avInviteSheet(ta+" 的换昵称邀请",'<div class="muted" style="text-align:center">'+esc(ta)+" 邀请你换上这个昵称</div>"+'<div style="font-size:20px;font-weight:700;text-align:center;margin:10px 0 2px;word-break:break-all">'+esc(n)+"</div>",
  ()=>{applyMyNick(n);avTm("meName").hash=strHash(n);save("misc");sysMsg("我同意了 TA 的换昵称邀请，我的昵称换成了「"+n+"」",null,true)},
  ()=>{sysMsg("我拒绝了 TA 的换昵称邀请，昵称保持不变",null,true)})}
/* ---- 四个独立定时器（参考 mochi：60 秒轮询 + 启动立即检查；last/next=0 首跑即换一次；随机到当前值跳过且不推进计时） ---- */
function avCheck(k){try{if(!avEn()[k])return;
 const t=avTm(k),now=Date.now();let last=+t.last||0,next=+t.next||0;
 if(last>now||last<0||isNaN(last)){last=0;next=0}
 if((now-last)/36e5<next)return;
 const p=nickPool();
 if(k==="taAva"||k==="meAva"){
  const lib=k==="taAva"?p.taAva:p.meAva;if(!lib.length)return;
  const data=pick(lib);if(!data)return;
  const curUrl=k==="taAva"?(S.assets.ava_ta||""):(S.assets.ava_me||"");
  if(data===curUrl)return;
  if(t.hash&&strHash(data)===t.hash)return;
  const inv=k==="meAva"&&Math.random()*100<AV_INVITE_PROB;
  if(inv&&sheetOpen())return;
  t.last=now;t.next=String(1+Math.random()*7);save("misc");
  if(k==="taAva"){t.hash=strHash(data);save("misc");setAvatar("ta",data);sysMsg((S.settings.taName||"TA")+" 更换了头像",data)}
  else if(inv)showMeAvatarInvite(data);
  else{t.hash=strHash(data);save("misc");setAvatar("me",data);const tx=(S.settings.taName||"TA")+" 更换了你的头像";sysMsg(tx,data);toast(tx)}}
 else{
  const lib=k==="taName"?p.taName:p.meName;if(!lib.length)return;
  const n=pick(lib);if(!n)return;
  const curN=k==="taName"?(S.settings.taName||"TA"):(S.settings.myName||"我");
  if(n===curN)return;
  if(t.hash&&strHash(n)===t.hash)return;
  const inv=k==="meName"&&Math.random()*100<AV_INVITE_PROB;
  if(inv&&sheetOpen())return;
  t.last=now;t.next=String(1+Math.random()*7);save("misc");
  if(k==="taName"){applyTaNick(n);t.hash=strHash(n);save("misc");sysMsg("TA 把聊天昵称换成了「"+n+"」",null,true)}
  else if(inv)showMeNickInvite(n);
  else{applyMyNick(n);t.hash=strHash(n);save("misc");const tx="TA 把我的聊天昵称换成了「"+n+"」";sysMsg(tx,null,true);toast(tx)}}
}catch(e){}}
function avTick(){["taAva","meAva","taName","meName"].forEach(avCheck)}
/* ---- 两级面板（参考 mochi avlib：上排换什么 头像/昵称，下排页签换谁的 TA/我的，四个 pane 各带池子 + 空态 + 开关） ---- */
let avPanel=false,avKind="avatar",avOwner="ta";
function avPaneAva(who){const p=nickPool(),arr=who==="me"?p.meAva:p.taAva,en=avEn();
 const cur=who==="me"?(S.assets.ava_me||""):(S.assets.ava_ta||"");
 return '<div class="stkgrid">'+arr.map((u,i)=>'<div class="cell'+(u===cur?" on":"")+'" data-act="an-use-ava" data-who="'+who+'" data-i="'+i+'"><img src="'+u+'"><button class="del" data-act="an-del-ava" data-who="'+who+'" data-i="'+i+'">×</button></div>').join("")+"</div>"+
  (arr.length?"":'<div class="muted" style="padding:2px 0 8px">还没有头像，点击下方按钮添加</div>')+
  '<div class="btnrow" style="margin-top:14px"><button class="btn sm" style="flex:1" data-act="an-up" data-who="'+who+'">＋ 添加头像</button><button class="btn sm danger" style="flex:1" data-act="an-clear" data-k="'+who+'Ava" '+(arr.length?"":"disabled")+'>清空头像池</button></div>'+
  '<div class="row" style="border:none;margin-top:6px"><span class="lab">'+(who==="ta"?"TA 随机更换头像":"TA 主动给我换头像")+'<br><span class="sub">每隔 1-8 小时随机换一次'+(who==="ta"?"":"；直接换或弹窗征求你同意")+'</span></span><label class="sw"><input type="checkbox" data-act="an-en" data-k="'+who+'Ava" '+(en[who+"Ava"]?"checked":"")+"><i></i></label></div>"}
function avPaneName(who){const p=nickPool(),arr=who==="me"?p.meName:p.taName,en=avEn();
 const cur=who==="me"?(S.settings.myName||"我"):(S.settings.taName||"TA");
 return (arr.length?'<div class="chips" style="margin-bottom:8px">'+arr.map(n=>'<span class="tagwrap"><button class="chip'+(n===cur?" on":"")+'" data-act="an-use-name" data-who="'+who+'" data-n="'+esc(n)+'">'+esc(n)+'</button><button class="tagx" data-act="an-del-name" data-who="'+who+'" data-n="'+esc(n)+'">×</button></span>').join("")+"</div>":'<div class="muted" style="padding:2px 0 8px">还没有昵称，点击下方按钮添加</div>')+
  '<div class="btnrow" style="margin-top:14px"><button class="btn sm" style="flex:1" data-act="an-name-add" data-who="'+who+'">＋ 添加昵称</button><button class="btn sm danger" style="flex:1" data-act="an-clear" data-k="'+who+'Name" '+(arr.length?"":"disabled")+'>清空昵称池</button></div>'+
  '<div class="row" style="border:none;margin-top:6px"><span class="lab">'+(who==="ta"?"TA 随机更换昵称":"TA 主动给我换昵称")+'<br><span class="sub">每隔 1-8 小时随机换一次'+(who==="ta"?"":"；直接换或弹窗征求你同意")+'</span></span><label class="sw"><input type="checkbox" data-act="an-en" data-k="'+who+'Name" '+(en[who+"Name"]?"checked":"")+"><i></i></label></div>"}
function avNickPanelHtml(){const p=nickPool(),nameKind=avKind==="name";
 const taN=S.settings.taName||"TA",myN=S.settings.myName||"我";
 const cnt=k=>(k==="taAva"?p.taAva:k==="meAva"?p.meAva:k==="taName"?p.taName:p.meName).length;
 const cntOf=w=>cnt(w==="ta"?(nameKind?"taName":"taAva"):(nameKind?"meName":"meAva"));
 const tabN=w=>esc(w==="ta"?taN:myN)+(nameKind?" 的昵称库":" 的头像库")+"（"+cntOf(w)+"）";
 return '<div class="pathead"><span class="t">头像和昵称 · '+esc(taN)+'</span><button class="ibtn" data-r="x" title="关闭">'+ico("close")+"</button></div>"+
  '<div class="avbody">'+
  '<div class="patnav" style="padding:8px 14px 0">'+[["avatar","头像"],["name","昵称"]].map(k=>'<button class="chip'+(avKind===k[0]?" on":"")+'" data-avk="'+k[0]+'">'+k[1]+"</button>").join("")+"</div>"+
  '<div class="patnav" style="padding:5px 14px">'+[["ta",tabN("ta")],["me",tabN("me")]].map(t=>'<button class="chip'+(avOwner===t[0]?" on":"")+'" data-avo="'+t[0]+'">'+t[1]+"</button>").join("")+"</div>"+
  '<div style="padding:8px 14px 0">'+(nameKind?(avOwner==="ta"?avPaneName("ta"):avPaneName("me")):(avOwner==="ta"?avPaneAva("ta"):avPaneAva("me")))+"</div>"+
  '<div class="muted" style="padding:6px 16px 12px">头像池点图即换、昵称池点名字即换；开关打开后 TA 每隔 1-8 小时随机换一次（换我的会直接换或弹窗征求同意）。</div></div>'}
function bindAvSheet(sh){if(!sh)return;sh.classList.add("panelsheet","patsheet","avsheet");sh.onclick=e=>{if(e.target.closest("[data-r]")){avPanel=false;closeModal()}
  const kb=e.target.closest("[data-avk]"),ob=e.target.closest("[data-avo]");
  if(kb){avKind=kb.dataset.avk;syncAvSheet();return}
  if(ob){avOwner=ob.dataset.avo;syncAvSheet()}}}
function openAvNick(){avPanel=true;const sh=openSheet(avNickPanelHtml());sh.style.animation="";bindAvSheet(sh)}
/* 面板打开时，任何 render() 都同步刷新面板内容（面板内的操作按钮仍走 ACT） */
function syncAvSheet(){if(!avPanel)return;let sh=document.querySelector("#modal .sheet");
 const wasOpen=!!(sh&&sh.classList.contains("avsheet"));
 const keep=sh&&sh.querySelector(".avbody")?sh.querySelector(".avbody").scrollTop:0;
 /* 被 prompt/confirm 关掉后自动回到面板（不再退回聊天页） */
 if(!wasOpen)sh=openSheet(avNickPanelHtml());
 sh.innerHTML=avNickPanelHtml();bindAvSheet(sh);
 /* 重新同步时不播「从下往上」的入场动画：面板原地固定不动 */
 sh.style.opacity="1";sh.style.transform="none";
 if(keep){const b=sh.querySelector(".avbody");if(b)b.scrollTop=keep}
 const m=document.querySelector("#modal");if(m&&!m.classList.contains("on"))m.className="on"}
ACT["an-use-ava"]=el=>{const p=nickPool();const u=(el.dataset.who==="me"?p.meAva:p.taAva)[+el.dataset.i];if(!u)return;
 if(el.dataset.who==="me")switchMyAvatar(u);else switchTaAvatar(u)};
ACT["an-del-ava"]=el=>{const p=nickPool();const arr=el.dataset.who==="me"?p.meAva:p.taAva;const i=+el.dataset.i;if(i>=0&&i<arr.length)arr.splice(i,1);save("misc");syncAvSheet()};
ACT["an-up"]=el=>{const who=el.dataset.who;pickFile("image/*",true,fs=>{if(!fs.length)return;
 let ok=0,fail=0,done=0;const added=[];
 const step=okF=>{if(okF)ok++;else fail++;done++;if(done<fs.length)return;
  const p=nickPool();const arr=who==="me"?p.meAva:p.taAva;added.forEach(u=>arr.push(u));save("misc");syncAvSheet();
  toast(ok>0&&fail===0?"成功添加 "+ok+" 张头像":ok>0?"添加成功 "+ok+" 张，失败 "+fail+" 张":"添加失败，请选择有效的图片文件")};
 fs.forEach(f=>{readAsDataURL(f).then(u=>compressImage(u,256,.85)).then(c=>{added.push(c);step(true)}).catch(()=>step(false))})})};
ACT["an-clear"]=el=>{const k=el.dataset.k;confirmDlg(k.indexOf("Name")>=0?"清空昵称池？":"清空头像池？","清除",true).then(ok=>{if(!ok){syncAvSheet();return}nickPool()[k]=[];save("misc");syncAvSheet();toast("已清空")})};
ACT["an-name-add"]=async el=>{const who=el.dataset.who;const v=await promptDlg("添加昵称","",true);syncAvSheet();if(v==null)return;
 const raw=String(v).split(/\r\n|\r|\n|\u2028|\u2029|\u0085/);const lines=raw.map(cleanNick).filter(Boolean);
 const blank=raw.length-lines.length;
 if(!lines.length)return toast("没有可添加的昵称（都是空行或只有不可见字符）");
 const p=nickPool();const list=who==="me"?p.meName:p.taName;let dup=0;
 lines.forEach(n=>{if(list.indexOf(n)>=0){dup++;return}list.push(n)});
 const added=lines.length-dup;if(!added)return toast(dup>1?"这 "+dup+" 个昵称都已经在池子里了":"这个昵称已经在池子里了");
 save("misc");syncAvSheet();
 const tail=(dup?"，"+dup+" 个已存在":"")+(blank?"，跳过 "+blank+" 个空行":"");
 toast(dup||blank?"已添加 "+added+" 个昵称"+tail:added>1?"已添加 "+added+" 个昵称":"已添加昵称「"+lines[0]+"」")};
ACT["an-use-name"]=el=>{const n=el.dataset.n;if(el.dataset.who==="me")switchMyName(n);else switchTaName(n)};
ACT["an-del-name"]=el=>{const p=nickPool();const arr=el.dataset.who==="me"?p.meName:p.taName;const i=arr.indexOf(el.dataset.n);if(i>=0)arr.splice(i,1);save("misc");syncAvSheet()};
ACT["an-en"]=el=>{avEn()[el.dataset.k]=el.checked;save("misc")};
ACT["voice-toggle"]=()=>{toggleVoicePerm();render()};
ACT["voice-record"]=()=>{if(mediaRec&&mediaRec.state==="recording"){mediaRec.stop();mediaRec=null;render();return}if(!S.settings.chat.voice){voicePermDialog();return}startRecord();setTimeout(()=>render(),200)};
function applyFont(){const st=document.documentElement.style;const f=S.settings.appFont,file=S.assets.app_font;let ff=document.getElementById("appfont");
 const setFace=src=>{if(!ff){ff=document.createElement("style");ff.id="appfont";document.head.appendChild(ff)}ff.textContent='@font-face{font-family:"XJApp";src:url("'+src+'")}';st.setProperty("--app-font",'"XJApp",-apple-system,"PingFang SC","Microsoft YaHei",sans-serif')};
 if(file&&(!f||f==="__file__")){setFace(file);return}
 if(ff)ff.textContent="";
 if(f&&f!=="__file__"){const isUrl=/^https?:\/\//i.test(f)||/^data:/i.test(f)||/\.(ttf|otf|woff2?|eot)(\?|#|$)/i.test(f);if(isUrl)setFace(f);else st.setProperty("--app-font",'"'+f.replace(/"/g,"")+'",-apple-system,"PingFang SC","Microsoft YaHei",sans-serif');return}
 st.removeProperty("--app-font")}
ACT["chat-export"]=()=>exportKeys(["chats"],"聊天记录_"+dayKey(Date.now())+".json");
ACT["chat-import"]=()=>pickFile("application/json,.json",false,fs=>readAsText(fs[0]).then(t=>{try{const o=JSON.parse(t);restoreVal("chats",o.chats||o).then(v=>{S.chats=S.chats.concat(v);save("chats");render();toast("导入完成")})}catch(e){toast("文件解析失败")}}));
ACT["chat-clear"]=()=>confirmDlg("清除全部聊天数据？此操作不可恢复","清除",true).then(ok=>{if(!ok)return;S.chats=[];save("chats");render();toast("已清除")});
let voiceAudio=null,voicePlayingId=null;
function updateVoiceIcons(){document.querySelectorAll(".voice[data-id]").forEach(el=>{el.classList.toggle("playing",el.dataset.id===voicePlayingId)})}
function stopVoiceAudio(){if(voiceAudio){try{voiceAudio.pause()}catch(e){}}voiceAudio=null;voicePlayingId=null;updateVoiceIcons()}
function toggleVoicePlay(id,data){if(!data)return;
 if(voicePlayingId===id&&voiceAudio){stopVoiceAudio();return}
 stopVoiceAudio();
 voiceAudio=new Audio(mediaUrl(data,"v"+id));
 voicePlayingId=id;updateVoiceIcons();
 voiceAudio.onloadedmetadata=function(){try{const d=Math.round(voiceAudio.duration||0);
  if(d>0){const t=document.querySelector('.feedvoice[data-id="'+id+'"] .fv-dur');if(t)t.textContent=d+"″"}}catch(e){}};
 voiceAudio.onended=()=>{voicePlayingId=null;voiceAudio=null;updateVoiceIcons()};
 try{voiceAudio.play().catch(()=>{voicePlayingId=null;voiceAudio=null;updateVoiceIcons()})}catch(e){voicePlayingId=null;voiceAudio=null;updateVoiceIcons()}}
ACT["play-voice"]=el=>{const id=el.dataset.id;
 /* 媒体可能已拆成独立记录：先按需读出来再播 */
 const _p=function(owner,obj,slot,field){if(!obj)return false;
  if(mediaHas(obj,field)){mediaLoad(owner,obj.id||id,slot,obj,field).then(function(u){if(u)toggleVoicePlay(id,u)});return true}
  return false};
 if(_p("m",S.chats.find(function(x){return x.id===id}),"d","data"))return;
 if(_p("f",S.moments.find(function(x){return x.id===id}),"v","voiceData"))return;
 if(_p("c",S.cards.find(function(x){return x.id===id}),"d","data"))return;
 for(const _p2 of S.moments){const _cm=(_p2.cmts||[]).find(function(x){return x.id===id});if(_p("mc",_cm,"v","voiceData"))return}
};
ACT["call-start"]=callStart;
ACT["call-accept"]=answerCall;
ACT["call-reject"]=rejectCall;
ACT["call-end"]=userHangup;
ACT["call-min"]=callMinimize;
ACT["call-restore"]=callRestore;
ACT["open-rp"]=el=>openTransfer(el.dataset.id);
ACT["letter-new"]=()=>letterEditOpen("write");
