ACT["period-day"]=el=>{const ds=el.dataset.d;
 const rec=periodRecOn(ds),l0=(rec&&rec.log)||{};
 const draft={flow:l0.flow||"",sym:(l0.sym||[]).slice(),mood:l0.mood||""};
 const chips=function(kind,list,cur){return '<div class="chips">'+list.map(function(v){const on=kind==="sym"?(cur||[]).indexOf(v)>=0:(cur||"")===v;
  return '<button class="chip'+(on?" on":"")+'" data-plk="'+kind+'" data-v="'+v+'">'+v+"</button>"}).join("")+"</div>"};
 const sh=openSheet('<div class="mtitle">'+esc(ds)+'<button class="ibtn" data-r="x">'+ico("close")+'</button></div>'+
  '<div class="btnrow"><button class="btn" data-pd="start" style="flex:1">这天是经期开始</button><button class="btn" data-pd="end" style="flex:1">这天是经期结束</button></div>'+
  '<div class="sect" style="margin:12px 2px 4px">流量</div>'+chips("flow",PC_FLOWS,draft.flow)+
  '<div class="sect" style="margin:10px 2px 4px">症状 <span class="sub">可多选</span></div>'+chips("sym",PC_SYMS,draft.sym)+
  '<div class="sect" style="margin:10px 2px 4px">心情</div>'+chips("mood",PC_MOODS,draft.mood)+
  '<div class="btnrow" style="margin-top:12px"><button class="btn" data-pd="del" style="flex:1">删除记录</button><button class="btn pri" data-pd="save" style="flex:1">保存</button></div>',true);
 sh.onclick=function(e){
  const ch=e.target.closest("[data-plk]");
  if(ch){const kind=ch.dataset.plk,v=ch.dataset.v;
   if(kind==="sym"){const i=draft.sym.indexOf(v);if(i>=0)draft.sym.splice(i,1);else draft.sym.push(v)}
   else draft[kind]=(draft[kind]===v?"":v);
   sh.querySelectorAll('[data-plk="'+kind+'"]').forEach(function(b){const on=kind==="sym"?draft.sym.indexOf(b.dataset.v)>=0:draft[kind]===b.dataset.v;b.classList.toggle("on",on)});
   return}
  const b=e.target.closest("[data-pd]");
  if(!b){if(e.target.closest("[data-r]"))closeModal();return}
  const op=b.dataset.pd;closeModal();
  if(op==="start"){S.periods.push({id:uid(),start:ds+"T00:00:00",end:null,log:draft});toast("已标记经期开始")}
  else if(op==="end"){const open=S.periods.filter(function(r){return !r.end}).sort(function(a,b){return String(b.start).localeCompare(String(a.start))})[0];
   if(!open){toast("没有进行中的记录");return}open.end=ds+"T00:00:00";open.log=draft;toast("已标记经期结束")}
  else if(op==="del"){S.periods=S.periods.filter(function(r){return String(r.start||"").slice(0,10)!==ds});toast("已删除这天的记录")}
  else{const r2=periodRecOn(ds);if(r2){r2.log=draft;toast("已保存记录")}else{S.periods.push({id:uid(),start:ds+"T00:00:00",end:ds+"T00:00:00",log:draft});toast("已记录这天")}}
  save("periods");render();try{periodCareCheck()}catch(e2){}}};
