ACT["lib-bulk"]=()=>{const cat=curParam;if(CATTYPE(cat)!=="text"){pickFile(CATTYPE(cat)==="img"?"image/*":"audio/*",true,fs=>addFiles(cat,fs));return}openSheet('<div class="mtitle">批量导入（每行一条）<button class="ibtn" data-r="x">'+ico("close")+'</button></div><textarea id="bi" style="min-height:160px"></textarea><div class="btnrow center" style="margin-top:12px"><button class="btn" data-act="bulk-file" style="background:transparent;border:1px solid var(--line)">从文件导入</button></div><div class="btnrow center" style="margin-top:10px"><button class="btn" data-r="x">取消</button><button class="btn pri" data-r="ok">导入</button></div>',true);$("#modal .sheet").onclick=e=>{const b=e.target.closest("[data-r]");if(!b)return;const lines=$("#bi").value.split("\n").map(s=>s.trim()).filter(Boolean);closeModal();if(b.dataset.r!=="ok"||!lines.length)return;const g=(S.misc.gf||{})[cat]||"";lines.forEach(l=>S.cards.push({id:uid(),cat,type:"text",content:l,group:g}));save("cards");libRefresh(cat);toast("已导入 "+lines.length+" 条")}};
function addFiles(cat,fs){const g=(S.misc.gf||{})[cat]||"";if(CATTYPE(cat)==="img"){Promise.all(fs.map(f=>readAsDataURL(f).then(u=>compressImage(u,1024,.82)))).then(rs=>{rs.forEach(u=>S.cards.push({id:uid(),cat,type:"img",data:u,group:g}));save("cards");libRefresh(cat);toast("已导入 "+rs.length+" 张")})}else{fs.forEach(f=>S.cards.push({id:uid(),cat,type:"voice",data:f,name:f.name,dur:2,group:g}));save("cards");libRefresh(cat);toast("已导入 "+fs.length+" 条语音")}}
