ACT["lib-block-menu"]=()=>{const cat=curParam;const groups=S.misc.groups[cat]||[];S.misc.blockGroups=S.misc.blockGroups||{};
 if(!groups.length)return toast("暂无分组；可点每条字卡右侧的屏蔽按钮单独屏蔽");
 const bg=()=>S.misc.blockGroups[cat]||[];
 const body=()=>'<div class="mtitle"><span class="mtt">屏蔽分组（整组字卡）</span><button class="ibtn" data-bclose="1" title="关闭">'+ico("close")+'</button></div>'+
  groups.map((g,i)=>'<button class="row listbtn" data-bg="'+i+'" style="border:none;background:none"><span class="lt">'+esc(g)+'</span><span class="lv"><span class="checkcircle'+(bg().indexOf(g)>=0?" on":"")+'">'+(bg().indexOf(g)>=0?ico("check"):"")+"</span></span></button>").join("")+
  '<div class="muted" style="margin-top:10px">可多选；勾选后该分组整组字卡会被屏蔽，点右上角 ✕ 关闭</div>';
 const sh=openSheet(body());
 $("#modal").classList.add("stick");
 sh.onclick=e=>{
  if(e.target.closest("[data-bclose]")){closeModal();return}
  const b=e.target.closest("[data-bg]");if(!b)return;
  const g=groups[+b.dataset.bg];const arr=S.misc.blockGroups[cat]=S.misc.blockGroups[cat]||[];const k=arr.indexOf(g);if(k>=0)arr.splice(k,1);else arr.push(g);
  save("misc");sh.innerHTML=body();libRefresh(cat);toast(k>=0?"已取消屏蔽「"+g+"」":"已屏蔽「"+g+"」")};
};
/* 从文件导入：读取文本/JSON 填入输入框，再点「导入」入库 */
function bulkLinesFromText(t){t=String(t||"").trim();if(!t)return [];
 try{const o=JSON.parse(t);const arr=Array.isArray(o)?o:(o&&Array.isArray(o.cards)?o.cards:(o&&o.data&&Array.isArray(o.data.cards)?o.data.cards:null));
  if(arr)return arr.map(c=>typeof c==="string"?c:(c&&typeof c.content==="string"?c.content:"")).map(s=>s.trim()).filter(Boolean)}catch(e){}
 return t.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)}
ACT["bulk-file"]=()=>pickFile("application/json,.json,.txt,text/plain",false,fs=>{if(!fs||!fs[0])return;readAsText(fs[0]).then(t=>{const lines=bulkLinesFromText(t);if(!lines.length)return toast("文件里没有可导入的内容");const ta=$("#bi");if(ta)ta.value=(ta.value.trim()?ta.value.replace(/\s+$/,"")+"\n":"")+lines.join("\n");toast("已读取 "+lines.length+" 条，点「导入」完成")})});
ACT["lib-import-cat"]=()=>{const cat=curParam;pickFile("application/json,.json,text/plain",false,function(fs){
 if(!fs||!fs[0])return;
 readAsText(fs[0]).then(function(t){
  let o=null;try{o=JSON.parse(t)}catch(e){return toast("不是有效的 JSON 文件")}
  let list=null;
  const mk=mochiItems(o);
  if(mk)list=mk.filter(function(x){return x.cat===cat||CATTYPE(x.cat)===CATTYPE(cat)});
  if(!list){
   const arr=Array.isArray(o)?o:(Array.isArray(o&&o.cards)?o.cards:(o&&o.data&&Array.isArray(o.data.cards)?o.data.cards:null));
   if(arr)list=arr.filter(function(c){return c&&typeof c==="object"})}
  if(!list||!list.length)return toast("文件里没有能导入「"+cat+"」的字卡");
  shrinkImportImages(list,480,function(){
   let n=0;const gs={};
   list.forEach(function(c){
    const o2={};Object.keys(c).forEach(function(k){if(k!=="_u")o2[k]=c[k]});
    o2.cat=cat;if(!o2.type)o2.type=CATTYPE(cat);
    if(!o2.id||S.cards.some(function(x){return x.id===o2.id}))o2.id=uid();
    if(o2.group===undefined)o2.group="";
    if(o2.group)gs[o2.group]=1;
    S.cards.push(o2);n++});
   S.misc.groups=S.misc.groups||{};S.misc.groups[cat]=S.misc.groups[cat]||[];
   Object.keys(gs).forEach(function(g){if(S.misc.groups[cat].indexOf(g)<0)S.misc.groups[cat].push(g)});
   if(CATS.indexOf(cat)<0)CATS.push(cat);
   save("cards");save("misc");libRefresh(cat);
   const gk=Object.keys(gs);
   toast("已导入 "+n+" 条到「"+cat+"」"+(gk.length?(" · 分组 "+gk.length+" 个"):""))})})})};
ACT["lib-export-cat"]=()=>{const cat=curParam;(async()=>{try{
 const items=cardsOf(cat).map(function(c){const c2=Object.assign({},c);delete c2._u;return c2});
 if(!items.length)return toast("这个分类还没有内容");
 const out=[];for(const c of items){const c2=Object.assign({},c);if(c2.data instanceof Blob)c2.data=await blobToDataUrl(c2.data);out.push(c2)}
 download("字卡_"+cat+"_"+dayKey(Date.now())+".json",JSON.stringify({app:"xingjian",ver:1,cat:cat,data:{cards:out}}));
 toast("已导出 "+out.length+" 条");
 }catch(e){toast("导出失败："+(e&&e.message||e))}})()};
ACT["lib-export-all"]=()=>exportKeys(["cards"],"字卡库全部.json");
/* ================= mochi 字卡库适配 + 导入压缩 ================= */
const MOCHI_MAP={text:"主字卡",kaomoji:"颜文字",emoji:"Emoji",image:"表情包",sticker:"表情包",stk:"表情包",voice:"语音字卡",poke:"拍一拍",pat:"拍一拍",interact:"情绪字卡",intent:"情绪字卡",music:"音乐",period:"经期",cjian:"主字卡",mjfree:"自由字卡",room:"房间",water:"水",fish:"鱼",garden:"花园",eat:"吃饭",piggy:"存钱",drift:"漂流",reach:"触碰",sync:"同步"};
/* 单条：纯 dataURL / http 链接都算图片；对象取 content / data */
function mochiVal(c){if(typeof c==="string")return /^(data:|https?:|blob:)/.test(c)?{d:c}:{s:c};
 if(c&&typeof c==="object")return {s:(c.content||c.text||c.name||""),d:(c.data||c.img||c.url||"")};return {}}
/* 解析 mochi 字卡库导出：{text:[],kaomoji:[],emoji:[],sticker:[["分组名",[图片…]],…]} */
function mochiItems(o){
 if(!o||typeof o!=="object"||Array.isArray(o))return null;
 const keys=Object.keys(o).filter(function(k){return MOCHI_MAP[k]&&Array.isArray(o[k])});
 if(!keys.length)return null;
 const items=[];
 const add=function(cat,group,content,data){
  if(data){items.push({cat:cat,type:"img",data:String(data),group:group||""});return}
  const c=String(content==null?"":content).trim();if(!c)return;
  items.push({cat:cat,type:CATTYPE(cat),content:c,group:group||""})};
 keys.forEach(function(k){const cat=MOCHI_MAP[k],v=o[k];
  if(!Array.isArray(v))return;
  v.forEach(function(row){
   if(Array.isArray(row)&&row.length>=2&&Array.isArray(row[1])){
    const g=String(row[0]==null?"":row[0]);
    row[1].forEach(function(c){const x=mochiVal(c);if(x.d)add(cat,g,"",x.d);else add(cat,g,x.s)})}
   else{const x=mochiVal(row);if(x.d)add(cat,"","",x.d);else add(cat,"",x.s)}})});
 return items.length?items:null}
/* 导入过大图片时自动压到最长边 maxW（并发 4，避免一次性解码太多图爆内存） */
function shrinkImportImages(items,maxW,cb){
 const big=items.filter(function(x){return x.type==="img"&&typeof x.data==="string"&&x.data.indexOf("data:")===0&&x.data.length>45000});
 if(!big.length)return cb(0);
 let i=0,done=0;const CONC=4;
 const next=function(){
  if(i>=big.length)return;
  const it=big[i++];
  compressImage(it.data,maxW||480,.82).then(function(u){it.data=u}).catch(function(){}).then(function(){done++;
   if(done===1||done%25===0||done===big.length)toast("正在压缩图片 "+done+"/"+big.length+"…");
   if(done===big.length)cb(big.length);else next()})};
 for(let k=0;k<Math.min(CONC,big.length);k++)next()}
ACT["lib-import-all"]=()=>pickFile("application/json,.json",false,fs=>{readAsText(fs[0]).then(function(t){
 let o=null;try{o=JSON.parse(t)}catch(e){}
 if(!o)return toast("不是有效的 JSON 文件");
 const items=[];
 const add=function(cat,group,content,data){
  if(data){items.push({cat:cat,type:"img",data:String(data),group:group||""});return}
  const c=String(content==null?"":content).trim();if(!c)return;
  items.push({cat:cat,type:CATTYPE(cat),content:c,group:group||""})};
 const val=function(c){if(typeof c==="string")return {s:c};if(c&&typeof c==="object")return {s:(c.content||c.text||c.name||""),d:(c.data||c.img||c.url||"")};return {}};
 // 1) 星笺自己的导出
 if(o.app==="xingjian"&&o.data&&Array.isArray(o.data.cards)){o.data.cards.forEach(function(c){if(!c||!c.cat)return;items.push(c)})}
 // 2) 语录 / 类似 {customReplies:[...]}
 else if(Array.isArray(o.customReplies)||Array.isArray(o.customPokes)||Array.isArray(o.customStatuses)||Array.isArray(o.customMottos)||Array.isArray(o.customIntros)||Array.isArray(o.customEmojis)){
  if(Array.isArray(o.customReplies))o.customReplies.forEach(function(x){add("主字卡","语录",x)});
  if(Array.isArray(o.customPokes))o.customPokes.forEach(function(x){add("拍一拍","",x)});
  if(Array.isArray(o.customStatuses))o.customStatuses.forEach(function(x){add("状态","",x)});
  if(Array.isArray(o.customMottos))o.customMottos.forEach(function(x){add("主字卡","座右铭",x)});
  if(Array.isArray(o.customIntros))o.customIntros.forEach(function(x){add("主字卡","自我介绍",x)});
  if(Array.isArray(o.customEmojis))o.customEmojis.forEach(function(x){add("Emoji","",x)});
 }
 // 3) mochi 字卡库导出：{text:[],kaomoji:[],emoji:[],sticker:[["组",[图片…]],…]}
 else{const mk=mochiItems(o);if(mk)mk.forEach(function(x){items.push(x)})}
 if(!items.length)return toast("这个文件里没有能识别的字卡");
 const by={};items.forEach(function(c){by[c.cat]=(by[c.cat]||0)+1});
 const desc=Object.keys(by).map(function(k){return k+" "+by[k]+" 条"}).join("、");
 shrinkImportImages(items,480,function(){
 actionSheet("识别到 "+items.length+" 条字卡："+desc,["合并导入（跳过重复）","清空后导入"]).then(function(i){
  if(i==null)return;
  if(i===1)S.cards=[];
  if(!S.misc.groups||typeof S.misc.groups!=="object")S.misc.groups={};
  let n=0;
  items.forEach(function(c){
   if(!c.cat)return;
   if(!S.misc.groups[c.cat])S.misc.groups[c.cat]=[];
   if(c.group&&S.misc.groups[c.cat].indexOf(c.group)<0)S.misc.groups[c.cat].push(c.group);
   if(CATS.indexOf(c.cat)<0)CATS.push(c.cat);
   const dup=S.cards.some(function(x){return x.cat===c.cat&&(c.type==="img"?(x.data===c.data):(String(x.content||"")===String(c.content||""))) });
   if(dup)return;
   S.cards.push({id:uid(),cat:c.cat,type:c.type||CATTYPE(c.cat),content:c.content||"",data:c.data||undefined,group:c.group||"",name:c.name||""});n++});
  save("cards");save("misc");closeModal();render();toast("已导入 "+n+" 条字卡（跳过重复 "+(items.length-n)+"）")});});
}).catch(function(){toast("读取文件失败")})});
