function pkToggle(el){const p=pkState();const want=el.checked;if(want===p.on)return;
 if(want){confirmDlg("开启「灵感拾取」后，已拾取的内容会重新进入对应的人物卡池，并继续从对话中拾取新内容。确定开启吗？","开启").then(ok=>{if(!ok){el.checked=false;return}p.on=true;pkSyncPool();save("pickup");save("cards");render();toast("已开启灵感拾取")})}
 else{confirmDlg("关闭「灵感拾取」后将停止拾取；已拾取的内容会保留，但不会进入人物卡池。确定关闭吗？","关闭",true).then(ok=>{if(!ok){el.checked=true;return}p.on=false;pkSyncPool();save("pickup");save("cards");render();toast("已关闭灵感拾取")})}}
